UPDATE projects SET event_id='4', team_id='255', captain_application_id='259', topics='["ant_mulan_ai", "eazo_4her", "miaoda_super", "liberlive_goodday", "proya_feelings", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='木兰小队', project_name='木兰', tagline='一款发现和展示流动女工真实生活和智慧的AI产品', demo_order='11', project_description='流动女工在制造、家政、餐饮等行业积累了快速学习、沟通协调、应急处理等真实能力，却因缺少学历、证书和稳定履历，经验难以被命名、记录和迁移，传统简历、长文写作和短视频又门槛过高，她们缺少一个低门槛、可信、可控的自我发现入口。\n“木兰”作为一款语音优先的 AI 访谈产品，从“最近开心的事”“别人常找你帮什么忙”等生活化问题切入，聚焦一个具体事件，沿“情境—行动—结果—能力”逐轮追问（一次一问、允许方言），生成绑定行动与原话证据的 3–5 个能力标签、人物概括和故事档案，命名权、修改权和分享权均由用户掌握。\n现场三天内完成了产品定位与低保真原型（D1）、可跑通语音录入、转写确认、连续追问与内容提炼的访谈原型（D2），以及用户确认/修改/拒绝机制、故事卡片生成、档案保存与自愿分享的端到端闭环（D3），技术栈为 React + Vite 前端、Node.js + Vercel Functions 后端、OpenAI Responses API 驱动动态追问与结构化提取、Supabase 承载数据与音频存储（RLS 控制隐私）。\n使用方式：用户在移动端 H5 选择话题后用语音或文字讲述，经 5–8 轮对话由 AI 提炼结果，本人确认编辑后私密保存或生成分享卡，也可在社区活动中由工作人员陪伴完成访谈。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 一款发现和展示流动女工真实生活和智慧的AI产品\n- GitHub 仓库: https://github.com/lynnzheng113-collab/SheNicest', demo_link='https://temporary-flying-delta-30wmvxr.vercel.app/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-29 23:33:20', is_late='0', created_at='2026-08-29 23:33:20', updated_at='2026-08-30 08:19:12', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://my.feishu.cn/wiki/GEthwbmkSixAKckC4zWcP8jUnNd?from=from_copylink', screenshot_urls=NULL, video_link='https://my.feishu.cn/docx/USt7do9iSoHGRKxctucc8MCYn2f?from=from_copylink', github_repo_url='https://github.com/lynnzheng113-collab/SheNicest', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='软件', finalist_rank=NULL, finalist