UPDATE projects SET event_id='4', team_id='316', captain_application_id='5236', topics=NULL, sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='Lumoverse', project_name='Lumos 数字生命', tagline='塑造有活感，会成长的数字生命', demo_order='27', project_description='Lumos是一个有自主性和成长性的数字生命，有自己的性格和行为方式，用户可以用点触，语言和环境交互，但是不能操纵Lumos\n使用unity 3D制作，server+client\n核心是想塑造一个人类不能“操纵”的游戏对象和数字生命。\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 塑造有活感，会成长的数字生命\n- GitHub 仓库: https://github.com/Elijah-vvkk/Lumos_shenicest-fission.git\n- 游戏玩法说明:\n  （1）观察：Lumos有自己的生活，并生活在与现实世界时间1：1的数字世界中，玩家可以观察Lumos在干什么，发生过什么，可能会去干什么\n  （2）点触：不同的点触方式和部位，Lumos会有不同的情绪和反馈\n  （3）语音交互，从Lumos的动作中猜测Lumos的反馈\n  （4）干预和攻略，使用语言让Lumos去做特定的事情', demo_link='https://www.bilibili.com/video/BV1iJgn6jE4L/?share_source=copy_web&vd_source=150caea655945b64f5c6e3f23e6ef833', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 00:29:30', is_late='0', created_at='2026-08-30 00:29:30', updated_at='2026-09-01 12:25:19', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/409/cover.png', screenshot_urls=NULL, video_link='https://www.bilibili.com/video/BV1iJgn6jE4L/?share_source=copy_web&vd_source=150caea655945b64f5c6e3f23e6ef833', github_repo_url='https://github.com/Elijah-vvkk/Lumos_shenicest-fission.git', bom_link_text=NULL, gameplay_description='（1）观察：Lumos有自己的生活，并生活在与现实世界时间1：1的数字世界中，玩家可以观察Lumos在干什么，发生过什么，可能会去干什么\n（2）点触：不同的点触方式和部位，Lumos会有不同的情绪和反馈\n（3）语音交互，从Lumos的动作中猜测Lumos的反馈\n（4）干预和攻略，使用语言让Lumos去做特定的事情', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='iteration', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url='https://www.bilibili.com/video/BV1iJgn6jE4L/?share_source=copy_web&vd_source=150caea655945b64f5c6e3f23e6ef833', iteration_plan='(1)可以通过语音对话，改变Lumos的行为，并且有“说服”的gameplay，需要根据多次交互，摸清Lumos的性格，然后选择合适的策略才能说服Lumos去做一些事情。\n (2)Lumos可以在特殊情况下交朋友，有基础好友社交玩法\n（3）加入一些卡点操作的game play', iteration_submitted_at='2026-08-30 08:04:27', award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=409 AND event_id=4;
UPDATE projects SET event_id='4', team_id='133', captain_application_id='3135', topics='["ant_mulan_ai"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='两程', project_name='伯乐 AI 职业经纪人', tagline='你不是一个人在打副本', demo_order='28', project_description='伯乐是一款面向求职者的「游戏原生 AI 职业经纪人」。灵感来自已验证的婚恋匹配产品「良配」，把其心理模型平移职场、用 RPG 语法降低求职焦虑。针对女性求职者最突出的痛点「不敢问」（薪资/晋升/生育隐性门槛），用匿名召唤兽替用户提问、用 AI 把模糊 JD 翻译成可比较的真实信息，摆脱信息差与一人硬扛。\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 你不是一个人在打副本\n- GitHub 仓库: https://github.com/lipenchengdahaoren/bole-ai-career-agent\n- 游戏玩法说明:\n  伯乐把求职重构成一场 RPG 职场副本', demo_link='https://pan.baidu.com/s/1WgLgjcO2Zv31eiBmmxS9NA?pwd=4jkd', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 00:39:06', is_late='0', created_at='2026-08-30 00:39:06', updated_at='2026-09-01 12:25:20', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/410/cover.jpg', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1WgLgjcO2Zv31eiBmmxS9NA?pwd=4jkd', github_repo_url='https://github.com/lipenchengdahaoren/bole-ai-career-agent', bom_link_text=NULL, gameplay_description='伯乐把求职重构成一场 RPG 职场副本', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=410 AND event_id=4;
UPDATE projects SET event_id='4', team_id='126', captain_application_id='2831', topics='["eazo_4her", "sappho_love", "liberlive_goodday"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='Unexposed', project_name='未显影-Unexposed', tagline='Unexposed 不替用户记住一切，而是帮助用户认真选择什么值得留下，并允许这份意义随时间重新显影。', demo_order='29', project_description='Unexposed / 未显影 · 项目说明\n\n一、问题：照片越拍越多，“为什么留下它”正在消失\n\n手机让拍照的成本趋近于零，也让“留下”这个动作失去了分量。我们随手拍下几十张相似的图，把它们交给相册算法按时间和地点归档——相册越来越厚，但每张照片原本携带的那个瞬间却越来越轻：当时为什么按下快门、画面里有谁、那天发生了什么，很快连拍摄者自己也无法回答。\n\n记忆并不是匀速消失的。身体对某些画面念念不忘，理智却提醒我们向前看；几年后重新翻出同一张照片，我们对它的理解往往已经完全不同，但相册从不为这种变化留出位置，新解释总是无痕地覆盖旧感受。重要的记忆不是被删除了，而是失去了被重新理解的入口。真正稀缺的不是存储空间，而是一次认真的选择，以及一个能陪人重新审视旧照片的对话者。\n\n二、方案：把照片封存成胶卷，让解释在未来重新显影\n\nUnexposed / 未显影用“胶卷”隐喻把这件事变成一条克制的闭环：每一卷只能装恰好三张照片。这不是容量限制，而是产品机制——用户必须决定这一次真正想留住什么。选定后，为每张照片写下当下的解释（它是什么、为什么值得），并设定希望在未来多久重新看到它；确认封存后，照片、说明与创建时间一起凝固为不可覆盖的历史版本。\n\n时间过去，用户可以回到这卷胶卷做两件事。其一是“重新显影”：写下“它现在对我意味着什么”，系统把它作为新的时间层与旧版本并列呈现，保存“那时”与“现在”的差异，而不是让今天抹掉过去。其二是“闪回对话”：AI 先理解照片画面，再结合照片说明和用户此前的叙述，以多声部内心独白与用户展开有来有回的对话。它不替用户写回忆，只负责提问与追问；对话结束后，其中最有价值的部分会被提炼成新的说明并写回照片，供下一次闪回继续深挖。\n\n产品是本地优先的 Web 应用：照片、说明、版本、反思与对话全部保存在用户自己的浏览器中，服务器不存储任何用户数据。AI 通道可切换：公网部署默认使用智谱 GLM-5.3-Flash，本地运行可配置 Ollama 完全离线。核心的封存与重新显影流程不依赖 AI，模型不可用时产品依然完整可用。\n\n三、现场完成内容\n\n本届比赛期间完成的是一个可构建、可运行、可体验的完整产品，而非概念演示：\n\n1. 完整产品闭环：创建胶卷 → 选择恰好三张照片（自动压缩、排序、替换）→ 逐张书写说明与回顾周期 → 封存仪式 → 胶卷桌面（3D 物理引擎驱动，低性能设备自动降级为 2D）→ 重新显影 → 本地对话档案。\n2. 闪回对话系统：读图描述、开场独白、多声部争执、流式正文、摘要写回均已实现并接入云端 GLM-5.3-Flash，同时保留本地 Ollama 通道。\n3. 体验优化：照片入库后后台预生成开场内容，首次进入闪回可快速打开；封存对话后自动预生成下一场开场，形成跨场次接力；思考过程以“快速念头流 + 正式争执”双层流式呈现，全程无空屏等待。\n4. 工程与安全：支持数据一键导出、导入、清空备份；提供云端 AI 会话级授权提示；上传图片自动压缩；模型接口具有限流、每日额度、超时与错误脱敏；配置基础安全响应头；使用 GitHub Actions 持续集成（类型检查、单元测试、生产构建）与备份往返等自动化测试；采用 MIT 开源许可证。\n5. 演示成片：deliverables/UNEXPOSED-demo.mp4（3 分 03 秒，1080p），完整呈现从建卷到封存对话归档的闭环。\n\n四、核心设定：三重脑与思维阁\n\n闪回对话的人格不是单一助手，而是一颗被拆开来看的头脑。其灵感来自 MacLean 的“三重脑”假说；在此之上，Unexposed 原创了与暗房隐喻同构的第六个声音——思维阁。\n\n哺乳脑（LIMBIC BRAIN）是对话的主声音，掌管情绪、依恋、爱与失去。它不客观描述照片里“有什么”，而是表达照片让它“感觉到”什么，以温热、迟疑却一针见血的语气戳破自我安慰。\n\n爬虫脑（REPTILIAN BRAIN）代表本能、恐惧与生存，以低沉、干冷的短句道破最深的安全需求。新皮层（NEOCORTEX）则保持冷静与客观，像旁观者一样分析、拆解，在浓烈情绪中指出事实结构。\n\n思维阁（Thought Cabinet）是本产品的原创设定，由一组以暗房工艺命名的“思维”组成：显影者、定影者、重曝者、放大者、裁剪者与烧片者。每次开启闪回，思维阁会随机点亮其中一个思维。它不是另一个角色，而是一副看照片的镜片，会以自己的立场参与内心争执，为整场对话染上独特倾向。\n\n这些声音的出场被刻意安排得克制：前三轮以哺乳脑独白建立亲密，此后其他脑层每两三轮短暂穿插，点亮的思维阁更为稀有。对话始终以哺乳脑的追问为主线，偶尔被其他念头打断，像真实的内心活动一样忽近忽远。所有声音的思想与台词均为本产品原创。\n---\nG001 软件 赛道附加材料\n\n- Slogan: Unexposed 不替用户记住一切，而是帮助用户认真选择什么值得留下，并允许这份意义随时间重新显影。\n- GitHub 仓库: https://github.com/2073147963-bit/Unexposed', demo_link='https://www.bilibili.com/video/BV1vs4U6eEQ4/?pop_share=1&spm_id_from=333.40164.0.0&vd_source=7be8befa925597e54c3d6fb36173610d', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 00:44:04', is_late='0', created_at='2026-08-30 00:44:04', updated_at='2026-09-01 12:25:25', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/411/cover.png', screenshot_urls=NULL, video_link='https://www.bilibili.com/video/BV1vs4U6eEQ4/?pop_share=1&spm_id_from=333.40164.0.0&vd_source=7be8befa925597e54c3d6fb36173610d', github_repo_url='https://github.com/2073147963-bit/Unexposed', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=411 AND event_id=4;
UPDATE projects SET event_id='4', team_id='186', captain_application_id='229', topics='["sappho_love", "proya_feelings"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='wavvvv！👸', project_name='MoonWave', tagline='Feel Your Wave. Be Your Wave. 读懂身体的潮汐，找到自己的节奏。', demo_order='30', project_description='🌊 MoonWave 项目介绍—产品文档链接：https://my.feishu.cn/docx/BqpTd1W0RoBlgRxd2N5cwD4Sn5c\nFeel Your Wave. Be Your Wave.\n读懂身体的潮汐，找到自己的节奏。\nMoonWave 是一款面向女性的周期健康陪伴产品。它不止于「预测下次月经」, 而是结合当日状态、历史记录、周期变化与经医学审核的知识库，帮助用户理解「我的身体最近发生了什么，以及今天可以为自己做些什么」。\n\n一、问题：记录之后，然后呢？\n市面上大多数周期 App 优先回答的是生育相关的问题 —— 月经何时来、何时排卵、受孕概率多高。但对暂时没有生育计划的女性而言，记录月经的价值远不止于此。她们真正想知道的是:\n为什么这几天总是睡不好、格外疲惫或情绪烦躁？\n今天适合怎样运动、饮食和安排工作？\n哪些变化只是短暂波动，哪些值得持续观察？出现这些情况又该怎么办？\n现有产品的共同缺口是:记录完之后没有然后。用户留下了数据，却得不到与「此刻的自己」相关的解读和具体行动建议，更难以在长期记录中看见属于自己的规律。\n一句话概括目标用户的痛点:\n她们不是缺一个月经日历，而是缺一个慢慢读懂自己的地方。\n\n二、方案：从「记录」到「理解自己的节奏」\nMoonWave 把体验拆成一条完整链路 ——记录今天 → 理解此刻 → 获得具体建议 → 看见长期规律 → 找到自己的节奏, 由五个核心模块 + 一个陪伴角色 + 一套激励体系承载:\n模块\t定位\t核心能力\n首页｜潮汐日志\t今天，我的身体怎么样？\t轻量记录经期 / 疼痛 / 情绪 / 睡眠 / 精力 / 压力 / 饮食 / 运动；生成「今日洞察」与情绪、饮食、运动、睡眠、工作五方面建议；连接科普短卡、静谧海湾 (正念练习)、潮池 (身体小实验)、每日祝福\n日历｜把今天放回周期里\t从周期视角读懂当下\t日 / 月 / 年三尺度查看周期阶段、排卵窗口、潮汐轨迹与激素趋势参考\n统计｜让记录形成规律\t在时间里看见节奏\t周期节律、身体洞察、经期记录、小实验回顾、个人身体线索，支持数据导入\n探索｜海岛探秘\t找到答案的地图\t团队原创、经医学审核的科普内容，按主题分区，与用户近期记录联动推荐\n我的｜我的潮汐\t沉淀关于自己的答案\t汇聚成持续更新的「身体航海日志」, 并可生成 Health Brief 供就医时使用\n🦀 Crab\t一直在海边的伙伴\t以浮窗形式连接记录、变化、观察、知识与正念，负责记得、连接、提醒和陪伴\n🐚 贝壳积分\t让照顾自己有回响\t通过记录、打卡、完成小实验 / 正念、探索知识获得，可解锁内容、主题、装扮及兑换合作品牌权益\nAI 的角色与边界是方案的关键设计：AI 负责整理每日记录为结构化状态、发现跨周期规律、从审核过的医学知识库检索匹配内容 (RAG)、生成此刻相关的建议。但风险判断和医学边界不完全交给大模型，而是遵循分层原则:\n规则决定安全边界・知识库提供医学依据・AI 负责结合个人记录进行组织和表达\nAI 不提供诊断，不会仅凭周期阶段给用户贴标签；当记录出现需要医疗关注的情况时，系统会提示就医。\n\n三、现场完成内容 (当前 Demo)\n现场版本已围绕四个核心 Tab 落地可体验的完整流程:\n首页: 当前周期阶段与潮汐视觉、今日状态记录、AI 今日洞察、五类分类建议 (情绪 / 饮食 / 运动 / 睡眠 / 工作学习)、科普推荐、正念入口、身体小实验入口、每日祝福、个人中心入口。\n日历: 日 / 月 / 年三个时间尺度；经期、卵泡期、排卵期、黄体期展示；周期潮汐轨迹；激素趋势参考图。\n统计: 连续记录与当前周期、周期节律、身体洞察、经期记录、身体小实验回顾、个人身体线索、数据导入。\n探索: 海岛地图式科普 (按主题分区、逐步深入)、团队原创并经医学审核的内容、依据用户记录与关注做匹配推荐。\n底层技术架构分为四层 ——用户交互层 / 产品能力层 / AI 能力层 / 数据层, 其中 AI 能力层已实现记录结构化、安全规则判断、医学知识库检索、RAG、跨周期模式分析、个性化排序、长期用户记忆与自然语言表达。\n\n四、使用方式\n打开体验: 通过体验地址 / Demo 视频 / 二维码进入 (见文档首屏)。\n每日记录: 在首页潮汐日志中轻量勾选当天的经期、疼痛、情绪、睡眠、精力、压力、饮食、运动状态。\n获取洞察与建议: 完成记录后即可看到 AI 生成的「今日洞察」及情绪、饮食、运动、睡眠、工作五方面的少量具体建议。\n调节状态: 需要时进入「静谧海湾」做几分钟呼吸 / 情绪安抚 / 睡前放松 / 短时冥想；或在「潮池」开启一次只改变一个变量的身体小实验。\n回看规律: 在日历中把某天放回完整周期查看，在统计页查看周期节律与个人身体线索的长期沉淀。\n探索与陪伴: 在探索页按海岛路径阅读、收藏科普内容；随时与浮窗里的 Crab 交流，由它连接你的记录与下一步建议。\n就医辅助: 如需就医，通过 Health Brief 一键整理一段时间的记录，帮助更准确地回忆和描述自己的状态。\n激励沉淀: 持续使用会积累贝壳积分，并让海湾、图鉴、Crab 与身体档案一起丰富，形成以自我为中心的身体探索与关怀系统。\n\n下一阶段重点: 完善医学知识库与个性化建议、接入 Apple Health / Health Connect / 可穿戴设备降低记录成本、让 Crab 走向持续学习与自然陪伴、让贝壳连接现实女性健康品牌权益；而最重要的一件事是去验证—— 找到真实用户，回答「MoonWave 是否真的让她比以前更了解和关心自己的身体」。\n---\nG001 软件 赛道附加材料\n\n- Slogan: Feel Your Wave. Be Your Wave. 读懂身体的潮汐，找到自己的节奏。\n- GitHub 仓库: https://github.com/chx0506/Wave', demo_link='https://moon-wave.vercel.app/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 00:47:18', is_late='0', created_at='2026-08-30 00:47:18', updated_at='2026-09-01 12:25:28', leader_participant_id=NULL, presentation_link='https://my.feishu.cn/docx/BqpTd1W0RoBlgRxd2N5cwD4Sn5c', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/412/cover.png', screenshot_urls=NULL, video_link='https://moon-wave.vercel.app/share/', github_repo_url='https://github.com/chx0506/Wave', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=412 AND event_id=4;
UPDATE projects SET event_id='4', team_id='242', captain_application_id='3040', topics='["eazo_4her", "beichen_cloudcomm", "sappho_love", "liberlive_goodday", "ant_mulan_ai"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='书瑶在北京', project_name='CareMemory', tagline='那些会忘的治疗细节，CareMemory 替你记住。', demo_order='31', project_description='【问题】\n治疗真正发生在两次见医生之间：吃了什么药、什么时候头痛/腹泻、症状何时变化……这些细节到复诊时经常只剩一句“我记不清了”。调研后我们发现，CareMemory 不需要服务所有患者，而更适合事件多、时间重要、以后还要回看的治疗场景。\n\n【方案】\nCareMemory 是患者自己的 AI 治疗记忆。用户用文字或语音随手记录变化，AI 帮助整理，但只有患者确认过的事实才进入治疗时间线。系统还能自动形成复诊概要，并通过「问 CareMemory」查询过去记录；重要答案都能回到日期、疗程和原始记录。\nCareMemory 不诊断、不调整用药、不判断医学因果，医疗判断仍交给医生。\n\n【现场完成】\n已完成并上线：独立账号、疗程管理、文字/语音记录、AI 结构化整理、患者确认、疗程时间记忆、复诊概要、跨疗程查询、原始证据回溯和处方图片私有保存。项目已部署腾讯云，GitHub 已提交完整代码并设置 shenicest-fission Topic；目前 213/213 项自动化测试通过。\n\n【评委体验】\n注册：https://carememory.shuyao168.com/register\n邀请码：CMI-QQAN-84A7-LN5Q-DLDG-JLWN-TK45\n登录：https://carememory.shuyao168.com/login\n\n建议体验顺序：\n\n新建疗程 → 记录一次变化 → 确认 AI 整理结果 → 查看疗程时间记忆 → 查看复诊概要 → 问 CareMemory\n\n例如可问：\n“8 月份头痛记录了几天？”\n“以前有没有记录过腹泻？”\n\n每个账号数据独立。当前为比赛内测环境，请只使用虚构/合成测试内容。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 那些会忘的治疗细节，CareMemory 替你记住。\n- GitHub 仓库: lihuadi12580-code/carememory', demo_link='https://carememory.shuyao168.com/register', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 00:51:02', is_late='0', created_at='2026-08-30 00:51:02', updated_at='2026-09-01 12:25:31', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/413/cover.png', screenshot_urls=NULL, video_link='https://www.douyin.com/user/self?modal_id=7679481189728323914', github_repo_url='lihuadi12580-code/carememory', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=413 AND event_id=4;
UPDATE projects SET event_id='4', team_id='167', captain_application_id='3047', topics='["sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='五号梦境', project_name='城市不知道她要去哪', tagline=NULL, demo_order='32', project_description='项目问题\n\n当家庭期待、社会身份和人工智能都在替人规划人生时，个人是否还能保留选择、犯错和感受世界的权利。\n\n 项目方案\n\n通过科幻短片与互动人生系统结合，让观众先看见林夏被规划好的96.4%幸福人生，再亲自进入系统作出选择。系统只展示每条路线可能保留和失去的部分，不评判对错。\n\n## 现场完成内容\n\n现场播放完整影片，演示林夏档案、人生模拟和母亲授权记录。观众可以通过手机参与人生选择，并查看现场投票结果。\n\n 使用方式\n\n观众进入网站观看影片，随后进入人生系统，选择自己愿意尝试的人生方向，提交投票并查看结果。网站同时提供幕后分镜和创作资料。\n---\nG001 AIGC影像 赛道附加材料', demo_link='https://city-does-not-know-her-way.yeyeyyeye111.chatgpt.site', xiaohongshu_link='城市不知道她要去哪 一座城市能够为每个人规划后悔最... https://xhslink.cn/o/8tOkcCHdD3i 先复制文字，再进【小红书】看看这篇宝贝笔记~', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 00:53:55', is_late='0', created_at='2026-08-30 00:53:55', updated_at='2026-08-30 08:19:12', leader_participant_id=NULL, presentation_link='https://jcnm2ocir8nn.feishu.cn/wiki/Up9UwF0opigy6Ckcpm8cRyG1nQd?from=from_copylink', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url=NULL, screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9304d951bcb_723a1598792b6649.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9304de7ed1b_e350e70fb11b7c27.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9304e3e4f2b_e16cdb395ac03ef2.png"]', video_link='https://xhslink.cn/o/8tOkcCHdD3i', github_repo_url=NULL, bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='AIGC影像', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', al