UPDATE projects SET event_id='4', team_id='208', captain_application_id='4884', topics='["eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='绿色云帆', project_name='Carbon Universe 碳宇', tagline='共建普惠碳世界，让中小主题轻松参与碳核算、碳资产流转与碳中和实践', demo_order='33', project_description='碳宇是一个面向中小企业和个人的一站式碳中和平台，打通碳核算、碳交易、碳普惠、碳凭证的完整闭环，让每一份碳足迹都可验证。在双碳目标下，中小企业和个人普遍面临四大痛点：碳核算门槛高，要么手工估算、要么花数万元找第三方机构；个人缺乏参与减碳的渠道和激励；碳资产交易不透明，普通主体难以理解；碳数据散落各处，无法形成可信凭证。碳宇用四个模块逐一解决这些问题。AI 碳核算支持自然语言录入，自动拆解排放并给出减碳建议；碳资产交易提供双余额、挂单吃单和实时订单簿，全程透明可追溯；碳普惠把步行、关灯等低碳行为变成打卡积分，形成行为到激励的正循环；凭证台账自动汇总各项数据，一键导出 PDF 作为可验证的碳档案。另有全球碳观测 3D 地球，让碳数据可视可感。技术上采用 FastAPI 后端加单文件 Vue3 零构建前端，接口不可用时自动降级为演示数据，保证演示稳定。从核算到交易、激励到凭证，碳宇把减碳从口号变成每个人每天都能执行的小行动。下一步，碳宇计划从演示走向真实数据：接入权威排放因子库与核算标准，让核算结果更接近企业实际；引入真实碳市场行情（如全国碳市场与 CCER），把虚拟交易升级为可对接的模拟撮合；同时支持企业组织架构与多人协作，让碳管理真正进入日常工作流。我们希望碳宇不仅是一次黑客松的展示，更是一套能被真实采用、持续生长的碳管理体系，让减碳成为一件简单、透明、人人可参与的事。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 共建普惠碳世界，让中小主题轻松参与碳核算、碳资产流转与碳中和实践\n- GitHub 仓库: https://github.com/yu-222/Carbon-Universe', demo_link='https://www.bilibili.com/video/BV1pW416BEZP/?share_source=copy_web&vd_source=8df5485a47d42bf5731e4b38f98c4201', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 00:54:57', is_late='0', created_at='2026-08-30 00:54:57', updated_at='2026-09-01 12:25:38', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/415/cover.jpg', screenshot_urls=NULL, video_link='https://www.bilibili.com/video/BV1pW416BEZP/?share_source=copy_web&vd_source=8df5485a47d42bf5731e4b38f98c4201', github_repo_url='https://github.com/yu-222/Carbon-Universe', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12