UPDATE projects SET event_id='4', team_id='165', captain_application_id='4981', topics='["eazo_4her", "frostsullivan_proof", "miaoda_super"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='🔥🌳🐱', project_name='Memory', tagline='Memory · 记录情绪，看见自我', demo_order='88', project_description='Memory 是一款面向年轻人的情绪记录与自我觉察手账应用。产品分为日记本模块、AI自我觉察模块、漂流瓶模块。用户可以创建不同类型本子记录日常、疗愈、显化日记；借助AI分步拆解情绪事件，通过5种人格视角完成自我觉察；还可以使用漂流瓶进行匿名情绪共鸣交换，降低情绪复盘门槛，帮助用户梳理感受、看见内心卡点\n---\nG001 软件 赛道附加材料\n\n- Slogan: Memory · 记录情绪，看见自我\n- GitHub 仓库: https://github.com/lalalalallaallaallalala/xiaosantong', demo_link='https://pan.baidu.com/s/1UrE66pEECCAPpNNFHSVnhg?pwd=33qe', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 04:14:09', is_late='0', created_at='2026-08-30 04:14:09', updated_at='2026-09-01 12:28:01', leader_participant_id=NULL, presentation_link='https://jcni998unt6l.feishu.cn/docx/BPsCdDJwWoaHpVxlJn7cv1dTnge', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/473/cover.jpg', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9335cb364b9_f014a676a91f2b16.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9335d54bfdf_45cbbd730b88767b.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9335e58dda4_c42f62698125b219.png"]', video_link='https://pan.baidu.com/s/1UrE66pEECCAPpNNFHSVnhg?pwd=33qe', github_repo_url='https://github.com/lalalalallaallaallalala/xiaosantong', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, a