UPDATE projects SET event_id='4', team_id='53', captain_application_id='291', topics='["miaoda_super"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='Locus', project_name='面向 STEAM PhD 申请者的可信学术定位与申请决策工具', tagline='Know where you stand. Know where to apply.', demo_order='105', project_description='Locus AI 是一个面向博士申请者的 AI 学术决策助手，解决博士申请过程中背景评估、学校定位、导师搜索和学术信息真实性验证高度碎片化的问题。\n\n用户输入教育背景、GPA、科研经历、研究方向和目标地区后，Locus 将其转化为一条完整决策流程：背景竞争力诊断 → 学校搜索池定位 → 导师 / Lab 智能匹配 → 学术证据交叉验证。\n\n与普通 AI 推荐不同，Locus 不把模型生成的导师信息直接当作事实，而是结合学校官网、OpenAlex、ORCID 和论文数据进行交叉验证，并对无法确认的信息明确标记不确定性。\n\n本次黑客松参赛版本使用秒哒完成产品界面、核心交互流程和公开部署；完整 Locus 产品已在线运行，并进一步支持真实博士导师搜索、证据验证、CV 与申请档案等功能。\n---\nG001 软件 赛道附加材料\n\n- Slogan: Know where you stand. Know where to apply.\n- GitHub 仓库: https://github.com/houfy761-tech/locus-ai-miaoda.git', demo_link='https://app-e205l9ni9udd.miaoda.online', xiaohongshu_link='一口月白', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 05:49:11', is_late='0', created_at='2026-08-30 05:49:11', updated_at='2026-09-01 12:28:56', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/490/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93453adc303_fd052000fabda49c.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93456f57f49_31baa65e077bdfdc.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93457320c5e_dbbd43c62fe2b136.png"]', video_link='https://xhslink.cn/o/k4iAtFU8Gh', github_repo_url='https://github.com/houfy761-tech/locus-ai-miaoda.git', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:16:10', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=490 AND event_id=4;
UPDATE projects SET event_id='4', team_id='182', captain_application_id='4752', topics='["zhiyuan_herrobot", "insta360_hervision", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='泡泡特攻队', project_name='卡洛奇境', tagline='卡洛，等待与你相遇的赛博NPC', demo_order='106', project_description='**赛博NPC，是一套面向主题乐园、文旅景区与沉浸式商业空间的智能角色交互系统。**\n\n它将自主感知、角色化对话、视线跟随与AIGC影像生成融入完整体验流程：主动发现并迎接游客，以符合世界观的人设完成剧情引导，在互动过程中自主记录游客的选择与影像，最终生成并留存一段以游客为主角的个性化内容。\n\n它让NPC不再只是被观看、被操作的机械装置，而是能够主动引导体验、参与内容创作，并将一次短暂互动转化为可领取、可分享、可留存的个人故事。\n\n**自主引导，主动记录，影像留存——让每一位游客都成为故事的主角。**\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 卡洛，等待与你相遇的赛博NPC\n- GitHub 仓库: https://github.com/HanjingLaura/bu-zhi-dao-dui-dui\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a9355778ef10_92b30975023aaa0a.png)', demo_link='https://hanjing-laura.vercel.app/carol/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 05:53:22', is_late='0', created_at='2026-08-30 05:53:22', updated_at='2026-09-01 12:29:01', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/491/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a934da30c60e_252f7bbb723511e7.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a934db0b7e61_f14fd6b3c7e122f2.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a934dbff350c_e8a73092199463b3.png"]', video_link='https://www.bilibili.com/video/BV1Kx4S6XEjg/', github_repo_url='https://github.com/HanjingLaura/bu-zhi-dao-dui-dui', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='1', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:16:10', review_notes='', track_code='硬件', finalist_rank='3', finalist_track='硬件