UPDATE projects SET event_id='4', team_id='71', captain_application_id='5244', topics='["sappho_love", "proya_feelings", "eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='蝉', project_name='ARCANA-探索之旅', tagline='女性自我愉悦与亲密关系的探索之旅', demo_order='130', project_description='这个项目设立的原因是x想用卡牌去带领大家触摸，感受自己的身体，引导女性在相对安全、低压力的体验中靠近自己的身体与感受，识别羞耻、不安、疲惫及未被说出的需求。\n\n现场完成了：\n产品背景及定位设计，用户需求调研，网页设计，卡牌机制设计，卡牌牌面编写。\n使用点击，触控的方式抽卡，推进以及基础的选择。\n\n还有待改进的问题是：卡牌的完整性，动画的流畅度以及音乐。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 女性自我愉悦与亲密关系的探索之旅\n- GitHub 仓库: https://github.com/mamingyang9975-eng/card', demo_link='https://pan.baidu.com/s/1bl7tAOgzq0svz2NNrF9LnA?pwd=1111', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:00:04', is_late='0', created_at='2026-08-30 07:00:04', updated_at='2026-09-01 12:30:01', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/515/cover.png', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1bl7tAOgzq0svz2NNrF9LnA?pwd=1111', github_repo_url='https://github.com/mamingyang9975-eng/card', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:11:30', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=515 AND event_id=4;
UPDATE projects SET event_id='4', team_id='61', captain_application_id='4934', topics=NULL, sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='Foothold', project_name='Foothold-老年妈妈力量训练及跌倒检测工具', tagline='陪她练好每一块肌肉，让每一次跌倒都能被\\'早一步’看见', demo_order='131', project_description='问题：\n全球范围内，老年女性肌肉流失影响的不只是力量，也会影响行动、平衡和跌倒风险。WHO 建议65 岁及以上老年人每周至少 2 天进行涉及主要肌群的肌肉强化活动，以提升功能能力并预防跌倒。\n\n与此同时，跌倒是65岁以上老年女性群体中最常见、后果最严重的意外伤害之一，尤其是独居或子女不在身边的老人女性——跌倒后如果不能第一时间被发现，从"摔倒"到"被救助"之间的时间窗口，直接决定了后续的伤情严重程度。\n\n本次项目成员的妈妈正在经历肌肉萎缩，有着力量训练以恢复肌力、并预防跌倒的刚性需求。\n\n因此，我们将目标人群设定为65岁以上，有肌力恢复及预防跌倒需求的老年女性。尤其是独居或与子女分开居住，有一定跌倒史，且对复杂智能设备接受度有限的人群。并解决她们的2个核心痛点：\n\n1、养成肌肉力量训练的习惯以提高行走能力、预防跌倒\n2、及时进行跌倒识别，并通知子女。\n\n\n注：全球约 1.1–3 亿60岁及以上老年人可能受肌少症影响（以世界卫生组织 2023 年60 岁及以上人口为基数，10%-27% 患病率粗略估算）\n\n方案：\n我们构建了一套“微信小程序+嵌入式/可穿戴硬件+情感陪伴”三位一体的安全守护产品体系。\n\n针对老年女性养成肌肉力量训练习惯以提升行走能力、预防跌倒的需求，我们通过微信小程序和嵌入式硬件设备帮助这一群体在手机端和居家物理环境中，低门槛地进行训练动作学习-锻炼提醒-打卡陪伴。子女也可以通过小程序在日常生活中陪伴老年妈妈进行日常训练，并可发送鼓励的话语、有效建议等。\n\n同时，针对老年女性跌倒后‘无法呼救’的痛点，我们推出了低门槛的穿戴式守护终端。她只需像戴手表一样佩戴该硬件，系统便能实时捕捉异常姿态；一旦发生真实跌倒，硬件会自动识别并向子女推送紧急告警，全程无需老人操作。\n软硬件端均进行适老化设计，以提升老年女性的使用体验。\n现场完成内容：\n跌倒检测穿戴终端：能够通过裸片 ESP32-S3-N16R8 + MPU6050 六轴传感器。实时监测老年女性的姿态与加速度变化，判断疑似跌倒事件。并通过本地无源蜂鸣器（GPIO4）进行语音提示和警报，物理按键（GPIO5）用于老人取消误报。若10秒内未收到取消信号（意味着老人可能已失去行动能力），系统立即转为持续长鸣，并通过PushPlus向子女的微信推送包含时间与地点的紧急告警，将“摔倒到被发现”的黄金救援时间压缩至极限。\n\n\n日常训练与陪伴终端：微信小程序进行了聚焦于训练习惯养成和子女陪伴的开发，并进行了适老化优化，硬件端完成了基于DFRobot UNIHIKER K10行空板的肌肉训练文字及语音提示、训练计时功能、训练中后的音乐陪伴及语音鼓励，（与小程序协同）定时触发训练提醒已完成代码层逻辑设定。训练期间配有舒缓音乐陪伴，并在完成后触发语音鼓励。\n\n首次方式：\n软件端：老年女性和子女通过微信小程序，分别进行初始设定，后续使用可直接登陆。\n硬件端：将DFRobot UNIHIKER K10行空板放在日常起居的醒目位置，链接上Wi-Fi，并佩戴好可穿戴手环。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 陪她练好每一块肌肉，让每一次跌倒都能被\\'早一步’看见\n- GitHub 仓库: https://github.com/Juliawww-wy/Foothold\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a938038a4bde_f9a4c1e83b3387fa.jpg)\n  - ![BOM 图](/platform/uploads/images/2026/08/6a93804a7cd72_67b45a65a1e46fd9.jpg)\n  - ![BOM 图](/platform/uploads/images/2026/08/6a938064edcaf_fbd55df5d185faa3.png)', demo_link='https://pan.quark.cn/s/9338d05d721c', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:00:16', is_late='0', created_at='2026-08-30 07:00:16', updated_at='2026-09-01 12:30:04', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/516/cover.png', screenshot_urls=NULL, video_link='https://pan.quark.cn/s/9338d05d721c', github_repo_url='https://github.com/Juliawww-wy/Foothold', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='iteration', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:11:30', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url='https://github.com/Yiruo/banma-jianxing', iteration_plan='从0-1加入嵌入式/可穿戴硬件方案，包括日常训练提醒终端（DFRobot UNIHIKER K10）、跌倒检测穿戴设备（ESP32-S3-N16R8 + MPU6050 六轴传感器、无源蜂鸣器（GPIO4）等，可提升日常训练陪伴及跌倒检测能力。\n软件部分更聚焦在训练入门、子女陪伴等功能上，并进行了适老化体验优化', iteration_submitted_at='2026-08-30 08:59:33', award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=516 AND event_id=4;
UPDATE projects SET event_id='4', team_id='251', captain_application_id='5295', topics='["ciie_smartchain", "frostsullivan_proof", "bluebox_sleep", "beichen_cloudcomm", "ant_mulan_ai", "insta360_hervision", "proya_feelings", "miaoda_super", "liberlive_goodday"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='万花筒', project_name='纹样造梦者', tagline='用技术连接民族文化与女性公益', demo_order='132', project_description='项目说明：\n问题：中国1732项国家级非遗中，民族手工艺占比超40%，但传承人平均年龄超50岁，年轻人「想学没入口、想帮没途径」。与此同时，女性公益项目与用户日常割裂，捐赠行为缺乏情感连接。\n方案：「万花筒」是一个连接民族文化学习与女性公益的移动应用，核心功能包括：民族美学微课（从苗绣纹样到藏族吉祥八宝）、木兰能量积分系统（学习赚能量、能量做公益）、文化社交社区（方言交换、作品投票、AI传承人采访）。\n现场完成内容：48小时内完成可交互H5原型，包含：完整课程学习-能量赚取-公益捐赠闭环流程，以及AI纹样生成功能演示。\n使用方式：用户打开app，每日开启「民族美学盲盒」学习纹样课程，完成创作任务赚取木兰能量，用能量兑换公益权益（为乡村女童购买美育用品/支持民族女性手艺人课时费），在社区与同好组队、交换方言。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 用技术连接民族文化与女性公益\n- GitHub 仓库: https://github.com/siyuezhong/wanhuatong', demo_link='https://pan.baidu.com/s/1QlIKvRwPE09ZNgS1yNmWsw?pwd=9eU5', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:04:54', is_late='0', created_at='2026-08-30 07:04:54', updated_at='2026-09-01 12:30:05', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/517/cover.png', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1QlIKvRwPE09ZNgS1yNmWsw?pwd=9eU5', github_repo_url='https://github.com/siyuezhong/wanhuatong', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_s