UPDATE projects SET event_id='4', team_id='125', captain_application_id='3059', topics='["sappho_love", "tripo_hergaze"]', sponsor_consents='{"tripo_hergaze": {"rights": "非独占、全球范围、免费", "topic_code": "tripo_hergaze", "sponsor_key": "tripo", "topic_title": "为她而设计 — Her Gaze, Her Game", "consented_at": "2026-08-27T23:00:15+08:00", "consented_ip": "120.244.16.132", "sponsor_label": "Tripo 3D", "sponsor_full_name": "Tripo 3D (Vietnam)", "consented_user_agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0"}}', application_id=NULL, session='从0到1', cohort=NULL, team_name='斗斗熊', project_name='她的世界不一样 多元宇宙', tagline='让AI创造不存在的玩法', demo_order='1', project_description='这是个来自“她”一位母亲的问题：孩子要上初中了，我辅导不了了。她的孩子说：我想在玩中学习可以吗？\n当然可以。通过简单的对话即可生成丰富的世界、游戏、视频、图像、故事。。。。\n爱玩是孩子的天性，学习是必要的天性也是宝贵的。如何能让孩子既能学好又能玩？通过AI强大的生成能力，普通用户也可以随心所欲的生成游戏。通过简单的描述，AI可以创造各种世界观。通过强大的AI系统生成世界观档案。\n创建游戏设定、剧情、视频。玩家自己设定目标。AI生成游戏。玩家在游戏中自由探索。项目分为两部分一部分是强大的AI生成，第二部分是用这个AI系统生成的可以学习的游戏。\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 让AI创造不存在的玩法\n- GitHub 仓库: https://github.com/ghostbear111/chemistry-world\n- 游戏玩法说明:\n  在化学的世界里，水会结冰，冰会成为水，岩浆很烫怎么办呢？\n  玩家通过化学知识在游戏中探索边学边玩。从学习中获得乐趣。\n  即使是化学小白也可以通过游戏的引导探索化学世界的乐趣！', demo_link='https://ghostbear111.itch.io/chemistry-world', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:10:19', is_late='0', created_at='2026-08-30 07:10:19', updated_at='2026-09-01 12:30:09', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/519/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9366964f9b4_03e8f9f71e70d8b0.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9366a5c270e_30b981d01a40cf34.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9366d9c1e4d_df1906b6e1593609.png"]', video_link='https://www.bilibili.com/video/BV1Jo4U6kETW/?vd_source=30a69454e773acd8bd41031dcb5c09f5', github_repo_url='https://github.com/ghostbear111/chemistry-world', bom_link_text=NULL, gameplay_description='在化学的世界里，水会结冰，冰会成为水，岩浆很烫怎么办呢？\n玩家通过化学知识在游戏中探索边学边玩。从学习中获得乐趣。\n即使是化学小白也可以通过游戏的引导探索化学世界的乐趣！', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=519 AND event_id=4;
UPDATE projects SET event_id='4', team_id='152', captain_application_id='240', topics='["miaoda_super", "eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='TOILER_安心如厕小组', project_name='TOILER', tagline='厕所里面有什么', demo_order='134', project_description='TOILER是一个面向女性公共厕所使用场景的即时选择工具。\n在项目前期对女性朋友的访问中，大家提出了各种让自己“再忍忍”、暂时不使用公共厕所的情况。其中，无法快速找到符合自己当下需求的厕所是被多次提到的痛点。地图软件已经可以告诉我们厕所在哪里，但真正影响女性是否愿意进入的，往往还有门锁、厕型、坐便卫生支持、厕纸、置物、洗手和干手等内部条件。很多时候，我们需要走进厕所，才能知道这个厕所是否适合自己使用。\nTOILER希望逐步建立一套面向女性如厕选择的厕所决策信息模型，并以这些信息作为筛选条件，匹配当前更符合需求的厕所。用户可以选择自己当前在意的信息，TOILER根据附近厕所已确认的设施状态进行匹配，并明确区分“已确认满足”“已确认不满足”和“信息未知”；当附近没有完全满足需求的厕所时，TOILER则会继续展示较接近当前需求的厕所，并如实标注不同需求的满足情况，把最终判断留给使用者自己。\n本次黑客松提交的主体是TOILER用户端。我们将前期研究中形成的厕所决策信息转化为可查询、筛选和比较的结构化条件，并完成了Web与微信小程序版本。与此同时，TOILER beta作为前期研究与真实用户验证工具，通过对匿名公共厕所照片的“再忍忍 / 还想看看 / 我看行”的选择、追问与日常自报，持续验证哪些信息真正进入女性的如厕判断；TOILER Steward则作为信息长期维护机制的验证原型，用于探索场馆和信息维护方如何持续确认、更新厕所状态。\n当前TOILER用户端已提供可直接体验的Web版本，并保留微信小程序版本。用户可通过当前位置或附近区域查看DEMO厕所，根据自己当前在意的条件筛选、比较并查看结果。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 厕所里面有什么\n- GitHub 仓库: https://github.com/Janejoey/TOILER', demo_link='https://app-e0zg5upm7kzl.miaoda.online/#/pages/home/index', xiaohongshu_link='https://xhslink.cn/o/6B8Kdud1Bo2', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:11:42', is_late='0', created_at='2026-08-30 07:11:42', updated_at='2026-09-01 12:30:13', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/520/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a932a0cb22e1_ed04aecb068ada3f.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a932a15db748_739642406188fcc1.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a932a1bca7fd_ac6ac9547563d81a.png"]', video_link='https://xhslink.cn/o/9Tg4AWDJXuG', github_repo_url='https://github.com/Janejoey/TOILER', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='standard', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=520 AND event_id=4;
UPDATE projects SET event_id='4', team_id='32', captain_application_id='3075', topics='["liberlive_goodday", "insta360_hervision", "qingxian_self"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='老ADHD0～1挑战solo硬件', project_name='盯盯机', tagline='ai督学机器人', demo_order='135', project_description='AI驱动的督学娃娃。自建视觉识别系统，AI控制提醒\n---\nG001 硬件 赛道附加材料\n\n- Slogan: ai督学机器人\n- GitHub 仓库: https://github.com/Imogene-Schaefer/dingdingji\n- BOM / 原理图:\n  - https://raw.githubusercontent.com/Imogene-Schaefer/dingdingji/main/img/hero-doll.jpg', demo_link='https://521d94ac.r9.cpolar.cn/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:25:21', is_late='0', created_at='2026-08-30 07:25:21', updated_at='2026-09-01 12:30:13', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99303/cover.jpg', screenshot_urls=NULL, video_link='https://1', github_repo_url='https://github.com/Imogene-Schaefer/dingdingji', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99303 AND event_id=4;
UPDATE projects SET event_id='4', team_id='271', captain_application_id='4615', topics='["liberlive_goodday", "proya_feelings", "qingxian_self", "bluebox_sleep", "zhiyuan_herrobot", "eazo_4her", "ant_mulan_ai", "ciie_smartchain"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='鹅在', project_name='鹅在', tagline='鹅在，守护您！——独居老人无感跌倒守护', demo_order='136', project_description='【问题】\n3300 万独居老人，跌倒后超 1 小时无人发现的占 38.4%。摄像头侵犯隐私，老人拒装（我们发起人的奶奶就说过："不想被别人看到"）；穿戴设备要充电要佩戴，老人忘戴；一键呼救，摔得动不了时够不到按钮。三大方案全部死局。\n\n【方案】\n鹅在基于团队自主发明《一种基于射频信道感知中枢的自适应多模态协同调度方法及系统》（发明专利申请已受理，申请号 202611112053.1）二次开发，采用 CSI 射频无感感知，从架构上不存在隐私问题：全程不产生任何图像，原始信号不落地，只存结构化结论。三路信号融合——身体动态、呼吸频率、在场状态交叉判断（无接触呼吸检测误差 0.2 次/分），双证齐了才触发，单信号不告警。个体化基线按每位老人的日常习惯建模。\n\n【现场完成内容】\n赛事期间完成系统全部开发：ESP32-S3 双板真机 96 小时跑通全链路——边缘决策系统（黄橙红黑四级状态机、跌倒三分类 + 近场 6 秒确认、个体化健康档案、两轮语音确证、失联接力）、告警认知层（双引擎架构：大模型推理输出疑似病因与个性化理由，AI 只解释不触发，不可用时自动降级规则版，全程留痕可审计）、子女端 H5 9 页、双通道部署（局域网摆摊演示 + 公网 https）。数据真实：8 组控制变量实验 × 20 次（跌倒 F1–F4 / 呼吸 B1–B4 / 空调底噪对照），全部阈值溯源到实测数据；28 轮数据驱动参数迭代；基线/底噪/帧率三重环境自校准（空调底噪 17 倍补偿）；动/静信噪比 12.2:1；算法调优基于居家参考基线（底噪 0.009）真实数据集评测；比赛现场实测底噪 0.08，不满足低噪前置条件，主动放弃现场演示，改在与居家参考基线对齐的受控场地（复测底噪 0.009、分布一致）完成全链路真人实测，数据分布匹配、不放水。\n\n【使用方式】\n现场扫码即可在自己手机上体验：子女端实时波形、47 秒告警时间线、健康档案实时联动；公网 Demo（见"Demo 链接"字段）直接访问。老人家中布置（装两块 ESP32）后，老人零操作——不装摄像头、不佩戴、不按按钮；24 小时数据自动沉淀为生活/健康档案，子女随时看趋势。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 鹅在，守护您！——独居老人无感跌倒守护\n- GitHub 仓库: https://atomgit.com/happyhouse/GD\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a9359b1ca76f_a1a466f0b152ffdd.jpg)', demo_link='https://acng9x05atrp.feishu.cn/file/Ipfgbt1GHoeLBPxCbYAcZWipnab', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:27:45', is_late='0', created_at='2026-08-30 07:27:45', updated_at='2026-09-01 12:30:19', leader_participant_id=NULL, presentation_link='https://acng9x05atrp.feishu.cn/file/WUQabdiBVoENIqxDFnTc2YGUnvd', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99304/cover.jpg', screenshot_urls=NULL, video_link='https://acng9x05atrp.feishu.cn/file/Ipfgbt1GHoeLBPxCbYAcZWipnab', github_repo_url='https://atomgit.com/happyhouse/GD', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='iteration', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:07:26', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url='https://github.com/firecangshu/guardgoose', iteration_plan='一、新增：① 告警认知层：双引擎，大模型推理输出疑似病因、标签与个性化理由，判定等级按映射表锁定，不可用时自动降级规则版，全程留痕可审计；② AI 周报：24h 感知数据自动聚合为周度健康报告；③ 检测报告体系：静/动双报告；④ 子女端 H5 共 8 页（含新增检测报告页）。\n二、构建：① UI 设计系统重构（design tokens、鹅 IP 视觉规范、首屏重做、8 页交互打磨修复断点）；② TTS 告警铃声；③ 信号处理核心（活动强度/锁频共识呼吸 6–36 次/分/滑窗分位+EMA 底噪）；④ preflight 五项自检；⑤ 3D 外壳；⑥ 双通道部署。\n三、验证：8 组×20 次控制变量实验（跌倒 F1–F4 / 呼吸 B1–B4 / 空调底噪对照），全阈值溯源实测数据；28 轮数据驱动迭代；基线/底噪/帧率三重自校准（空调 17 倍补偿）；96h 全链路真机，47s 端到端，信噪比 12.2:1，呼吸误差 0.2 次/分；居家底噪 0.009 基线真实数据集调优；现场实测底噪 0.08 不满足低噪前置，改在与基线对齐的受控场地（复测 0.009）完成真人实测。', iteration_submitted_at='2026-08-30 07:27:45', award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99304 AND event_id=4;
UPDATE projects SET event_id='4', team_id='17', captain_application_id='3219', topics='["liberlive_goodday", "ciie_smartchain", "beichen_cloudcomm"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='深度思考中......', project_name='好奇·迹', tagline='小派了解孩子，机械臂绘画梦想', demo_order='137', project_description='面向儿童线下探索空间的智能陪伴与兴趣转化系统\n\n让孩子的好奇被听见、被延伸，并转化为可以回看和带走的探索成果。\n\n项目概述\n\n好奇迹是一套面向博物馆、科技馆等儿童线下探索空间的智能陪伴系统。它以移动机器人作为现场交互载体，在家长掌握移动与授权的前提下，通过儿童化讲解、自然语音对话、视觉理解和兴趣线索识别，帮助孩子沿着自己的好奇继续探索；同时把照片、对话、路线、兴趣元素与纪念画组织成参观后的个人记录。\n\n一句话说明：好奇迹不是替孩子规划一条标准答案路线，而是陪他沿着自己的兴趣继续走下去。\n\n当前真实状态：移动机器人遥控与儿童语音对话已经能够实时运行；展品识别、兴趣识别、自动拍照和探索报告属于部分完成；下一展品推荐仍为后续规划，机械臂自动落笔闭环尚未证实。当前版本应表述为“核心链路可运行、完整闭环仍在集成”，不宜描述为全自动成品。\n\n\n一、项目定位\n\n1. 服务对象\n\n以儿童为核心体验者；家长或监护人掌握移动、路线与隐私授权；场馆负责知识与内容边界。\n\n2. 首个场景\n\n以博物馆青铜器展览作为验证入口，原因是该场景知识密度高、成人表达明显、亲子讲解门槛高。\n\n3. 产品形态\n\n当前系统结构更接近B2B2C：以场馆为部署与服务入口，为家庭提供现场陪伴以及参观后的照片、报告和纪念品体验。\n\n4. 能力边界\n\n博物馆是验证入口，不是能力边界。后续可迁移到科技馆、自然教育基地、研学和亲子文旅空间。\n\n\n二、我们要解决的问题\n\n孩子并不缺少更多知识，而是缺少一个能及时理解“为什么这个细节吸引我”、愿意顺着兴趣继续交流的探索伙伴。家长愿意陪伴，却常常不知道孩子此刻需要听到什么程度、如何把“快看这个”变成真正有来有往的对话。场馆拥有专业内容，但统一讲解和成人表达难以根据不同孩子的语言、表情和动作即时调整。\n\n对孩子：好奇信号容易被忽略，探索被统一路线和标准答案打断。\n\n对家长：专业讲解门槛高，既担心讲不清，也难以捕捉孩子的真实兴趣。\n\n对场馆：儿童服务能力不足，缺少可用于优化内容的匿名化兴趣反馈。\n\n核心问题是补上“理解兴趣—及时回应—继续延伸—留下结果”这一段体验。\n\n\n三、解决方案与系统组成\n\n好奇迹把一次参观组织成四个连续动作：听见兴趣信号、用儿童能理解的方式回应、给出与兴趣相关的探索方向、留下可回看的记录与可带走的作品。四类端侧共同承担体验与安全责任。\n\n1. 场馆协作中心\n\n主要使用者为场馆工作人员，承担展品知识、儿童表达口径和内容审核的配置工作。当前Vue 3页面可以运行，但展品管理和画作建议主要为前端模拟；真实知识主要维护在配置文件中。\n\n2. 家长端应用\n\n主要使用者为家长或监护人，提供服务解锁、虚拟摇杆控制、授权拍照、照片查看和探索报告查看等功能。网页已经部署，但账号体系和部分主体数据仍未完成。\n\n3. 移动陪伴机器人\n\n主要服务孩子与家庭，在展品前进行讲解、倾听提问、视觉问答和兴趣证据采集。网页遥控和本地语音对话链路已经能够运行。\n\n4. 绘画机械臂\n\n目标是把兴趣元素转化为现场绘画。当前已经完成纪念画图片生成和跨服务器传输，自动转轨迹并驱动真机落笔仍待打通。\n\n\n四、机器人何时开口\n\n1. 到达展品时：提供简短、易懂的基础介绍，不一次性灌输全部信息。\n\n2. 出现兴趣信号时：依据停留、朝向、偏好表达、连续追问、重复互动以及音量和语速等弱证据，决定是否继续交流。\n\n3. 孩子主动提问时：从人工预设、场馆审核的资料中回答；当前不依赖实时联网搜索。\n\n这些线索仅用于判断是否继续互动以及如何延伸，不用于对孩子做性格、能力或心理诊断。\n\n\n五、目标体验闭环与现场演示\n\n以下流程同时说明“目标体验”与“当前演示边界”。已实现的步骤可实时运行；尚未闭环的步骤明确标注为部分完成或人工触发。\n\n1. 抵达展品\n\n家长用手机虚拟摇杆控制机器人来到青铜鼎前，机器人进行简短的儿童化介绍。遥控与语音链路可实时运行。\n\n2. 发现兴趣\n\n孩子注意到兽面纹或“大眼睛”，系统结合停留、朝向、语音和连续互动记录兴趣证据。兴趣识别已有混合链路，但正式现场样本仍少。\n\n3. 自然问答\n\n孩子追问铸造方法，机器人通过本地多模态模型和预设展品资料回答。自由问答与摄像头画面理解可以本地运行。\n\n4. 延伸探索\n\n目标体验会推荐相关展品，并由家庭决定是否前往。当前“下一展品推荐”尚未实现，演示时需要使用预设路径或人工引导。\n\n5. 记录与创作\n\n获得授权后，系统保存代表性照片、对话片段、路线与兴趣元素。报告链路部分完成，系统可生成纪念画图片并传至机械臂侧。\n\n6. 交付成果\n\n目标是在出口附近由机械臂完成最后绘制，并向家长端交付发现手册。当前机械臂自动落笔仍需人工触发或进一步集成。\n\n\n六、现场演示建议口径\n\n1. 重点展示实时遥控、安全停车、儿童语音对话、视觉问答和兴趣证据记录。\n\n2. 照片、报告与画作生成按“真实代码+预设资料+少量联调数据”的状态说明。\n\n3. 下一展品推荐使用预设演示路径，不宣称已有实际推荐算法。\n\n4. 机械臂部分展示图片生成与传输；如果现场落笔依赖人工触发，应在解说中明确。\n\n\n七、实际技术实现\n\n当前工程以Jetson本地推理为核心，通过云端HTTPS服务与常驻SSH隧道连接手机网页、机器人开发板和数据接口，在有限算力条件下兼顾语音、视觉、对话与运动安全。\n\n1. 机器人与计算\n\n机器人本体为高擎Mini Pi Plus。计算平台为NVIDIA Orin NX Developer Kit，具备16GB级内存，当前使用25W模式。系统环境为Ubuntu 20.04、JetPack 5.1.5和aarch64。视觉硬件为Intel RealSense D435i RGB-D相机。\n\n2. 机器人控制\n\n使用ROS Noetic和Python。真实话题包括/cmd_vel、/joy_msg、/fsm_state、电机反馈和相机压缩画面。控制网关同时检查电机反馈和FSM状态。\n\n3. 遥控链路\n\n控制路径为：手机网页→HTTPS云端接口→常驻SSH隧道→开发板Python网关→ROS运动话题。短时控制租约确保松手或断网后自动停车。\n\n4. 语音链路\n\n语音唤醒使用Sherpa-ONNX Zipformer KWS；VAD使用Silero VAD ONNX；ASR使用Qwen3-ASR-0.6B Q4_K量化模型并通过CrispASR本地服务运行；声纹门控使用3D-Speaker CAM++；TTS使用本地量化CosyVoice3。\n\n5. 对话与视觉\n\n使用Qwen3.5-2B-Q4_K_M.gguf和mmproj-BF16.gguf，通过llama.cpp本地部署。上下文窗口为16384 tokens，关闭思考模式，并尽量将GPU层卸载到Jetson GPU。\n\n6. 展品知识\n\n展品知识主要来自人工预设资料和参考图。museum_config.yaml管理展品ID、介绍词、互动问题、视觉描述和参考图。YOLO11n轻量特征索引用于候选匹配，再由本地Qwen模型复核。\n\n7. 网页与云服务\n\n家长端采用Next.js 16、React 19、TypeScript、Vinext/Vite和Nginx。场馆端采用Vue 3。云端使用Ubuntu、Nginx HTTPS和Python ThreadingHTTPServer。\n\n8. 数据与记忆\n\n开发板和云服务器均使用SQLite，保存Episode Memory、语义偏好、展品进度、照片和报告数据。\n\n9. 兴趣画作\n\n使用豆包Seedream图像API生成纪念画图片，并将文件传到高擎Panthera-HT六轴机械臂侧。图片到绘画轨迹及真机落笔尚未形成可核验闭环。\n\n\n八、当前完成度\n\n状态依据“能否真实运行、是否依赖预设数据、是否形成完整闭环”判断。\n\n1. 家长端网页：部分完成\n\n已部署；移动端适配、遥控、照片和报告增量接口可用，登录和部分主体数据仍为演示。\n\n2. 场馆协作中心：演示模拟\n\n页面完整可运行；儿童声纹录入是真实功能，Prompt、展品管理和画作建议主要为前端模拟。\n\n3. 移动机器人遥控：已完成可运行\n\n网页摇杆、云端中继、SSH隧道、ROS运动和安全停车链路均已实现。\n\n4. 儿童语音对话：已完成可运行\n\nKWS、VAD、ASR、视觉LLM、TTS和声纹均为真实本地模型。\n\n5. 展品识别与讲解：部分完成\n\n真实识别与讲解代码已经完成，但展品库样例少，尚未完成场馆级标定。\n\n6. 兴趣识别：部分完成\n\n真实混合算法和模型复核已经实现，但正式现场数据较少。\n\n7. 下一展品推荐：后续规划\n\n未发现可核验的实际推荐算法或执行接口。\n\n8. 自动拍照：部分完成\n\n授权门控、候选帧、兴趣复核、落盘和上传代码存在，并已用少量样本联调。\n\n9. 探索报告生成：部分完成\n\nEpisode Memory报告生成、上传和查询接口存在；网页仍混有静态演示报告。\n\n10. 机械臂绘画：部分完成\n\n兴趣画作生成和图片传输已经完成；自动转轨迹并真机落笔的闭环未证实。\n\n11. 参观到纪念品串联：部分完成\n\n多段链路可以运行，但推荐和机械臂落笔尚未形成完整自动闭环。\n\n对外表述原则：可以说“核心交互链路已跑通、关键模块已实现并进入闭环集成”；不应说“所有环节均已全自动运行”或“已具备成熟场馆部署能力”。\n\n\n九、核心创新与参与者价值\n\n核心创新：\n\n1. 从统一讲解转向兴趣驱动的陪伴。当下的观察和提问决定后续交流方向。\n\n2. 从单次问答转向连续探索。Episode Memory将多轮观察、对话和偏好串联起来。\n\n3. 从纯数字互动转向可带走成果。照片、报告、纪念画与线下绘画目标共同构成体验闭环。\n\n4. 从替代家长转向增强亲子陪伴。家长始终掌握移动、路线、授权和是否继续探索的决定。\n\n参与者价值：\n\n对孩子：有人听见并回应他的好奇；知识以更容易理解和参与的方式出现；探索留下个人化成果。\n\n对家长：降低讲解压力，获得理解孩子兴趣的具体线索，同时保留共同探索和决策的参与感。\n\n对场馆：在不牺牲专业性的前提下补充儿童服务能力，并获得用于优化内容的匿名化反馈线索。\n\n\n十、安全、隐私与产品边界\n\n1. 运动安全\n\n家长端提供停止与紧急停止。控制网关以短时租约、实时电机反馈和FSM状态门控降低断网与误动作风险。\n\n2. 监护人授权\n\n拍照、对话片段和探索记录应在监护人授权后采集。正式产品需要补齐账号、权限、撤回和删除机制。\n\n3. 儿童数据最小化\n\n兴趣信号仅服务当次互动和内容延伸，不进行性格、能力或心理判断。\n\n4. 知识边界\n\n展品知识以人工预设和场馆审核资料为主，不把实时联网搜索作为当前能力。\n\n5. 移动边界\n\n当前由家长遥控，不宣称自主跟随或自主导航。\n\n6. 生成边界\n\n纪念画图像生成使用外部API。机械臂自动落笔仍待完成，应避免把概念图当作真机闭环证据。\n\n\n十一、下一步计划与应用延展\n\n下一阶段的优先级不是增加更多概念功能，而是把现有模块收敛成稳定、可复现、可在真实场馆验证的数据闭环。以下时间规划为工程建议，并非已经确认的对外承诺。\n\n近期，约1个月：扩充真实展品库和参考图，完成场馆标定，清理网页演示数据，稳定兴趣照片、报告和记忆链路。\n\n中期，约3个月：实现下一展品推荐，跑通图片到机械臂轨迹与真机绘画，开展小规模真实场馆试点。\n\n阶段目标，约半年：完善账号、权限、隐私授权、设备运维和多场馆知识配置，形成可复制部署方案。\n\n当“感知兴趣—儿童化回应—关联推荐—作品与记录”机制在博物馆完成验证后，可以迁移到科技馆、自然博物馆、水族馆与动物园、自然教育基地、研学活动和亲子文旅空间。不同场景需要替换知识内容、互动口径与场馆流程，但孩子视角的陪伴机制保持不变。\n\n优先试点建议：博物馆、科技馆和研学机构与当前产品及技术形态的匹配度最高；正式合作计划仍需团队确认。\n\n\n十二、开发过程与团队信息\n\n可核验的近期开发工作包括：\n\n1. Mini Pi Plus、Jetson、ROS与RealSense硬件链路集成。\n\n2. 网页实时遥控、状态门控与失联安全停车。\n\n3. 本地语音唤醒、VAD、ASR、视觉LLM、TTS与声纹门控。\n\n4. 视觉问答、展品特征识别、主动讲解与Episode Memory。\n\n5. 兴趣证据、自动抓拍、报告接口以及家长端、场馆端网页原型。\n\n6. 兴趣画作生成和跨服务器文件传输。\n\n可确认的密集集成时间为2026年8月28日至30日；公开脱敏工程基线于2026年8月30日凌晨发布。这只能证明近期集成窗口，不能代替正式立项时间。\n\n主要工程挑战是在Jetson有限算力上并行运行视觉、语音识别、对话和语音合成，同时保证儿童交互需要的低延迟，并应对公网隧道不稳定、机器人状态误判和运动安全问题。当前采用量化模型、25W功率模式、模型常驻预热、GPU卸载、事件驱动架构、控制租约自动停车、分层健康检查和本地SQLite记忆等方式解决。\n\n团队信息待补充：团队总人数、完整成员姓名或昵称、逐人分工、指导老师、正式合作伙伴、项目立项时间，以及现场前与现场期间的工作边界。当前唯一可公开核验的昵称为ZxShane，即GitHub仓库发布者，不能据此推断项目只有一名成员。\n\n\n十三、核验口径与资料范围\n\n本说明将原项目叙事与工程核验结果合并，遵循“真实运行状态优先、无法证实的信息不作确定陈述”的原则。核验范围包括公开项目主页及脱敏基线、展馆配置与兴趣识别代码、开发板实时状态与主要工程、云服务器服务与数据库，以及Panthera-HT机械臂工程和画作传输日志。\n\n本文中的后续时间表、试点对象和B2B2C产品形态属于基于当前工程结构的建议或判断，仍需团队正式确认后才能作为对外承诺。\n\n\n让每个探索空间，都多一个真正从孩子视角出发的入口。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 小派了解孩子，机械臂绘画梦想\n- GitHub 仓库: https://github.com/ZxShane/Traces-of-Curiosity\n- BOM / 原理图:\n  - https://www.hightorque.cn/chapter/mini-pi%e4%ba%a7%e5%93%81%e4%bd%bf%e7%94%a8%e6%89%8b%e5%86%8c', demo_link='https://124.223.51.227/haoqiji/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:28:26', is_late='0', created_at='2026-08-30 07:28:26', updated_at='2026-09-01 12:30:23', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99305/cover.jpg', screenshot_urls=NULL, video_link='https://pan.quark.cn/s/ecfaba89b821', github_repo_url='https://github.com/ZxShane/Traces-of-Curiosity', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='iteration', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url='https://www.hightorque.cn/chapter/mini-pi%e4%ba%a7%e5%93%81%e4%bd%bf%e7%94%a8%e6%89%8b%e5%86%8c', iteration_plan='本项目保留 Mini Pi plus 的机器人本体、运动与感知开发接口，将其改造为面向 6—12 岁亲子家庭的博物馆智能伴游终端，在机器人中开发智能大脑，实现多模态语音问答；在 Panthera-HT 通用六轴运动控制基础上新增个性化绘画流程。团队另行开发场馆协作中心、家长端、展品知识库、儿童兴趣感知与报告生成等软件，打通“场馆配置—现场伴游—兴趣留痕—机械臂创作—家庭回顾”的软硬件闭环。', iteration_submitted_at='2026-08-30 07:28:26', award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99305 AND event_id=4;
UPDATE projects SET event_id='4', team_id='192', captain_application_id='4552', topics='["insta360_hervision", "ant_mulan_ai", "proya_feelings", "miaoda_super", "eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='活着就是要开心 ！', project_name='遇己-每张照片，都是一场与自己的重逢', tagline='用 AI把你的照片， 排成一本可以读的人生传记', demo_order='138', project_description='问题：\n照片越拍越多，却很少被整理和回看——障碍不是拍照，而是“照片之后的工作”：选图、分类、写文字、排版。设计软件门槛高，生成式 AI 会篡改照片，传统照片书平台不理解照片关系，人工定制贵且难规模化。\n方案：\n遇己从真实照片出发，AI 负责理解和编排，不重绘照片：CLIP 聚类自动分组去重；聊天补充回忆生成故事；自研排版引擎约 3 分钟排出整书；一句话改全书风格，也可手动精修单页；家人可跨时空协作；一份内容输出电子版、PDF、翻页视频、纸书和 NFC 摆件。\n现场完成内容：\n黑客松 4 天内在基线之上完成照片理解流水线、记忆引导对话、全局 AI 编辑、多人协作、多载体输出及全套 UI 升级。已完成 17 个真实作品，最多处理 500 张照片，约 3 分钟出第一版。\n使用方式：\nhttps://dev.yujeeai.com/ 登录\n上传照片 →（可选）聊天补充回忆 → 约 3 分钟生成整书 → 一句话改风格或手动修页面 → 选择任意形态输出。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 用 AI把你的照片， 排成一本可以读的人生传记\n- GitHub 仓库: https://github.com/yvaineyu9/yujee-hackathon', demo_link='https://dev.yujeeai.com/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:28:27', is_late='0', created_at='2026-08-30 07:28:27', updated_at='2026-09-01 12:30:27', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99306/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a936903e2ffa_b1085c7db66ce2f7.jpg","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93690783c51_0a25580aaa1ccb23.jpg","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93690ab0f18_3e35630e639042f0.jpg"]', video_link='https://www.bilibili.com/video/BV1kX4U6LELC/', github_repo_url='https://github.com/yvaineyu9/yujee-hackathon', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 07:31:41', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99306 AND event_id=4;
UPDATE projects SET event_id='4', team_id='33', captain_application_id='3283', topics='["ciie_smartchain"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='无限工厂', project_name='HaloFactory｜协同工厂, SparkLink｜AI 互动胸牌', tagline='HaloFactory｜协同工厂,任务、标准和进度跟着工人走，异常在现场就能反馈。 SparkLink｜AI 互动胸牌,碰一碰，先产生火花，再开始协作。', demo_order='139', project_description='HaloFactory 是一款面向制造现场的 AI 协同工牌，也是一块跟着员工移动的“随身生产看板”。它把当前任务、操作要点、完成进度和下一步行动直接呈现在员工胸前，让每个人随时知道自己现在做什么、怎么做、已经做到哪里。\n当现场出现缺料、设备异常、质量疑问或需要支援等问题时，员工可以快速上报，系统结合当前人员、工位、工序和任务信息，将问题准确传递给对应负责人，并持续同步处理状态。\nHaloFactory 让任务跟着人走、问题留在现场解决，减少信息不同步、交接不清和问题无人跟进造成的漏做、错做与返工。\n\nSparkLink 是一款面向黑客松、创客活动和行业交流场景的 AI 互动胸牌。它不依靠固定标签简单匹配，而是让每个人展示自己当下的所长、所需和组队状态。  \n参与者可以通过手机填写“我能提供什么、正在寻找什么”，并选择“待组队、开放交流、已有队伍或暂不打扰”等状态。胸牌将这些信息转化为现场可见的动态信号，让陌生人一眼知道彼此是否存在交流和协作的可能。  \n当两张胸牌主动碰一碰时，胸牌会通过灯光、动效和积分给予即时反馈；手机端则结合双方主动提供的项目经历与当前目标，生成具体的交叉合作点、破冰话题和下一步行动，帮助陌生人从交换联系方式，进一步走向真实协作。  \nSparkLink 不替用户决定谁是“最佳队友”，而是帮助双方更快找到一个值得聊、可以试着一起做的具体切入点。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: HaloFactory｜协同工厂,任务、标准和进度跟着工人走，异常在现场就能反馈。 SparkLink｜AI 互动胸牌,碰一碰，先产生火花，再开始协作。\n- GitHub 仓库: https://github.com/xypasolini-droid/HaloFactory, https://github.com/xypasolini-droid/SparkLink\n- BOM / 原理图:\n  - https://my.feishu.cn/wiki/X98Qw4F1MiY1hckpGMPcg2yjn0f?from=from_copylink', demo_link='https://worker-copilot-30s-captioned-seedance25-720p.mp4', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:29:41', is_late='0', created_at='2026-08-30 07:29:41', updated_at='2026-09-01 12:30:30', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99307/cover.png', screenshot_urls=NULL, video_link='https://worker-copilot-30s-captioned-seedance25-720p.mp4', github_repo_url='https://github.com/xypasolini-droid/HaloFactory, https://github.com/xypasolini-droid/SparkLink', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='1', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 07:37:30', review_notes='', track_code='硬件', finalist_rank='2', finalist_track='硬件', finalist_locked_at='2026-08-30 14:46:05', iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99307 AND event_id=4;
UPDATE projects SET event_id='4', team_id='28', captain_application_id='3096', topics='["tripo_hergaze"]', sponsor_consents='{"tripo_hergaze": {"rights": "非独占、全球范围、免费", "topic_code": "tripo_hergaze", "sponsor_key": "tripo", "topic_title": "为她而设计 — Her Gaze, Her Game", "consented_at": "2026-08-26T17:40:46+08:00", "consented_ip": "124.127.75.221", "sponsor_label": "Tripo 3D", "sponsor_full_name": "Tripo 3D (Vietnam)", "consented_user_agent": "Mozilla/5.0 (Linux; U; Android 16; zh-cn; PJZ110 Build/BP2A.250605.015) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/115.0.5790.168 Mobile Safari/537.36 HeyTapBrowser/40.10.20.1"}}', application_id=NULL, session=NULL, cohort=NULL, team_name='赛博修仙系统', project_name='赛博修仙系统', tagline='用AI真干活换灵石的修仙经营游戏——修为不是“肝”出来的，是“干”出来的。', demo_order='140', project_description='1、解决了什么问题：\nAI在非互联网领域的小白普及还不够，很多不了解AI的人焦虑却又畏难，然而AI培训市场良莠不齐、割韭菜现象严重，AI小白们缺乏学习AI的自驱力和科学路径。\n这个项目就是希望用“游戏化教育”的方式，让AI小白在轻松玩游戏的过程中逐步掌握Agent、拓展能力边界，就像修仙一样，和自己的“本命法器”Agent共同修炼升级，成为六边形战士😎\n\n特色：\n修仙/经营游戏的修为靠挂机刷本堆出来——数值是虚的；\n学习打卡工具只记「学了什么」、不验「干成了什么」——反馈也是虚的。\nAI使用者明明每天都在用 AI 干真实的活，这些产出却缺少可视化的成长反馈——成长也是虚的。\n而赛博修仙系统，打通了让学习、成长、升级的过程，在赛博修仙的世界观下，让个人能力的提升和游戏角色的升级统一。\n\n目标用户：\n覆盖从「听说过 AI」到「靠 AI 挣钱」的所有人。\n\n2、方案：\n一条世界观第一定律：修为只能来自本命法器在真实世界完成的真实任务。\n• 法宝桥：逆向 ZCode 桌面端的任务调度机制，游戏派发的任务以原生会话出现在 Agent 自己的界面里真实执行——不是后台调 API，观众看得见它思考、建文件、写代码，完成后可继续多轮追问。\n• 经济闭环：干活 → 灵石 → 开荒 / 催熟 / 喂器灵 / 器灵对战 → 更深秘境。灵石只能靠真干活换来，买得到捷径，永远买不到修为。\n• 十境六脉：整体境界 ＝ 六脉中最短的一条（木桶模型），逼玩家突破能力边界，从AI小白成长为AI通才。\n\n3、现场完成内容\n• Godot 客户端完整玩法闭环：领任务 / 派发 / 结算 / 开荒 / 种植 / 催熟 / 收割 / 器灵升级\n• 零依赖 Node.js 法宝桥（sqlite 插表 → 桌面端原生会话）+ 主线八关任务链\n• 三轮真实派发实测：演示任务 41 秒完成、零越界；最重一关 136 秒产出 11 个文件（4 个 JSON 全部合法）；全链路无人工复制粘贴\n\n4、使用方式\n双击 启动.command（自动起桥 + 起游戏）。\n前置：本机安装 ZCode 桌面端并登录、Node ≥ 22.5。\n游戏首页右下角确认「法宝桥：已通」→ 任务面板领任务 → 点「去修炼」→ 切到 ZCode 看它干活 → 回游戏收灵石、进行经营游玩（开荒 / 催熟 / 喂器灵 / 器灵对战等）。\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 用AI真干活换灵石的修仙经营游戏——修为不是“肝”出来的，是“干”出来的。\n- GitHub 仓库: https://github.com/shinna782-hub/newbuilder/tree/main\n- 游戏玩法说明:\n  1、玩法：修仙模拟经营。\n  --领历练任务\n  --点「去修炼」，任务真实派发给本命法器（你日常用的 AI 助手）执行 \n  --AI 助手干完回执结算，灵石与修为在游戏中入账\n  --下秘境青芜原：爆破符开荒、买种播种、催熟收割青芒草\n  --投喂本命法器的器灵升级 ，与灵兽对战\n  --叩开更深秘境。\n  注意：\n  灵石是重要资源，只能靠用AI真的干活换来；\n  法器干活吞吐的灵气按 1000:1 折成额外灵石（「吐纳所得」，每日有上限）。\n  \n  2、操作：WASD 移动 / 数字键切工具 / 鼠标点地块或空格对正前方使用 / E 进据点。\n  任务在「任务」面板领取、派发、结算。\n  \n  3、目标：修为成长。\n  十境（凡人 → 飞升，每境十级）× 六脉（商业 / 产品 / 内容 / 技术 / 思维 / 表达，一脉十窍）。\n  修为成长体系是按照科学的AI培训课程体系去转化设计的。\n  规则一条：整体境界 ＝ 六脉中最短的那一条（木桶模型），逼你补短板、从AI小白成长为AI通才。\n  \n  4、通关条件：\n  演示用的主线任务「制作一款 AI 产品小程序」八关全通——注册 → 需求 → 备案 → 开发 → 提审 → 冷启动 → 复盘 → 变现，每关由法器产出真实可用的成果物过关。\n  \n  5、关键交互：\n  1）任务派发「去修炼」→ 切到 ZCode 桌面端，看 AI 的原生会话真实开工（约 15 秒接单、40 秒左右交活，无任何模拟动画）；\n  2）结算瞬间灵石入账、六脉雷达图亮窍；\n  3）炸地 → 种草 → 催熟 → 收割  → 喂宠 → 对战的农场循环手感。', demo_link='https://pan.baidu.com/s/1uw0ieOosP3ZV4hPTijBrLA?pwd=se5x', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 07:30:34', is_late='0', created_at='2026-08-30 07:30:34', updated_at='2026-09-01 12:30:34', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99308/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937198523c4_ae7be12486d901d2.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9371ad6a508_222ebc58bf593878.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9371b201107_72456a9fd0b9d64f.png"]', video_link='https://pan.baidu.com/s/1uw0ieOosP3ZV4hPTijBrLA?pwd=se5x', github_repo_url='https://github.com/shinna782-hub/newbuilder/tree/main', bom_link_text=NULL, gameplay_description='1、玩法：修仙模拟经营。\n--领历练任务\n--点「去修炼」，任务真实派发给本命法器（你日常用的 AI 助手）执行 \n--AI 助手干完回执结算，灵石与修为在游戏中入账\n--下秘境青芜原：爆破符开荒、买种播种、催熟收割青芒草\n--投喂本命法器的器灵升级 ，与灵兽对战\n--叩开更深秘境。\n注意：\n灵石是重要资源，只能靠用AI真的干活换来；\n法器干活吞吐的灵气按 1000:1 折成额外灵石（「吐纳所得」，每日有上限）。\n\n2、操作：WASD 移动 / 数字键切工具 / 鼠标点地块或空格对正前方使用 / E 进据点。\n任务在「任务」面板领取、派发、结算。\n\n3、目标：修为成长。\n十境（凡人 → 飞升，每境十级）× 六脉（商业 / 产品 / 内容 / 技术 / 思维 / 表达，一脉十窍）。\n修为成长体系是按照科学的AI培训课程体系去转化设计的。\n规则一条：整体境界 ＝ 六脉中最短的那一条（木桶模型），逼你补短板、从AI小白成长为AI通才。\n\n4、通关条件：\n演示用的主线任务「制作一款 AI 产品小程序」八关全通——注册 → 需求 → 备案 → 开发 → 提审 → 冷启动 → 复盘 → 变现，每关由法器产出真实可用的成果物过关。\n\n5、关键交互：\n1）任务派发「去修炼」→ 切到 ZCode 桌面端，看 AI 的原生会话真实开工（约 15 秒接单、40 秒左右交活，无任何模拟动画）；\n2）结算瞬间灵石入账、六脉雷达图亮窍；\n3）炸地 → 种草 → 催熟 → 收割  → 喂宠 → 对战的农场循环手感。', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99308 AND event_id=4;
