UPDATE projects SET event_id='4', team_id='250', captain_application_id='3186', topics='["liberlive_goodday", "ant_mulan_ai"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='能个p', project_name='绘声', tagline='AI口述影像生成与共创平台。让每一帧，都被听见。', demo_order='157', project_description='绘声面向视障和低视力观众，将影视作品中的关键画面转化为可编辑的描述和声音，让更多人也能更完整地观看、理解和欣赏影视作品。\n\n让观看选择更自主\n视障观众可以从自己想看的作品出发，发起口述影像生成，不再只能等待有限的无障碍片单。\n\n降低制作与地域门槛\nAI协助完成画面分析、描述起稿和语音生成，降低时间、资金和专业资源不足带来的限制。\n\n连接观众与志愿者\n让视障观众、口述影像志愿者和内容创作者在同一个社区提出需求、编辑作品、反馈质量。\n\n让口述影像被更多人了解\n通过作品广场、学习内容和社区共创，推广口述影像，帮助更多志愿者学习和参与。\n---\nG001 软件 赛道附加材料\n\n- Slogan: AI口述影像生成与共创平台。让每一帧，都被听见。\n- GitHub 仓库: https://github.com/niswind/audio-description', demo_link='https://audio-description-frontend-305149-11-1309188564.sh.run.tcloudbase.com/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:13:54', is_late='0', created_at='2026-08-30 08:13:54', updated_at='2026-09-01 12:31:13', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99326/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93756814167_8e0efa20f371827d.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937573b0976_96a22e297f101a2f.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9375841bc2b_0012e27b79de36dc.png"]', video_link='https://pan.quark.cn/s/8baa9cc270d4', github_repo_url='https://github.com/niswind/audio-description', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:16:10', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99326 AND event_id=4;
UPDATE projects SET event_id='4', team_id='44', captain_application_id='5000', topics='["liberlive_goodday", "insta360_hervision", "ciie_smartchain", "beichen_cloudcomm", "qingxian_self", "zhiyuan_herrobot", "zeroth_linku", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='别跟姐做队', project_name='YAYA', tagline='牙牙是一只能背在包包上的 AI 守护玩偶——白天是陪你聊天、拍照投喂养成的小伙伴，晚上走夜路时自动定位、拍照留证、一键求助，把女性安全感做成一个有温度的实体，而不是一个冷冰冰的口号', demo_order='158', project_description='牙牙 yaya — 项目说明\n\n问题\n\n女性独自走夜路时，安全感几乎为零：手机里的安全 App 需要解锁、翻页、找按钮，危险发生时根本来不及操作；而防身报警器、防狼喷雾是"死"的工具，平时不会带、不会用，关键时刻还可能被对方夺走。\n\n更深层的问题是：女性需要的不是一个冰冷的报警按钮，而是一个"本来就在身边"的伙伴——平时有情感连接，危险时无需操作就能守护。\n\n方案\n\n牙牙是一只随身守护型 AI 玩偶：\n\n平时：它是能聊天、能养成的小伙伴。对着它拍照"投喂"（拍下食物/物品），AI 识别后转化为虚拟道具，玩偶里的牙牙会做出反应、成长，建立日常情感连接；\n危险时：开启夜行守护后，它自动记录实时位置、拍下环境照片留证、生成可分享的守护链接给紧急联系人；长按玩偶/手机即可静默求助；还有模拟来电帮你脱身尴尬场景。\n\n核心差异：守护能力长在一个你本来就愿意随身携带的实体里，而不是藏在手机第三层菜单中。\n\n现场完成内容（黑客松期间工作增量）\n\n硬件\n\nESP32-S3 + OV2640 摄像头原型机：玩偶内嵌摄像头，可远程触发拍照并上传服务器留证\n实体玩偶外壳（现场 3D 打印/组装）\n\n软件（Web App，手机浏览器直接运行）\n\n夜行守护模式：GPS 实时定位 + 深色地图轨迹 + 环境拍照留证 + 守护链接分享（紧急联系人可远程查看位置）\n一键求助：长按 3 秒 SOS（防误触），三级响应（提醒联系人→发送位置照片→模拟拨号）\n牙牙语音对话：接入大模型 + 语音识别/合成，可自然聊天\n拍照投喂：拍照识别物品 → 生成虚拟道具 → 牙牙角色反应\n脱身工具：模拟来电（3 种话术）、一键录音存证\n"安全到家"确认闭环：到家后一键结束守护，自动通知联系人\n\n使用方式（现场演示流程）\n\n评委用手机浏览器打开牙牙 App，玩偶（ESP32）开机连网\n日常场景：对玩偶说句话，牙牙语音回应；拍一张桌上的食物照片"投喂"，牙牙开心反应\n夜归场景：点击"开始夜行守护"，地图显示实时轨迹，守护链接发给"紧急联系人"（第二台手机/评委手机打开，实时看到位置）\n模拟危险：演示者说"感觉有人跟着我"——牙牙主动提示并拍下环境照片；长按 SOS 3 秒，联系人手机收到位置+照片；可触发模拟来电脱身\n到家闭环：点击"安全到家"，守护结束，联系人收到平安通知\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 牙牙是一只能背在包包上的 AI 守护玩偶——白天是陪你聊天、拍照投喂养成的小伙伴，晚上走夜路时自动定位、拍照留证、一键求助，把女性安全感做成一个有温度的实体，而不是一个冷冰冰的口号\n- GitHub 仓库: https://github.com/Lukex-Collab/YAYA-CITY\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a93762478518_322c7f18f818da6e.png)', demo_link='https://www.bilibili.com/video/BV1Y84U6cEYb/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:15:48', is_late='0', created_at='2026-08-30 08:15:48', updated_at='2026-09-01 12:31:15', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99327/cover.png', screenshot_urls=NULL, video_link='https://www.bilibili.com/video/BV1Y84U6cEYb/', github_repo_url='https://github.com/Lukex-Collab/YAYA-CITY', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99327 AND event_id=4;
UPDATE projects SET event_id='4', team_id='296', captain_application_id='4586', topics='["miaoda_super", "eazo_4her", "liberlive_goodday", "proya_feelings", "insta360_hervision", "frostsullivan_proof", "ciie_smartchain", "sappho_love", "beichen_cloudcomm"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='未世科的希望', project_name='烟火有数', tagline='不抢阿姨的锅铲，只补她的记性、算盘和喇叭', demo_order='159', project_description='烟火有数是个体小摊主的 AI 经营副驾。「良米煎饼」摊主张姐的三大难题——备货靠猜（薄脆隔夜就废）、熟客口味靠脑记、没出摊顾客跑空——分别交给 AI 的算盘、记性和喇叭：用她自己摊位的流水预测明日备货并解释理由；替她记住每位熟客的口味与到点规律；出摊预告让顾客不再白跑。收摊时对手机说一句「卖了八十个」，语音自动记账，数据飞轮越转越准。\n现场可体验一摊三端：顾客端扫码点单选自提时段、阿姨端晨报给出「明天降温又开学，备 132 份」的人话建议、数据飞轮把 14 天误差从 ±30% 收敛到 ±8%。技术上用 Next.js 全栈 + GLM 做语音记账解析与晨报生成，支付走适配层（当前 Mock，落地零改动切官方商户号）。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 不抢阿姨的锅铲，只补她的记性、算盘和喇叭\n- GitHub 仓库: https://github.com/veraAIaytech/yanhuo-youshu', demo_link='https://jianbing-demo.vercel.app', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:16:24', is_late='0', created_at='2026-08-30 08:16:24', updated_at='2026-09-01 12:31:17', leader_participant_id=NULL, presentation_link='https://jianbing-demo.vercel.app/deck', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99328/cover.jpg', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1LwI0mMLRrwaZna2451VVlw?pwd=6gcg', github_repo_url='https://github.com/veraAIaytech/yanhuo-youshu', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:19:12', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99328 AND event_id=4;
UPDATE projects SET event_id='4', team_id='259', captain_application_id='5247', topics='["sappho_love", "proya_feelings", "eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='菌丝共和国', project_name='友个家｜AI驱动的找室友Dating App', tagline='客厅是最小单位的公共空间', demo_order='160', project_description='一、项目简介\n\n「友个家」是一款AI驱动的室友匹配与友邻连接产品，也可以理解为一款室友版Dating App。\n传统租房平台解决的是“住在哪里”和“要花多少钱”，友个家更关心的是“和谁住”以及“怎样一起生活”。\n我们从真实的合租痛点出发，通过共居人格测试和AI Agent匹配帮聊，理解每个人的生活习惯与情感需求，帮助人们找到不只愿意平分房租，也真正适合共享日常的人。\n从匹配合拍的室友，到连接15分钟生活圈内愿意彼此照应的友邻，友个家希望让人们在城市里重新认识附近，也重新拥有附近。\n\n二、项目背景与痛点\n\n在大城市里，我们每天可能会遇见很多人，却很难真正认识谁。而室友可能是这座城市里，少数一个不用特意约，就会经常见到的人。一起吃饭、一起吐槽工作，半夜在客厅聊天，周末临时决定去逛超市。\n如果刚好处得来，室友也许不只是室友——可以成为很好的朋友，甚至成为一种新的“家人”。\n当然，“处得来”是一个很大的前提。\n经济、隐私、卫生、作息、访客和生活理念等共居边界，琐细而繁多。逐一与潜在室友沟通，不仅耗费时间，也容易带来社交压力。\n所以，我们想做一款「室友版Dating App」：先了解你的生活习惯、性格和边界，也了解你想住在哪里、什么时候搬家，再为你寻找那些真的适合一起生活的人。\n那些入住前不好意思问、入住后每天都在意的小事，我们帮你问：洗衣机能洗袜子吗？锅能在水槽里泡一整晚吗？朋友可以临时来家里吗？卫生纸只剩最后一卷，谁去买？\n除了找室友，你也可以认识住在附近的友邻——一起吃饭、散步、看展、运动，或者只是偶尔说一句：“今晚排骨做多了，有人想分走吗？”\n「友个家」关心的不只是如何更高效地找到房子，也关心人与人如何共同生活、彼此照顾，建立更多元的“家”。\n在日益原子化的城市生活中，我们相信，客厅就是最小单位的公共空间。人与人的连接、照顾与共同生活，可以从这里开始。\n\n三、解决方案\n\n（一）找室友：先匹配生活，再共享屋檐\n针对传统租房平台「找房源、尬沟通、盲合租」的低效体验，「友个家」从人和共同生活出发，打造AI辅助、低压力连接的室友匹配产品。\n区别于纯房源工具类App，我们的核心逻辑是：先匹配人格，再匹配现实需求，最后连接真实的人。\nAI帮助用户完成前期筛选与重复沟通，降低合租过程中的沟通成本、试错成本和社交压力。\n1、「室友版MBTI人格测试」作为冷启动入口\n该套测试由32道共居人格情景题和8道共居底线题组成，帮助用户了解自己适合和怎样的人一起生活。\n我们不是在找一个拥有所有优点的人，而是找一个互相能接受彼此缺点的人。\n2、智能匹配，减少无效筛选\n通过自然对话打造用户专属AI智能体，结合聊天数据、测试结果、共居底线、位置、预算、性别、年龄等关键要素进行智能匹配。\n3、AI智能体协助沟通，减少重复沟通成本，降低社交压力\n在匹配到初步合适的潜在室友的情况下，用户可以一键开启双方AI智能体对话。二位的AI智能体将围绕生活习惯、共居规则、租房诉求、费用分摊等高频基础问题展开沟通。用户可以同步查看对话进展、随时加入，并对信息披露范围保持控制。\n4、共居生活工具箱\n未来，产品还将补充共同选房、共居公约、分账工具和租房清单等实用工具，让一次匹配进一步转化为更稳定、可持续的共同生活。\n\n（二）找友邻：从共享屋檐走向15分钟生活圈\n室友关系解决的是“和谁一起住”，友邻关系回应的是“附近有没有可以彼此照应的人”。\n用户可以向AI助手表达具体而微小的需求，例如“周末想找人一起看展”。AI将在社区内进行初步筛选与连接，帮助用户降低发起社交的心理门槛。\n主要友邻场景包括：\n1、生活互助：陪诊、技能交换、二手闲置流转等。\n2、兴趣社交：从室友搭子，延伸至健身搭子、做饭搭子、探店搭子、学习搭子等，打造同城年轻人社交圈。\n3、公共生活：用户可以选择将自己的家开放为「友邻客厅」。平台将提供包容性活动工具包，支持用户开展小型聚会、共同学习和兴趣活动，让客厅真正“活”起来。\n\n（三）活点地图：赛博City Walk，看见正在发生的附近\n活点地图是室友匹配与友邻连接的共同入口。\n不同于展示精确住址的传统地图，活点地图只呈现潜在室友与友邻、附近活动及关系节点，不展示具体楼栋和门牌，以兼顾连接效率与隐私安全。\n用户可以在城市、片区和街道等不同层级探索：\n- 哪些片区存在生活节奏相近的潜在室友；\n- 附近正在发生哪些友邻活动；\n- 人、地点和活动之间如何形成关系网络。\n它既是一种「赛博City Walk」，也是对城市“附近”的重新表达：地图上不只有房源，也有真实生活中的人和连接。\n\n四、项目创新点\n\n1、先匹配生活，再共享屋檐\n传统平台从房源出发，「友个家」从人和共同生活出发。我们先理解用户怎样生活，再寻找生活方式更合拍的人。\n2、AI Agent作为「友人中介」，减少社交摩擦\nAI Agent并非用户的“数字分身”，而是承担“友人中介”的角色：协助完成基础沟通、减少重复提问、提示尚未说清的边界，让用户把时间留给真正重要的交流。\n在这里，AI的价值不是替代人与人之间的社交，而是促进它更轻盈地发生。\n3、从一次匹配走向长期关系\n「友个家」不以完成一次室友配对为终点，而是进一步连接友邻、激活活点地图、共创友邻客厅，在城市中重建“附近”。\n产品面向两类核心用户：\n- 正在城市中寻找室友的租房者：强需求、低频低粘性；\n- 希望认识附近友邻的年轻人：轻需求、高频高粘性。\n两类用户可以形成互补：室友匹配解决当下明确的居住需求，友邻网络承接更长期的人际连接。\n\n五、开发过程\n\n在本次女性黑客松期间，团队完成了以下工作：\n1、明确产品核心逻辑，确定“先找人，再找房”的产品方向；\n2、开展用户访谈与合租痛点收集，设计并迭代共居人格测试；\n3、建立种子用户社群，收集真实用户反馈；\n4、开发并上线可体验的MVP；\n5、设计活点地图、室友匹配、友邻客厅等核心功能；\n6、完成主要产品流程与高保真原型。\n\n六、后续计划\n\n1、持续优化共居人格测试，提升测量的信度、效度与可解释性；\n2、开展真实室友匹配实验，验证从测试、推荐、沟通到线下见面的产品闭环；\n3、接入安全、透明、可控的AI Agent，完善用户授权、信息披露与人工介入机制；\n4、拓展友邻网络，招募友邻客厅共创者，完善社区安全保障与合规机制；\n5、丰富共居生活与社区活动工具箱，为友好共居和包容性活动提供可复用范本；\n6、探索商业化路径，用户免费+供给侧付费，与家居及生活方式品牌、长租公寓、租房平台和本地商户开展品牌共创、场景服务与推广合作。\n\n七、团队分工\n\n徐一鸣｜项目发起人 · 产品经理 · 商务拓展\n梁咏琪｜产品经理 · 视觉设计 · 运营\n魏易瑶｜产品工程师\n余婉遥｜营销传播 · 问卷开发\n葛欣雨｜产品经理 · 创意策划 · 商务拓展\n\n特别致谢\n于依朵｜全栈开发 · UI/UX\n刘欣｜运营维护 · 后勤工作 · UI/UX录入\n---\nG001 软件 赛道附加材料\n\n- Slogan: 客厅是最小单位的公共空间\n- GitHub 仓库: https://github.com/raccoonBK/yougejia', demo_link='http://129.211.15.153:8088/', xiaohongshu_link='https://xhslink.cn/o/1NsabuLVFi', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:17:39', is_late='0', created_at='2026-08-30 08:17:39', updated_at='2026-09-01 12:31:17', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99329/cover.png', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1pEwDW-4vUMLtpavO--jBOA?pwd=veby', github_repo_url='https://github.com/raccoonBK/yougejia', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99329 AND event_id=4;
UPDATE projects SET event_id='4', team_id='139', captain_application_id='5520', topics='["miaoda_super", "liberlive_goodday", "eazo_4her", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='创意无限', project_name='绿屿（智能植物养护系统）', tagline='绿屿（智能植物养护系统）——智能浇灌，绿意成屿。', demo_order='161', project_description='项目说明\n问题\n很多家庭的阳台、窗台摆满了花草，甚至还有一小片自己种的蔬菜——但打理它们的，往往固定是一个人，常常是家里的妈妈。她喜欢这些植物，却不是园艺专家：不同植物需水量不同，全靠经验和记忆；出差或加班几天，回来常常发现花蔫了；浇多了又会伤根。这些看不见的"惦记"，日积月累成了一种隐形的负担。\n\n方案\n绿屿（LvYu）是一款软硬件结合的家庭智能养护系统，slogan是"智能浇灌，绿意成屿"。软件端有一个植物知识库，用户选择自己养的植物后，会得到系统给出的推荐浇水参数，并以一面可视化的"数字花卉墙"集中展示所有植物的状态，兼具实用与颜值。硬件端设计了带独立土壤湿度传感器的智能花盆和浇水中枢，湿度低于设定值时自动触发浇水，并配有安全保护机制（观察期、浇水上限等），避免"失控浇水"。我们希望它不只是一个设备控制面板，而是把妈妈日常"要不要浇、浇多少、浇了没"的操心，安静地接管过去。\n\n现场完成内容\n该项目完全是本次黑客松从创意到实现从0到1的项目。受硬件元器件限制，主要完成了软件部分的完整闭环：植物库与推荐参数、添加植物三步流程、数字花卉墙首页、总览页（含异常排序）、单株详情页（含手动/自动浇水开关）、7天湿度趋势与浇水历史记录、水箱缺水的安全提示与恢复确认。硬件部分完成了产品概念设计（模块化拼接底座、单品分解与家庭拼搭效果图），现场以图示形式展示软硬件的系统结构和工作原理。\n\n使用方式\n现场将通过手机演示App：从"选择植物→确认推荐参数→加入花园"完整走一遍添加流程，展示数字花卉墙的日常查看体验，并模拟触发一次自动浇水与一次缺水异常，直观呈现绿屿如何在后台安静地替用户完成"检测-判断-执行-记录"的全过程。\n\n注意：如项目链接有任何问题请现场找我或者查看附件的ppt获取产品详细说明。\n\n提交一直失败，附上github仓库地址：https://github.com/RowanDrafts/Lvyu\n---\nG001 软件 赛道附加材料\n\n- Slogan: 绿屿（智能植物养护系统）——智能浇灌，绿意成屿。\n- GitHub 仓库: https://github.com/RowanDrafts/Lvyu', demo_link='https://lvyu.vercel.app', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:20:18', is_late='0', created_at='2026-08-30 08:20:18', updated_at='2026-09-01 12:31:19', leader_participant_id=NULL, presentation_link='https://my.feishu.cn/wiki/YQPXwMEu3iQBpikT9fncMRGmnKf', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99330/cover.png', screenshot_urls=NULL, video_link='https://my.feishu.cn/wiki/Db5Fw47sYiuB5fk4es8cSokunMf', github_repo_url='https://github.com/RowanDrafts/Lvyu', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99330 AND event_id=4;
UPDATE projects SET event_id='4', team_id='74', captain_application_id='3233', topics='["ant_mulan_ai", "eazo_4her", "proya_feelings", "sappho_love", "miaoda_super", "liberlive_goodday"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='碳基生物五坨', project_name='Make Again 再一次', tagline='一个帮助人接受离别，并重新学习如何带着这段关系继续生活的 AI 陪伴产品', demo_order='162', project_description='半年前，团队里Venus 的外公离世。外公去世后，妈妈很长时间无法从悲伤中走出来。她会因为一件熟悉的物品想起父亲，会突然陷入回忆，也会害怕那些关于他的记忆慢慢消失。与此同时，成员 Ruoxi 也有类似的经历。外婆离世后，她看到妈妈经常吃不下饭，一个人默默的流泪。我们开始意识到：离别并不会随着时间自动结束。一个人失去的，也不仅仅是另一个人。\n我们发现，分手、亲人离世和宠物离世虽然看似都是“失去”，但用户真正面对的问题并不相同。失恋的人失去的可能是一段每天聊天的习惯、一个情绪出口，以及曾经共同期待的未来；经历亲人离世的人，可能反复陷入思念、遗憾和“害怕记忆逐渐消失”的情绪中；而失去宠物的人，则常常失去一位陪伴自己多年的家人。很多人真正需要解决的，并不是“如何忘记”，而是如何从“被过去困住”，慢慢变成“带着过去继续往前走”。\n因此，我们设计了 Make Again。\n用户首次进入产品后，可以通过 AI 深度对话，梳理自己的经历、情绪变化以及与那段关系相关的困惑。AI 会逐步建立用户个人画像和重要关系画像，并生成阶段性反馈，帮助用户理解自己真正想要解决的问题。在之后的长期陪伴中，AI 不只是等待用户主动倾诉，还会结合用户的聊天内容、情绪状态和特殊时间节点提供个性化陪伴。例如，在用户容易想起过去的时间给予温和引导；根据聊天内容自动记录每日情绪；定期生成情绪趋势与成长报告；帮助用户保存树洞信件、照片和重要记忆。产品还设计了真实用户之间的“树洞”互动。处于痛苦中的用户可以匿名留下文字或语音，而经历过类似离别、已经逐渐走出来的人，可以在未来给予回应，让用户感受到自己并不是独自经历这一切。当用户准备结束一段旅程时，Make Again 也会根据不同的离别类型提供不同的纪念与告别方式。例如，针对亲人离世，可以通过用户保存的声音和记忆生成一段鼓励；针对宠物离世，可以整理照片、视频和日常记录，生成专属纪念内容；针对失恋，则可以通过数字化回忆整理与告别仪式，帮助用户重新面对这段关系。\n现场，我们将完成 Make Again 的核心产品原型，包括 AI 深度访谈、个人画像生成、主界面情绪陪伴、树洞互动以及部分“结束旅程”体验的 Demo，并展示用户从第一次进入产品，到接受 AI 陪伴，再到逐渐完成自我整理的完整使用流程。\n我们的目标不是帮助用户快速忘记一个人。而是陪伴每一个被离别困住的人，慢慢学会：带着回忆，继续生活。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 一个帮助人接受离别，并重新学习如何带着这段关系继续生活的 AI 陪伴产品\n- GitHub 仓库: https://github.com/Make-Again/make-again', demo_link='https://youtu.be/nLX4jBf8my8', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:21:27', is_late='0', created_at='2026-08-30 08:21:27', updated_at='2026-09-01 12:31:22', leader_participant_id=NULL, presentation_link='https://kcn0a2dfvaz1.feishu.cn/wiki/JJ3GwnTJaiav1TkbgJkcmk82nWg?from=from_copylink', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99331/cover.jpg', screenshot_urls=NULL, video_link='https://youtu.be/nLX4jBf8my8', github_repo_url='https://github.com/Make-Again/make-again', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99331 AND event_id=4;
UPDATE projects SET event_id='4', team_id='82', captain_application_id='3110', topics='["sappho_love", "bluebox_sleep", "insta360_hervision"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='Binomial', project_name='一个给 Z 世代女性的亲密 AI 陪伴—— 安全、私密,只属于你。', tagline=NULL, demo_order='163', project_description='Nascent Love 是一款面向自我探索场景的智能亲密陪伴产品,致力于把原本单向、缺乏回应的独自探索,变成一场安全、可控、真正属于使用者自己的对话。产品以智能入体震动棒为硬件载体,结合双温度传感、双压力传感与六轴惯性测量,实时感知使用中的贴合状态与身体反馈,并通过环形 LED 与语音交互,让 AI 陪伴角色能够读懂节奏、给出恰当的回应,而不打断、不评判。所有关键决策始终掌握在用户手中：可自主设定被陪伴的方式,可随时通过语音安全词或设备实体按键立即中止——该指令完全在本地由 ESP32 芯片离线识别执行,不联网、不上传、不留痕迹,任何人都无法远程重新启动设备。使用结束后,系统会生成一份可回看、可编辑、也可随时删除的个人记录,是否高潮、如何感受,由用户自己确认,而非产品替其宣布。我们相信,女性的身体感受长期以来被简化、被定义、被他人的目光解读,而认识自己本该是一件不必羞耻、不必取悦任何人的事——Nascent Love 想做的,正是把这份认识的主动权,重新交还给每一位使用者自己。目前,产品已完成从硬件到软件的初步贯通：设备可稳定连接手机应用,环形灯能够根据不同模式与强度档位实时联动,官网已上线可供体验的产品演示页面,Android 端应用已能够真实连接实体设备并完成基础交互,项目正从概念验证阶段进入产品化打磨阶段。\n---\nG001 ai/hardware 赛道附加材料', demo_link='https://love.nascentuniversity.online', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:26:23', is_late='0', created_at='2026-08-30 08:26:23', updated_at='2026-09-01 12:31:24', leader_participant_id=NULL, presentation_link='https://loveppt.divesee.com', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99332/cover.jpg', screenshot_urls=NULL, video_link=NULL, github_repo_url=NULL, bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99332 AND event_id=4;
UPDATE projects SET event_id='4', team_id='90', captain_application_id='3011', topics='["liberlive_goodday", "ant_mulan_ai"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='智能药盒', project_name='开盒 ≠吃药，一个让子女不用每天打电话问"药吃了吗"的药盒。', tagline='面向独居慢病老人及其子女的智能药盒 + 微信小程序。', demo_order='164', project_description='就在这次黑客松现场，一位工作人员跟我们说了一件事。\n他家里人有认知障碍。他买过智能药盒。\n他说:“它能监测到药盒被打开，但问题是：如果家人开了盒却忘了吃药，App 依然会默认“已服药”并发送提醒。”\n那一刻我们才明白,\n市面上所有药盒解决的都是同一个问题:盒子开没开。而家属真正想知道的是另一个问题:药，到底少没少，\n这两个问题之间的距离，就是我们这个产品存在的理由。\n亮点一：我们判的不是"开没开"，是"药还在不在"\n  【痛点】\n    货架上的智能药盒，判定逻辑只有一条：盒盖被打开 = 已服药。\n    老人开盖看一眼又关上、拿出来放桌上忘了吃、\n    甚至只是找东西碰开了盒子 —— 全都会被记成"已服药"。\n\n    对认知障碍、独居老人的家属来说，这个勾是假的。\n\n  【我们做了什么】\n    盒盖上一个光电传感器，药格里一个光电传感器。两个独立。\n\n    开盖的那一瞬间，先记一次：这格里有药吗？\n    关盖后等读数稳定，再记一次：现在还有吗？\n\n    两次一对比，给出四种结论：\n\n      有药 → 没药        =  已取药\n      有药 → 还有药      =  ★ 开过盒，药还在\n      本来就空           =  未确认\n      到点压根没开盖     =  漏服\n亮点二：全机只有一个按钮，它不是用来操作的\n  【痛点】\n    绝大多数适老产品的失败方式都一样：\n    让老人学一个新界面。老人学不会，产品变摆设。\n\n    我们采访过社区老人后发现一个反直觉的事实：\n    老人其实记得住自己吃什么，他们有惯性。\n    真正焦虑的是子女。\n\n  【我们做了什么】\n    所以我们做了一个角色分工极端明确的产品：\n\n      老人这一侧：不装 App，不学任何东西。\n                  照常开盒、取药。\n                  想说话，按一下按钮。\n\n      子女这一侧：小程序是唯一界面，正常成人的界面，\n                  不做大字版 —— 因为老人根本不用它。\n\n    按钮按下去，老人可以跟 App 里的健康助手说话：\n    今天血糖多少、吃了什么。\n    助手会把这些话整理成结构化数据，\n    积累成复诊时能直接给医生看的记录。\n\n还有两个小但很戳人的设计\n【1】默认零推送。沉默即平安。\n\n  我们不做每天定时汇报。\n  一天最多一条推送，而且只在真的出问题时才发。\n\n  为什么：如果每天下午都有一条黄色提醒在闪，\n  子女两周内就会对它脱敏。\n  等真出事那一次的提醒，也就跟着失效了。\n\n\n【2】提醒声是家人的声音，不是滴滴声\n\n  到点没开盒：\n    第 1 次 —— 播放子女提前录好的一句话\n    7 分钟后 —— 加大音量，再说一次\n    15 分钟后 —— 才通知子女\n\n  子女在 App 上看到的不是一句冷冰冰的"未服药"，\n  而是完整的过程：\n\n    18:00 提醒（播放了您 8/20 录的那条）\n    18:07 加大音量再提醒\n    18:15 仍未取药，通知您\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 面向独居慢病老人及其子女的智能药盒 + 微信小程序。\n- GitHub 仓库: https://atomgit.com/gcw_zxeme7Ax/pillbox1\n- BOM / 原理图:\n  - https://atomgit.com/gcw_zxeme7Ax/pillbox1/blob/main/docs/%E5%8E%9F%E7%90%86%E5%9B%BE%E4%B8%8EBOM.md', demo_link='https://atomgit.com/gcw_zxeme7Ax/pillbox1', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:27:13', is_late='0', created_at='2026-08-30 08:27:13', updated_at='2026-09-01 12:31:27', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99333/cover.png', screenshot_urls=NULL, video_link='https://atomgit.com/gcw_zxeme7Ax/pillbox1', github_repo_url='https://atomgit.com/gcw_zxeme7Ax/pillbox1', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99333 AND event_id=4;
UPDATE projects SET event_id='4', team_id='198', captain_application_id='4859', topics='["liberlive_goodday", "sappho_love", "eazo_4her", "proya_feelings", "miaoda_super"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='干巴得！', project_name='Ta-da!｜互动生日惊喜 H5', tagline='Ta-da! 把生日快乐，好好装起来。', demo_order='165', project_description='Ta-da! 的起点，是因为我和几个老朋友之间，一直都保留着给彼此过生日的习惯。\n中学的时候，我们会彼此写明信片、塞小纸条，写很多对未来的期许，也写很多想送给彼此的祝福。后来大家去了不同的城市，工作越来越忙，生日祝福慢慢变成了微信里的几句话和一个礼物链接。我想找到一种更适合现在生活的表达方式，把这种“认真准备一点东西给对方”的感觉留下来。\n所以有了 Ta-da! —— 一款移动端互动生日惊喜 H5。它把原本一眼就能看完的电子贺卡，变成一段可以参与、可以一点点打开的生日惊喜。\n送礼人通过创建端完成一份生日惊喜：填写双方信息，选择解锁方式，制作生日贺卡或照片手帐，再附上一份礼物。收礼人打开后，可以先玩一个很轻的小游戏，也可以直接进入内容，然后阅读祝福、查看手帐，最后亲手打开礼物。\n目前已经完成五步创建流程、找礼物 / 剪刀石头布 / 吹蜡烛三种小游戏、两套生日贺卡、1/2/3 张照片的手帐模板、照片构图调整、礼物揭晓，以及 Sender 到 Receiver 的完整本地预览流程。整体视觉以奶油色、珊瑚粉和薄荷绿为主，并加入 Tada 小怪兽作为陪伴和惊喜揭晓的角色。\nTa-da! 想做的，是让生日祝福不只停在一句话里，而是变成一段更完整、更有趣的互动体验。\n---\nG001 软件 赛道附加材料\n\n- Slogan: Ta-da! 把生日快乐，好好装起来。\n- GitHub 仓库: https://github.com/miso-zm/ta-da-birthday-surprise', demo_link='https://my.feishu.cn/docx/IMO5dDocOo6cdVx26bKc6tz9nmJ?from=from_copylink', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:27:29', is_late='0', created_at='2026-08-30 08:27:29', updated_at='2026-09-01 12:31:31', leader_participant_id=NULL, presentation_link='https://my.feishu.cn/docx/IMO5dDocOo6cdVx26bKc6tz9nmJ?from=from_copylink', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99334/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a936db2e5d31_95185d68a7d335e5.jpg","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a936db67dd58_3f172e20c2d89166.jpg","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a936dbc05544_0f7a363baa3bfcdf.jpg"]', video_link='https://my.feishu.cn/docx/IMO5dDocOo6cdVx26bKc6tz9nmJ?from=from_copylink', github_repo_url='https://github.com/miso-zm/ta-da-birthday-surprise', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99334 AND event_id=4;
UPDATE projects SET event_id='4', team_id='322', captain_application_id='5059', topics='["sappho_love", "eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='内界CAVE', project_name='内界CAVE', tagline='内界 CAVE 是一款面向成年女性的身体认知、亲密关系与自我边界成长应用。', demo_order='166', project_description='内界 CAVE 是一款面向成年女性的身体认知、亲密关系与自我边界成长应用。在四天黑客松中，我们完成了从 Expo/React Native 移动端、本地加密数据层、邮箱验证码身份后端，到 Astro 官网与在线演示的完整纵向闭环。用户可通过六页结构化旅程梳理期待与担忧，在非排序的行为地图中辨认边界，通过明确标注为预设路径的情境练习练习暂停、拒绝和改变主意，最终生成可编辑的沟通卡，并在“内界手记”中持续记录关键事件、感受变化与阶段成长。产品不替用户判断是否“准备好”，不把亲密行为设计成升级路线。核心私密内容本地优先保存；邮箱登录只用于同一设备上的账号隔离，不上传旅程、卡片或手记正文。当前移动端主流程不调用生成式 AI；仓库保留了受约束 AI gateway 研究，未来仅在用户主动选择并授权具体记录后，用于权威信息检索、功能与课程导航及手记辅助，敏感问题将拒答并转介专业机构。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 内界 CAVE 是一款面向成年女性的身体认知、亲密关系与自我边界成长应用。\n- GitHub 仓库: https://github.com/CarterWells111/CAVE', demo_link='https://zhuanlan.zhihu.com/p/2076780123588764152', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:29:00', is_late='0', created_at='2026-08-30 08:29:00', updated_at='2026-09-01 12:31:34', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99335/cover.png', screenshot_urls=NULL, video_link='https://neijiecave.com/demo/', github_repo_url='https://github.com/CarterWells111/CAVE', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99335 AND event_id=4;
UPDATE projects SET event_id='4', team_id='106', captain_application_id='4669', topics='["liberlive_goodday", "zhiyuan_herrobot", "zeroth_linku", "sappho_love", "miaoda_super", "proya_feelings", "eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='DO点正事', project_name='ECHO', tagline='Yes，I Do！', demo_order='167', project_description='当越来越多可穿戴设备开始记录身体数据，我们获得了越来越多数字，却未必因此更了解自己的身体。尤其在女性身体探索中，生理变化并不能直接等同于舒服、喜欢或意愿。基于这一问题，我们设计了 ECHO——一套由 Smart Ring、ECHO App 与 Haptic Device（触觉反馈设备）组成的女本位身体感知互动系统。 Smart Ring 感知心率、血氧变化，并兼具可穿戴饰品的个性化表达；Haptic Device 提供压力信号与实体按键输入，并接收经过安全策略确认后的振动反馈；App 负责设备连接、状态判断、AI 个体化互动、语音及安全控制。ECHO 将身体变化作为互动线索，而不是替用户判断感受、偏好或意愿，让身体的解释权始终留在用户手中。目前团队已完成用户研究、产品定义、UI/UX 及软硬件原型的第一阶段开发，并建立身体信号—状态判断—AI/语音互动—安全触觉反馈的核心闭环，同时通过问卷、访谈、UI 共创与公开内容完成第一轮用户验证。下一阶段，我们将进一步完成硬件整合与稳定性测试，引入种子用户开展 Beta 体验，验证长期身体记录与个体化互动的价值，并继续探索 ECHO 的产品化与商业化路径。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: Yes，I Do！\n- GitHub 仓库: https://github.com/fenixIves/ECHO\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a936f9a3ff4f_549b1fd775926ce1.png)', demo_link='https://echo-yesido-d3gv98ra046e946df-1477591684.tcloudbaseapp.com/2.0.0/', xiaohongshu_link='https://xhslink.cn/o/4wTNdl75TuY', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:31:55', is_late='0', created_at='2026-08-30 08:31:55', updated_at='2026-09-01 12:31:38', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99336/cover.png', screenshot_urls=NULL, video_link='https://b23.tv/kKhY0Dh', github_repo_url='https://github.com/fenixIves/ECHO', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99336 AND event_id=4;
UPDATE projects SET event_id='4', team_id='105', captain_application_id='5259', topics='["sappho_love", "ant_mulan_ai"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='Isyou', project_name='看见自己，也看见更多可能', tagline='看见自己，也看见更多可能', demo_order='168', project_description='# 项目说明\n\n一句话概括：Isyou 是一款面向多元神经群体的职业探索与成长 Coach，通过具体经历理解用户，把能力画像连接到真实岗位，并将职业差距转化为每天可以完成的小行动。\n\n## 1. 问题\n\n传统招聘和职业测评通常依赖“沟通能力强不强”“是否抗压”等抽象自评。这类表达容易忽略环境、任务结构和工作方式的差异，也会给不擅长自我包装的用户带来较高负担。\n\n现有产品主要存在四个问题：\n\n- 抽象标签多，用户很难准确描述自己。\n- 岗位推荐只看职位名称，较少分析具体任务、规则和工作环境。\n- 推荐结果缺少依据，用户不知道“为什么适合”。\n- 培训内容通常是固定课程，没有根据个人差距和实际进度动态调整。\n\n## 2. 方案\n\nIsyou 将职业探索设计成一条可追溯的完整路径：\n\n1. **结构化能力探索**  \n   通过生活场景、具体经历和卡片选项收集信息，允许跳过、不确定和自由补充，不要求用户先给自己贴标签。\n\n2. **能力图谱**  \n   将回答整理为能力倾向、环境偏好、约束条件和待确认项。每条判断都尽量保留来源，未知信息不会被写成能力缺陷。\n\n3. **岗位匹配与真实岗位检索**  \n   从任务结构、环境要求和规则稳定性等维度匹配岗位，同时支持联网检索公开招聘页面、核验职位信息并导出选定 JD。\n\n4. **通用成长 Coach**  \n   Coach 自动接收当前岗位、能力画像和岗位差距，依次生成 Gap Map、阶段计划和每日任务。用户提交结果后，系统将其保存为待复核证据，并在下一学习日先 Review，再调整后续任务。\n\n## 3. 完成度\n\n目前已经形成可以完整演示的端到端 Demo：\n\n- 能力探索问卷与本地进度保存。\n- 可追溯的能力图谱。\n- 5 个稳定的演示岗位匹配结果。\n- 真实岗位候选搜索、公开页面核验与 JD 下载。\n- 岗位详情到通用 Coach 的上下文传递。\n- Gap Map、阶段计划、每日任务和多日 Review。\n- 暂停、恢复、卡点反馈和任务降级。\n- 前端与 Coach API 同源运行。\n- 演示岗位与真实岗位明确区分。\n- 20 项自动化测试全部通过。\n- GitHub 公开仓库和本地运行说明已完成。\n\n当前仍属于 Hackathon Demo：Coach 会话主要保存在服务进程内存中，联网岗位搜索依赖外部 API、网络状态及招聘页面的可访问性。\n\n## 4. 下一步\n\n1. **数据持久化**  \n   接入数据库和账号体系，长期保存画像、Coach 会话、任务记录与能力证据。\n\n2. **提高 Coach 个性化能力**  \n   在现有状态机和安全边界内接入可控的模型能力，使任务内容更贴合岗位、用户起点和历史反馈。\n\n3. **完善真实岗位链路**  \n   增加更多招聘来源、搜索缓存、异步任务、失败重试和岗位失效检测。\n\n4. **开展真实用户测试**  \n   邀请多元神经群体、职业顾问和招聘方参与测试，重点验证提问压力、推荐准确性和任务可执行性。\n\n5. **加强隐私与可访问性**  \n   完善数据授权、删除机制、日志脱敏、键盘操作、屏幕阅读器支持和低刺激视觉模式。\n\n6. **生产化部署**  \n   增加 HTTPS、监控告警、限流、数据库备份和模型成本控制，使项目从可演示 Demo 走向可持续使用的产品。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 看见自己，也看见更多可能\n- GitHub 仓库: https://github.com/Marukooo11/Isyou', demo_link='https://github.com/Marukooo11/Isyou', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:32:07', is_late='0', created_at='2026-08-30 08:32:07', updated_at='2026-09-01 12:31:38', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99337/cover.jpg', screenshot_urls=NULL, video_link='https://github.com/Marukooo11/Isyou', github_repo_url='https://github.com/Marukooo11/Isyou', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99337 AND event_id=4;
UPDATE projects SET event_id='4', team_id='151', captain_application_id='4889', topics='["miaoda_super", "liberlive_goodday", "zhiyuan_herrobot", "eazo_4her", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='五仁月饼', project_name='月狸 Moonli', tagline='说着说着，看见自己', demo_order='169', project_description='【问题】人生过渡阶段年轻人情绪与想法无处倾诉，现有 AI 陪伴、日记、疗愈类产品均有短板，缺少低压力的自我沉淀空间。\n【方案】月狸 Moonli 是自我看见型陪伴 AI，以优势视角设计，不诊断评判；自动归档对话、沉淀自我、生成每日来信，帮用户看见自己；本地优先存储，所有洞察可溯源。\n【现场完成】完成四大模块交互 Demo、对话规则引擎、沉淀 - 溯源 - 来信核心链路；完成月光灵兽世界观塑造与全套视觉素材、交互原型落地。\n【使用方式】进入传送门倾诉，对话自动沉淀为光源与月痕；次日查看每日来信，洞察可溯源跳转；基础功能免费，深度功能订阅解锁。\n\n网页入口：https://ignored-forming-transmit-norman.trycloudflare.com\n---\nG001 软件 赛道附加材料\n\n- Slogan: 说着说着，看见自己\n- GitHub 仓库: https://github.com/Flowersou1/content-creation-companion', demo_link='https://pan.baidu.com/s/1pgLKesyQKPH48k8dVb_snQ?pwd=494p', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:36:13', is_late='0', created_at='2026-08-30 08:36:13', updated_at='2026-09-01 12:31:38', leader_participant_id=NULL, presentation_link='https://h31a0shuh9.feishu.cn/wiki/MxeTwzy24igGhuktM1bchWyvnjc?from=from_copylink', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99338/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937f2d3752d_ed2a8f57f94cc910.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937f413224b_89c642f1ef9155d0.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937f6caa21e_b228682e0e70df18.png"]', video_link='https://pan.baidu.com/s/1pgLKesyQKPH48k8dVb_snQ?pwd=494p', github_repo_url='https://github.com/Flowersou1/content-creation-companion', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99338 AND event_id=4;
UPDATE projects SET event_id='4', team_id='150', captain_application_id='3204', topics='["miaoda_super", "proya_feelings", "qingxian_self", "zhiyuan_herrobot", "eazo_4her", "insta360_hervision", "ciie_smartchain", "sappho_love", "ant_mulan_ai", "frostsullivan_proof", "beichen_cloudcomm", "bluebox_sleep"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='PMOS多囊专研社', project_name='Pomi多囊闺蜜', tagline='戳戳Pomi,翻译你的身体', demo_order='170', project_description='POMI：https://pomi.wildernotrack.me/\n首款AI +区块链的女性多囊患者健康管理工具。\n帮多囊患者把散落各家医院的检查单，变成一页医生敢直接看的复诊报告。\n\n【背景意义】据世界卫生组织统计，全球确诊多囊患者（PMOS，原名PCOS）约1.7亿，我国确诊患者约 2400 万。\n【市场调研】收集38 份医生问卷中，50+ 份患者问卷，系统调研 30+ 竞品；约90%的医生愿意参考 AI 整理的患者报告\n【核心痛点】患者长期承受病情与情绪双重压力，面临三重困境：1.跨院资料缺乏连贯性；2.指标繁杂难以持续监测；3.诊断效率低，面诊时间短讲不清碎片化信息。\n【产品功能】① 检验单智能识别；② 长期异常检验指标趋势线可视化③ 电子病历照片医院签署存证，接入医院管理系统，KYB验证，患者医生无感；④ 用药计划管理——医嘱打卡可视化。\n【技术栈】Flutter 客户端 + FastAPI 后端 + SQLite 数据库 + Qwen3.8-VL OCR + Nginx 单服务器部署。\n【已交付】Android 下载安装包+ 全用户体验网址（https://pomi.wildernotrack.me/）。\n【品牌运营】开通品牌公众号、小红书、微博等社媒推文阅读量当天即破25万+。\n【合作单位与商业化】深度走访3家三甲医院，已与 15 位医生来自达成合作意向，\n【差异化与商业价值】POMI精准锚定多囊群体，以就诊效率为产品目标：患者端高效讲清病情，医生端免于拼凑散落的病史、用药与症状，提升医患沟通质量。这一“碎片信息→完整证据链”的核心能力可迁移：症状隐匿持续、记录碎片化散落各院，是慢病群体的共同困境——多囊是我们选定的第一个切口，2400 万患者背后，是数亿慢病人群的同一命题。\n【壁垒】三层可复利资产——用户每次纠错沉淀为独家医疗标注数据集，识别精度随使用增长；循证报告框架经妇产科顾问逐项校准，构成专业性门槛；区块链来源签署让每份材料的来源、版本与时间不可静默篡改，叠加 15 位医生意向合作，构成通往真实医院试点的先发通道。\n\n合规：报告框架遵循 2023 国际循证指南、鹿特丹标准与门诊 SOAP 结构，经妇产科顾问逐项校准；全程不诊断、不荐药、不替代医生。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 戳戳Pomi,翻译你的身体\n- GitHub 仓库: https://github.com/healyops-blip/PMOS-ENclaire-app', demo_link='https://pomi.wildernotrack.me/', xiaohongshu_link='https://weibo.com/6201922881/5336654497973560?sourceType=weixin&from=10G8195010&wm=9856_0004&featurecode=newtitle&s_channel=4&s_trans=E1DzeghtI8pCs0wmBHgr8g%3D%3D_5336654497973560_s', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:36:46', is_late='0', created_at='2026-08-30 08:36:46', updated_at='2026-09-01 12:31:45', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99339/cover.jpg', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937a261847a_c523295c557768d8.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937a3b12dd0_e16c0528234a6802.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937afd8e278_c1c0258e9602fa34.jpg"]', video_link='https://www.bilibili.com/video/BV1hq4U6xEqg/?spm_id_from=333.1387.homepage.video_card.click&vd_source=bebc2bf3684cc53cabef863ed4a45855', github_repo_url='https://github.com/healyops-blip/PMOS-ENclaire-app', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 08:37:01', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99339 AND event_id=4;
UPDATE projects SET event_id='4', team_id='128', captain_application_id='3266', topics='["tripo_hergaze"]', sponsor_consents='{"tripo_hergaze": {"rights": "非独占、全球范围、免费", "topic_code": "tripo_hergaze", "sponsor_key": "tripo", "topic_title": "为她而设计 — Her Gaze, Her Game", "consented_at": "2026-08-29T00:09:12+08:00", "consented_ip": "210.12.140.210", "sponsor_label": "Tripo 3D", "sponsor_full_name": "Tripo 3D (Vietnam)", "consented_user_agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0"}}', application_id=NULL, session=NULL, cohort=NULL, team_name='长沙小分队', project_name='妈妈二十岁', tagline='Slogan：撬开那把锁，替她走一遍二十岁的路', demo_order='171', project_description='一、说明的问题\n情感叙事游戏“两张皮”：讲故事靠大段文本和播片，玩法与情绪无关，玩家是观众，不是当事人。\n泪点靠堆，不靠设计：煽情桥段可预期、可免疫；反转类叙事一旦被剧透，情绪价值直接归零。\n小团队做不出完整闭环：多数限时作品停在原型——有玩法没结尾、有 demo 没结算。\n本作针对这三点各给出一个解法。\n\n二、方案\n机制即叙事：三章里“方向反转、获得冲刺、最后一章只能向左慢慢走”既是玩法变化，也是剧情本身；全程几乎无文本，故事由关卡物件、四篇日记和环境演出承担。\n极佳手感：土狼时间 0.15 秒、跳跃缓冲 0.1 秒、可变跳高、判定内缩 2 像素——死了只怪自己，不怪操作；无生命值、无死亡惩罚，对手残玩家零门槛。\n音乐即机制：120 BPM 节拍器驱动全部陷阱周期运动，“听两拍，就知道什么时候该走”；音乐骤停本身是演出手段。\n反转防泄底设计：章节标题不上屏、日记日期即伏笔；全游戏只藏一件事，藏在日期里、藏在倒着走的路上——任何对外材料一个字不泄底，只能亲手玩到。\n48 小时 AI 流水线：玩法内核、流程表现、美术生成、音乐制作四线并行；占位资产程序化生成、二章破败美术由 AI 转换一章素材而来，保证交付完整闭环而非原型。\n三、现场完成内容\n现场完成了策划案的全部程序、美术、音乐设计：\n程序\n手感内核：加减速曲线、转向无打滑、可变跳高、顶点滞空、撞角修正\n12 种节拍同步陷阱：搓衣板、鸡毛掸子摆锤、酒瓶、飞溅零件、逆向传送带、冲压机、荆棘、腐心平台、发霉巨心、玻璃渣、啼哭声波、账单纸风\nConductor 节拍器 + 音乐骤停接口\n无惩罚死亡重生：碎裂粒子、1 秒重生、台灯检查点、防连死保护\n二章冲刺(24 像素瞬发、空中一次、冷却 1 秒)与 6 格缺口“起跳 + 空中冲刺”关卡设计\n三章全流程：OP 演出、状态机、眼睑过场、日记打字机 UI、HUD 记忆光片、开锁演出、黑屏大字、翻页转场、主菜单\nLUT 双画风调色(一章写实 / 二章梦核)\n\n美术\n三章三套画面：一章 1990s 写实、二章梦核破败(AI 转换生成)、三章双画风老街\n平台/地面 tile 体系、12 种陷阱美术、台灯/日记桌/门道具、主角与年老母亲精灵表\n\n音乐\nM1(一章，轻微克制)、M2(二章，渐强)、M3(三章)三轨独立原创\n结尾一段童声清唱(曲目现场揭晓)\n\n内容与物料\n四篇日记正文，每篇 200 字以上，数字细节构成伏笔证据链\n配套路演 PPT(评委向)、玩家向展屏文案、易拉宝与摊位物料\n---\nG001 游戏 赛道附加材料\n\n- Slogan: Slogan：撬开那把锁，替她走一遍二十岁的路\n- GitHub 仓库: https://github.com/qing99half/momat20\n- 游戏玩法说明:\n  运行：Windows 单文件 exe(PCK 内嵌)，双击即玩，免安装、零配置。\n  操作：ad移动，w/空格跳跃，Shift/f/右键 冲刺(第二章解锁)；日记正文阶段按任意键加速。\n  建议体验：一个人、一副耳机、15~20 分钟一口气通关；中途不要查任何剧透——结尾那段童声清唱，是留给通关者的。\n  流程：主菜单开始 → OP 演出 → 两章八关 → 只能向左走的最后一章 → 结算演出与“开发者的话”。', demo_link='https://pan.baidu.com/s/16lRaINPJgVIxjkFy1Akv9Q?pwd=tbqv', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:37:12', is_late='0', created_at='2026-08-30 08:37:12', updated_at='2026-09-01 12:31:46', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99340/cover.jpg', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/16lRaINPJgVIxjkFy1Akv9Q?pwd=tbqv', github_repo_url='https://github.com/qing99half/momat20', bom_link_text=NULL, gameplay_description='运行：Windows 单文件 exe(PCK 内嵌)，双击即玩，免安装、零配置。\n操作：ad移动，w/空格跳跃，Shift/f/右键 冲刺(第二章解锁)；日记正文阶段按任意键加速。\n建议体验：一个人、一副耳机、15~20 分钟一口气通关；中途不要查任何剧透——结尾那段童声清唱，是留给通关者的。\n流程：主菜单开始 → OP 演出 → 两章八关 → 只能向左走的最后一章 → 结算演出与“开发者的话”。', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99340 AND event_id=4;
UPDATE projects SET event_id='4', team_id='187', captain_application_id='4621', topics='["ant_mulan_ai", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='puppyland', project_name='puppyland', tagline='我们想创造一个温暖的空间，重新解释宠物离世。', demo_order='172', project_description='由于宠物生命的有限，养宠人终有一天不可避免地要面对它的离开。\n\n死亡意味着生命的结束，但对于留下来的记忆来说，关系并不会因此立即结束。对于人与宠物之间的情感而言，告别并不意味着关系的终结。\n\n事实离真相最近，却也往往最难以接受。\n\n这个世界上有很多人，在面对离别的时候，需要的也许并不是一个事实上的解决方案，而是一个可以安放情感的媒介。\n\n人类其实一直都在通过故事、想象和仪式，去理解那些无法改变的事情。\n想象力有时是一种解药。\n\n因为它离事实最远，却让我们拥有了另一种理解和面对离别的可能。\n\n我知道死亡本身无法被改变。\n\n所以，我想创造一个允许我们想象的地方——一个让离开不只是失去，让记忆和爱能够以另一种方式继续存在的地方。\n\n于是，我们做了一个和宠物离世、记忆有关的AI产品，希望把关于TA的照片、\n\n声音和故事，变成一个会不断生长的虚拟家园。  \n\n传统宠物纪念产品基本是在保存或者把已经发生过的事情保存下来，这类产品的核心就是纪念、记录和情感表达。 \n\n但我们不是想把回忆留在过去，而是希望小狗在另一个世界继续生活。所以用户进入之后看到的不是：“这是我的狗，\n它已经去世了。”\n\n而是：“它现在正在另一个地方生活。”\n\n它有自己的房间、会跑、会玩、会睡觉，会每天给你写信。\n\n我们调研了一些采访者，问了他们一些问题，直到我们意识到，如果只留下一个问题，\n我们最想问什么？\n\n我最想问自己什么呢？\n\n我想是—你的遗憾是什么？\n\n1. 从「纪念一只宠物」开始\n\n最初，我们希望关注的是宠物离世后的情感陪伴。\n\n很多人会认为“宠物只是宠物”，但对于陪伴我们多年的人来说，它其实已经是家庭成员，是生活的一部分。\n\n所以你们希望通过这个项目，让更多人意识到：\n\n宠物的生命虽然结束了，但人与宠物之间的关系并不会因此结束。\n\n2. 从「一个人的记忆」走向「共同创作一个世界」\n\n这就是你说的共创空间。\n\n现在是：\n\n我为我的狗建立一个空间。\n\n未来：\n\n所有离开的宠物，都可以来到这里。\n\n每一个主人都可以带着自己的记忆、故事、照片、声音，甚至一个小小的习惯，把自己的宠物带进这个世界。\n\n于是这个世界不是单方面创造的，而是由无数个“舍不得忘记它的人”共同创造出来的。\n\n最终形成一个「宠物的另一个世界」\n\n我觉得这里可以成为你们未来展望里最有想象力的一层。\n\n现实世界里，我们无法让已经离开的宠物回来。\n\n但在想象的世界里，我们可以。\n\n它们可以在这里：\n\n* 重新拥有自己的家\n* 遇见其他已经离开的宠物\n* 继续散步、玩耍、睡觉\n* 被主人留下的记忆滋养\n* 甚至拥有新的故事\n\n于是这个空间慢慢不再只是一个纪念馆。\n\n它会变成一个：\n\n属于所有离开现实世界的宠物的共同家园。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 我们想创造一个温暖的空间，重新解释宠物离世。\n- GitHub 仓库: https://github.com/puppy-island/puppyland', demo_link='https://puppyland.agentverse.social/', xiaohongshu_link='https://xhslink.cn/o/499GtOrKFPO', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:38:11', is_late='0', created_at='2026-08-30 08:38:11', updated_at='2026-09-01 12:31:51', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99341/cover.jpg', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/16yei5U5rTuXN9HKNZ6FoAQ?pwd=Mw7E', github_repo_url='https://github.com/puppy-island/puppyland', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99341 AND event_id=4;
UPDATE projects SET event_id='4', team_id='124', captain_application_id='4762', topics='["miaoda_super", "liberlive_goodday", "eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='知食分子', project_name='七分饱', tagline='七分饱 · 吃到刚好 — 不是算热量，是听懂身体', demo_order='173', project_description='项目核心理念：「七分饱 = 三分饿」—— 不在餐前干涉既定饮食选择，而在餐中充当即时的外部视觉刹车，饭后通过Agent 宠物对话建立身体感知闭环，将“少吃的节制”重构为给身体的舒适呼吸感与喂饱宠物的爱心馈赠。\n\n一、项目解决了什么问题？\n1. 生理感知延迟导致被动吃撑\n人体饱腹感信号从胃部传导至大脑中枢通常存在 15 至 20 分钟的生理延迟。在快节奏办公、进餐时间受限或多人社交聚餐等场景下，用户进食速度往往偏快，注意力被工作或社交分散。当大脑最终接收到“吃饱”信号时，生理摄入往往早已严重超量，导致饭后腹胀与精神萎靡。\n2. 传统饮食管理工具门槛高且脱离现实场景\n市面现有的健康管理与控卡 App 普遍采取两种极端模式：餐前给出单一严格的定制食谱，或餐后要求繁琐记录每种食材克重并计算卡路里。但现实中打工人与学生党高频面对的是外卖、快餐、食堂打饭与社交聚餐，缺乏自主搭配与精准分量把控空间，繁琐与脱离实际的机制极难让用户长期坚持。\n3. “节制与剩饭”的负面心理包袱\n在传统认知中，“没吃满”常伴随挨饿与剥夺感，而“必须光盘”的心理包袱容易驱使人们在已经饱腹时强行吃完。此外，一旦偶发吃撑，用户容易产生内疚与挫败感，进而彻底放弃健康记录。\n4. 静态算法模型无法匹配个体动态胃口\n千人千面的真实胃口差异巨大，且随着作息与进餐结构动态变化。通用静态摄入标准无法感知个体差异，更缺乏依据真实反馈持续自我迭代与收敛的自适应机制。\n\n二、使用了哪些方案？\n1. 认知重构与正向情感激励方案\n心智重塑：将“三分饿”定义为身体处于低负担、高专注状态时的呼吸感，消解减脂或控量过程中的匮乏感。\n情感代偿机制：将少吃的饭量转化为喂饱伴生 Agent 宠物的爱心馈赠，形成正向情感回馈闭环。\n放纵保护与连击维系：引入多邻国式打卡火焰与放纵保护卡，偶发吃撑如实反馈即可抵扣断签，包容真实人性。\n2. 餐前即时视觉刹车与双场景自适应\n一人食场景：餐前单张照片输入，算法自适应输出分菜品结构化卡片，直接标注分数比例建议（如“建议吃 4/5”、“建议吃 2/3”，低能量蔬菜标注“放心吃 ✅”），建立清晰的量化刹车锚点。\n多人聚餐场景：通过大语言模型生成针对性的进餐顺序与避坑指南（如优先清蒸/白灼、避开吸油底料、主食限量等社交进餐策略）。\n3. 轻量人机协同纠偏（HITL）\n提供“小七说对了吗？”极简纠偏面板，支持 Top-K 候选词一键点选替换（如“咖喱鸡”替换为“咖喱牛肉”），以及“偏少 / 适中 / 偏多 / 超大”4 档定性份量微调。前端本地即时重绘建议结果，实现 0 延迟响应且免除二次视觉 API 调用。\n4. 自研数学与自适应算法体系\nBMR 动态基准：采用 Mifflin–St Jeor 方程结合体重管理目标系数与三餐分配权重构建动态单餐能量基准。\nHFS 饱腹评分模型：综合餐食热量、蛋白质、膳食纤维与脂肪等关键维度，回归计算健康饱腹指数，与目标摄入形成双约束推荐。\n贝叶斯 / 卡尔曼增量自适应更新：餐后两轮分支对话提取执行比例与饱腹感反馈指标（-1 饿 / 0 刚好 / +1 撑），动态修正后验食量配额，并引入测量噪声阻尼机制防止单次异常波动破坏长期稳定性。\n\n三、现场完成的内容\n1. P0 餐前视觉与量化交互闭环\n完成用户基础身体数据设置模块与 Mifflin–St Jeor BMR 自动计算。\n打通微信小程序原生相机调用与智谱 AI 图像识别接口，实现多菜品结构化抽取与营养分类打标。\n落地一人食与多人聚餐 Switch 场景切换，完成分菜品分数卡片渲染与“小七说对了吗？”HITL 纠偏面板。\n2. P0 餐后对话与自适应校准闭环\n接入智谱 GLM 驱动的拟人化宠物 Agent，实现分支自适应对话与结构化饱腹感槽位提取。\n封装并跑通 JavaScript / Node.js 贝叶斯与卡尔曼增量校准模型，实现千人千面食量配额动态收敛。\n3. P1 激励系统与演示支持\n上线觉察提醒认知弹窗、“全吃完 + 刚刚好”触发 2.0 倍 EXP 暴击的「神准光盘」成就系统。\n制作 3D 打印 NFC 实体宠物标尺挂牌，支持手机碰一碰直达反馈页。\n在小程序内开发“时间机器”开发者演示面板，支持一键注入历史打卡数据以秒级演播模型收敛与宠物进阶。\n\n四、使用的方式与技术架构\n1. 前端交互层\n采用微信小程序原生全栈架构（WXML / WXSS / TypeScript / JavaScript），负责相机实时调用、结构化分数建议卡片渲染、4 档份量定性交互组件以及伴生宠物多态情绪与成长状态机呈现。\n2. 云端与后端架构\n依托微信云开发平台（Node.js 云函数 + 云数据库 + 云存储），承载轻量后端业务调度、用户鉴权、数据持久化存储、容灾降级与端云分流路由网关。\n3. AI 能力层\n视觉能力：集成智谱 AI 图像识别 API，实现食物主体分割、多菜品识别、营养成分打标与 Top-K 候选词抽取。\n语言与 Agent 能力：基于智谱 GLM 大语言模型构建拟人化宠物伙伴，实现多轮情感对话、意图识别与自由文本槽位抽取。\n4. 算法中枢与工程降本策略\n自研算法体系：在本地与云函数中协同运行 BMR 映射、HFS 回归以及贝叶斯增量更新算法。\n端云分流架构：常规确定性交互走前端本地规则与正则处理，复杂自由文本调用大语言模型，在保证毫秒级交互体验的同时大幅削减 Token 开销。\n\nhttps://my.feishu.cn/wiki/Ehplw1jORiKvX8kNVGGckpacnkc?renamingWikiNode=true\n---\nG001 软件 赛道附加材料\n\n- Slogan: 七分饱 · 吃到刚好 — 不是算热量，是听懂身体\n- GitHub 仓库: https://github.com/9-71/SevenFull', demo_link='https://pan.baidu.com/s/1zuZ5qDePo_c1iqY7OLRqjA?pwd=dsyn', xiaohongshu_link='https://xhslink.cn/o/3DyqYxvGuoC', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:39:28', is_late='0', created_at='2026-08-30 08:39:28', updated_at='2026-09-01 12:31:53', leader_participant_id=NULL, presentation_link='https://khsj.cn/8ibrc3u0u0u927q', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99342/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937717e3f78_063713e68d3ae3e1.png"]', video_link='https://pan.baidu.com/s/1zuZ5qDePo_c1iqY7OLRqjA?pwd=dsyn', github_repo_url='https://github.com/9-71/SevenFull', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99342 AND event_id=4;
UPDATE projects SET event_id='4', team_id='261', captain_application_id='4998', topics='["bluebox_sleep", "ciie_smartchain", "liberlive_goodday", "miaoda_super", "proya_feelings", "eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='一人合唱', project_name='夜安Calmnight', tagline='夜安是一套让女性全周期睡个好觉的智能睡眠调解方案', demo_order='174', project_description='零、简介\n夜安 YeAn 是一个面向女性全周期的智能睡眠温度决策系统，关注月经期、围绝经期、孕产期及日常睡眠中的热醒、怕冷、空调不适和多设备难协调问题。夜安不是单一空调或床垫，而是把用户主观冷热感、环境温湿度、生理信号、设备能力和用户反馈放进一个闭环，判断什么时候制冷、制热或不动作，以及应该优先使用床面、空调还是其他设备。\n\n\n\n一、问题\n人在睡眠过程中会受到体温、环境温度、皮肤状态和睡眠阶段变化的影响。传统空调或恒温设备通常只能调节整体环境，容易出现温度过冷、过热、频繁打扰和能耗较高等问题，无法根据人的实时状态进行细致调节。\n二、方案\n夜安通过采集人体状态与环境状态，识别用户当前的冷热舒适程度，并将状态映射为三种响应：\n1. 用户感觉偏热时，执行局部制冷。\n2. 用户状态正常时，保持当前环境，不主动打扰。\n3. 用户感觉偏冷时，执行局部加热。\n系统遵循“感知—判断—执行—反馈”的闭环逻辑，目标是在用户需要时及时调节，在用户舒适时保持安静和稳定。\n三、现场完成内容\n1. 完成 React Native 演示控制台。\n2. 完成热、正常、冷三种状态的交互切换。\n3. 完成皮肤温度、皮肤电活动、环境温度和睡眠阶段等状态信息展示。\n4. 完成制冷、不调节、加热三种演示结果展示。\n5. 完成感知、判断、执行、反馈的流程可视化。\n6. 完成作品提交信息区域，可填写作品口号、代码仓库、封面图和演示视频地址。\n7. 完成公开比赛演示仓库，核心算法、硬件、模型、数据库和研究资料继续保存在私有仓库中。\n四、使用方式\n打开代码仓库后，在本地执行：\nnpm install\nnpx expo start --web\n然后使用浏览器打开终端显示的地址，即可进入演示控制台。\n建议按照以下顺序进行现场演示：\n1. 点击“热”，展示局部制冷。\n2. 点击“正常”，展示系统保持稳定、不主动打扰。\n3. 点击“冷”，展示局部加热。\n4. 向下滑动，展示项目说明和提交信息。\n5. 展示公开仓库地址及项目主题设置。\n当前公开演示仓库：\nhttps://github.com/raccoonBK/yean-hackthon0830\n说明：当前公开仓库主要用于比赛评审和演示，状态切换使用的是演示映射，不直接控制真实设备，也不包含正式核心算法。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 夜安是一套让女性全周期睡个好觉的智能睡眠调解方案\n- GitHub 仓库: https://github.com/raccoonBK/yean-hackthon0830', demo_link='https://pan.baidu.com/s/1j5AleYsqQnE6aicRPMcK8w?pwd=r9dj', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:40:23', is_late='0', created_at='2026-08-30 08:40:23', updated_at='2026-09-01 12:31:54', leader_participant_id=NULL, presentation_link='https://www.canva.cn/design/DAHTuA6pTmU/yXkpeK97H8GXFTDCRjSYtw/edit', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99343/cover.jpg', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1j5AleYsqQnE6aicRPMcK8w?pwd=r9dj', github_repo_url='https://github.com/raccoonBK/yean-hackthon0830', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='standard', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99343 AND event_id=4;
UPDATE projects SET event_id='4', team_id='109', captain_application_id='5409', topics='["qingxian_self", "insta360_hervision", "ciie_smartchain", "zeroth_linku"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='鱼鱼鱼', project_name='清宝·自在空间', tagline='让设备跟着人走，让舒适不再离开工作生活和创作', demo_order='175', project_description='清宝·自在空间是一套以人体工学椅为移动据点的设备跟随方案，解决用户在沙发、床边、窗边等舒适姿势下，手机、平板或相机仍被固定在桌面、需要反复手扶和调整的问题。我们基于六轴机械臂设计椅载连接结构与可更换夹具，并结合语音、手势和姿态逻辑实现自然交互。本次现场重点完成椅载连接模块、设备夹具适配，以及语音微调与姿态跟随链路的集成验证。用户坐上椅子后即可通过语音或简单手势微调设备位置，让工作、学习、休息和创作都能在更舒适的姿势下持续进行。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 让设备跟着人走，让舒适不再离开工作生活和创作\n- GitHub 仓库: https://github.com/yerxiiiii/meiqiu\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a937464a3ed7_96dc4e8100551f84.png)', demo_link='https://b23.tv/bffzxdO', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:41:50', is_late='0', created_at='2026-08-30 08:41:50', updated_at='2026-09-01 12:31:56', leader_participant_id=NULL, presentation_link='https://my.feishu.cn/wiki/MXQewhJXGi0UtykJuWVcT9sinIM?from=from_copylink', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99344/cover.png', screenshot_urls=NULL, video_link='https://b23.tv/bffzxdO', github_repo_url='https://github.com/yerxiiiii/meiqiu', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='iteration', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url='https://github.com/HighTorque-Robotics', iteration_plan='本项目基于高擎动力 Panthera-HT 六轴机械臂进行二次开发，原机械臂本体及基础控制能力沿用现有开源/产品能力。创作期内新增内容包括：1）适配人体工学椅的椅载连接模块；2）手机、平板与 Insta360 的可更换末端夹具；3）语音与手势交互控制；4）面向居家场景的设备位置微调与姿态跟随逻辑。评审重点为上述新增结构、交互和场景化集成能力，不包含原机械臂本体分值。', iteration_submitted_at='2026-08-30 08:41:50', award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99344 AND event_id=4;
UPDATE projects SET event_id='4', team_id='25', captain_application_id='4690', topics=NULL, sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='多少学点吧', project_name='随缘番茄钟', tagline='计时在随机区间而不是固定值、带"准备时间"缓冲的番茄钟而已。送给我“随缘”启动困难又好奇的脑子。如果能帮到我，那也能帮到千千万万像我的“你”！', demo_order='176', project_description='番茄钟的规则有一定结构性、简洁（无需手机、功能少，占用人脑认知资源少），在此基础上增加了“准备时间”减少启动阻力、随机的工作和休息时间增加新鲜感。\n记录最近成功启动都维持了多久，有成就感、满足好奇心；没有取消成本、只保留最近5条成功启动记录，不被过去束缚。\n准备启动：5分钟；然后进入工作-休息循环。工作时间：25-40分钟；休息时间：3-10分钟。\n\n目标人群：首先要能帮到我。神经多样性？执行功能障碍？或者只是无数个想要“变高效”“学会努力”的人之一。\n我用过各种各样的工作法，似乎永远在“喜新厌旧”，但这何尝不是人生探索与证明的过程呢！由此我知道了工具的局限：真正的改变，发生在我自己活出的每一个瞬间，每一个微小的选择和无数内化的思想才能引起质变。\n开发的最后一天，我用它看杨福家原子物理。我的项目和我心之所向合二为一了，因黑客松中断几天的物理学习之旅再次启程，其实这才是我的“项目”，哪怕这个番茄钟邪修学习法之后被我弃用（也许很久以后又拾起），我的人生大“项目”从未中断...\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 计时在随机区间而不是固定值、带"准备时间"缓冲的番茄钟而已。送给我“随缘”启动困难又好奇的脑子。如果能帮到我，那也能帮到千千万万像我的“你”！\n- GitHub 仓库: https://github.com/yyaoshimaenaga/pomodo-what\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a934b6177356_88deb54769a2bf9b.png)\n  - ![BOM 图](/platform/uploads/images/2026/08/6a934b73d5eb9_7d55c661a67f2387.png)\n  - ![BOM 图](/platform/uploads/images/2026/08/6a934b793a92e_3e2b0262b5bf288e.png)', demo_link='https://www.bilibili.com/video/BV1WD4U62EtZ/?share_source=copy_web&vd_source=f740ec97458a9cea06fd377489c3e5a0', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:42:09', is_late='0', created_at='2026-08-30 08:42:09', updated_at='2026-09-01 12:31:59', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99345/cover.jpg', screenshot_urls=NULL, video_link='https://www.bilibili.com/video/BV1WD4U62EtZ/?share_source=copy_web&vd_source=f740ec97458a9cea06fd377489c3e5a0', github_repo_url='https://github.com/yyaoshimaenaga/pomodo-what', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99345 AND event_id=4;
UPDATE projects SET event_id='4', team_id='222', captain_application_id='4937', topics='["sappho_love", "miaoda_super", "liberlive_goodday", "eazo_4her", "zeroth_linku", "insta360_hervision", "tripo_hergaze"]', sponsor_consents='{"tripo_hergaze": {"rights": "非独占、全球范围、免费", "topic_code": "tripo_hergaze", "sponsor_key": "tripo", "topic_title": "为她而设计 — Her Gaze, Her Game", "consented_at": "2026-08-28T20:24:39+08:00", "consented_ip": "223.104.40.109", "sponsor_label": "Tripo 3D", "sponsor_full_name": "Tripo 3D (Vietnam)", "consented_user_agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0"}}', application_id=NULL, session=NULL, cohort=NULL, team_name='老公你说句话啊队', project_name='她所向之处|Where She Longs', tagline='选择她所爱之物，奔向她所向之处。 Choose What She Loves and Go Where She Longs.', demo_order='177', project_description='一、项目背景\n《她所向之处》| Where She Longs诞生于「She Nicest 千人烈变黑客松·大都｜科技创造节」游戏赛道，96小时极限开发。\n作品名取自古希腊诗人萨福残诗Fragment16：“she could not remember anything but longing.”（“她什么也无法记起，除了心中的渴望。”）萨福是有记载的西方文学史上第一位以第一人称书写爱与渴望的女性声音——两千多年前她写下的“我渴望，我欲求”，正是婚礼前夜的小凌第一次试图辨认的东西。\n我们想做一个关于“选择”的游戏。故事设定在一个被所有人定义的“好日子”前夜：黄道吉日、婚礼流程、宾客名单，所有人都告诉29岁的小凌“明天是好日子”，可她问“如果明天不结呢”。游戏不评判走进婚礼、取消婚礼、暂缓婚礼任何一个结局的好坏——因为无论怎么选，那一天都应该是她自己选的日子。自由不是不结婚，而是选择自己所向之处。\n七个企业命题在我们的作品里是同一件事的七个侧面：萨福的“渴望本能”、秒哒的“超级个体”、LiberLive 的谁定义“好日子”、eazo 的为说不自己的选择的女孩而做、Zeroth 的“桥接内心世界”、影石的“视界始于她想”、Tripo 的“女性凝视”——都指向同一个内核：先看见自己，再选择所向之处。\n二、 目标用户\n• 核心用户：身处“奥德赛时期”的年轻人——二十多岁到三十出头，工作没定型、感情没定型、人生方向模糊，被社会期待催着往前走的人。\n• 特别为她们而做：在生活中做不出自己的选择的女孩——选择三十岁之前结婚，选择一份稳定的工作，选择一个人人觉得“合适”的对象，选择固定利率的房贷、体面的婚礼、完美的婚纱照。选择养生、低卡饮食、定期体检，选择在饭局上被问“你什么时候结婚”时微笑，选择在会议上咽下异议，选择在自己的野心面前，假装没那么想要。选择在朋友圈发"做自己"，然后删掉。选择不在公共场合哭，选择不在公共场合生气，选择不在公共场合做任何“太激烈”的事，选择在喜欢的人面前装作不太喜欢，选择在被伤害之后说“我没事”，选择和妈妈冷战，选择在心里说"我不想变成你"，同时又怕自己正在变成你，选择做一个好女儿，选择做一个好女友，选择做一个"好相处的人"，选择做一个从不让别人为难的人……这一次，她要选择她所向之处。\n• 场景延伸：对叙事向独立游戏、女性题材内容、情绪价值体验感兴趣的泛玩家群体；黑客松/游戏展现场的过路体验者（单局体验时长设计为15-20分钟，适配展会场景）。\n三、 技术栈与 AI 使用说明\n开发方式：全员 VibeCoding，7 人 × AI 编程 Agent 并行开发。\n• 编程：团队 7 人每人在本机安装 AI 编程 Agent，按统一《任务单》模板领取任务、并行开发、逐条对照验收标准回传成果。写文案的成员做场景配置，做交互的成员调跑酷小游戏，美术产出可接入资产——一个人加上 AI 就是一条产线。技术统筹负责任务单拆分、模块接口约定与合并验收，主程序兜底核心交互。\n• 美术：场景与角色资产大量借助 AI 图像生成工具快速产出，由美术岗主导风格判断、构图筛选与关键场景人工二次调整；最终审美决策由人完成。\n• 剧本：100%人工原创编排。游戏内角色对话全部为人工剧本。\n• 游戏技术栈：godot。\n核心交互模块包括：第一/第三人称视角切换、闭眼状态的音频分层与输入交互、跑酷/跳石头小游戏、对话选择分支、多结局流程管理。\n• AI 使用合规：赛前由技术统筹核实各工具商用授权条款；AI 仅用于开发环节（编程辅助 + 美术资产生成），不用于游戏内实时内容生成。\n四、创新点\n1. 视角语言即叙事语言：第一人称下主角始终看不见自己；主动闭眼、再睁眼切换为第三人称，她才第一次“看见自己”——一个模糊的、不完整的自己。视角变化与自我认知完全同构，“看见自己”不是台词讲出来的，是玩家亲手切视角时意识到的。\n2. “闭眼”作为统一身体交互：闭眼是进入内心世界的开关——外部声音一层层消失，只剩呼吸与心跳，玩家由此进入草原、黑暗森林、神秘黑湖。玩法机制刻意调动身体感官：走入黑暗森林时眼前一片漆黑，玩家必须“闭上”眼睛，才能感知自己的身心所向。\n3. 流动的欲望化身“阿麦”：阿麦是主角内心欲望的投射，性别模糊、外型流动、不被定义——主角看不清自己时阿麦是模糊的，随冒险深入他的形象不断流动变化，逐渐长出长发、穿上裙子，最终在黑湖倒影中与主角轮廓重合。\n4. 跨代际的女性互相照见：湖对面救起主角的神秘女孩，通过无名指银戒指、掌纹皱纹、一道小疤痕三个交互点位，让玩家自己认出她是年轻时的母亲。她不提供答案、不做人生导师，只是说“我也这样”——两代女性的彼此照见本身就是力量。\n5. 不评判的三结局：走进婚礼、取消婚礼、暂缓婚礼都没有好坏判定。游戏不替玩家选择，只让选择是她自己做出的。\n6. 技术团队的“超级个体”协作范式：7人小队在96小时内全员使用AI编程工具并行开发，文案、交互、美术岗都直接产出可运行内容——本作品的开发过程本身就是“AI 唤醒本能”的一次实践，与作品主题互为印证。\n五、 团队分工（老公你说句话啊队·7人）\n角色\t成员\t职责\n总策划\t坚果\t作品开发总控、玩法机制与体验节奏把关、项目技术统筹与进度把控\n文案\t然比\t剧本撰写、游戏内文案与叙事设计\nPM/路演传播\t枫林\t项目管理、路演主讲、市场营销与传播、摆摊布展与物料制作\n技术统筹\t小芷\t任务单拆分、AI编程协作流程、模块合并验收、授权合规\n交互设计\tKathy\t闭眼交互、视角切换、对话分支等核心体验设计与实现\n美术\t不夜\tAI美术资产生成、风格定调、人工筛选与精修\n程序\t马桶哥\t主程序兜底、核心玩法实现、Demo演示操作\n\n六、 开发过程（96小时）\n• Day 1（8/26）：命题解读与方向锁定——从萨福残诗“longing”出发确立婚礼前夜的内心冒险核心设定；完成故事大纲、四章流程与七命题呼应映射；搭建全员 VibeCoding 协作流程（任务单模板 + 验收标准 + 模块边界）。\n• Day 2（8/27）：剧本V3定稿与垂直切片——四章剧本（新婚彩排/结婚前夜/奇妙夜 /典礼上的选择）锁定；第一/第三人称视角切换、闭眼音频分层交互跑通；美术风格定调，草原与森林场景资产批量产出。\n• Day 3（8/28）：内容填充与联调——黑暗森林闭眼段、黑湖跳石头、湖边母女对谈、三结局分支全部接入；摆摊物料（宣传册、易拉宝、土味请柬、宣传单）同步产出；200人试玩微信群建立。\n• Day 4（8/29）：测试打包与路演准备——完成新婚彩排与结婚前夜、典礼上的选择部分、Demo测试打包、物料打印制作、摆摊道具准备、8分钟路演逐字稿与Q&A预案定稿；全员合练。\n• Day 5（8/30）：09:00作品提交，摆摊初审+终审路演。\n七、后续计划\n1. 短期（赛后1个月）：根据现场试玩反馈打磨完整版——补全支线对话、优化闭眼段音频体验、增加结局后“她的所向之处”尾声段落；上线Web试玩版与itch.io页面。\n2. 中期（3-6个月）：参加 indiePlay、NAVID 等叙事向独立游戏展映；推出移动端版本；基于“奇妙夜”世界观开发DLC章节。\n3. 长期：做成一个系列——每个故事，都是一个女孩第一次听见自己的声音。《她所向之处》是第一部：婚礼前夜。后续故事可以发生在辞职前夜、分手前夜、三十岁前夜……同一个内心世界，不同的“好日子”。\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 选择她所爱之物，奔向她所向之处。 Choose What She Loves and Go Where She Longs.\n- GitHub 仓库: https://github.com/DiesesKontofuerVerbindung/WhereSheLongs\n- 游戏玩法说明:\n  游戏类型\n  叙事驱动的互动剧情游戏（Narrative Adventure）。以第一人称/第三人称视角切换为核心视觉语言，融合环境探索、对话选择、轻量动作小游戏与主观交互。\n  预计游戏时长： 主线流程约20分钟。\n  故事流程与玩法\n  第一章 · 新婚彩排（现实世界 · 第一人称）\n  玩家以盖着头纱的第一人称视角站在婚礼彩排现场。\n  • Checklist互动：点击场景各处，逐项完成婚礼清单（确认站位/音乐/来宾名单/菜单/誓词/婚戒/时间），每完成一项打一个勾。\n  • 关系叙事：未婚夫思雨迟到、把誓词推到"明天现场来"、中途因工作离场。玩家在点击与对话中，亲手把一场"完美婚礼"的流程确认完毕——也亲手确认了自己的格格不入。\n  • 车内对话中，玩家可以说出那句“如果明天不结呢？”\n  第二章 · 结婚前夜（现实世界 · 第一人称）\n  • 物品探索：点击房间中的物品阅读记忆文本——游戏机（“后来大部分时间都是他一个人在玩”）、从未拆封的攀岩鞋、看电影时他睡着的电影票。每件物品都是一段关系的旁证。\n  • 世界震动：母亲的催促（“你马上三十岁了”“这个年纪的人不能总是什么都不知道”）让世界三次震动、声音失真、声场收窄——玩家在主观听觉的崩塌中坠入梦境。\n  第三章 · 奇妙夜（内心世界 · 视角切换的核心章节）\n  ① 草原 · 相遇（自由探索）\n  • 小凌在发光草原醒来，遇见一个不知姓名的短发女孩。\n  • 环境互动：追发光小动物、看草坡顶端游过云层的发光巨鲸、女孩送她一朵靠近就闭合的花。\n  • 这一段没有任务、没有清单、没有正确路线——是全游戏唯一"没人催她去哪"的空间。\n  ② 黑暗森林 · 闭眼进入（交互语义：闭眼 = 倾听内心）\n  • 森林入口，女孩劝她别去。玩家选择进入后，主动闭眼：外部声音一层层消失，只剩呼吸、心跳和很远的虫鸣。\n  • 睁眼瞬间，视角从第一人称切换为2D横版第三人称——玩家第一次“看见自己”。此刻小凌的形象边缘发虚、色彩只有三四成、像没画完，象征她尚未看清自己。\n  ③ 森林冒险 · 阿麦（第三人称 · 轻动作）\n  • 心脏发光的神秘男孩阿麦在黑暗中带路，萤火虫排成光轨指路。\n  • 森林跑酷小游戏（神庙逃亡式）：跳跃/滑铲躲避藤蔓障碍；跑到中段出现多条路线，阿麦会模仿玩家的选择——玩家跳，他也跳。\n  • 核心视觉机制：随着冒险推进，小凌的形象越来越清晰完整，阿麦却越来越模糊，轮廓越来越像小凌。\n  ④ 神秘湖 · 跳石头（回到第一人称）\n  • 视角切回第一人称，玩家亲自踩上过湖的石头。\n  • 湖面具有反光：玩家寻找落脚点时，同时看见自己的影子和阿麦的影子——两个影子从姿态相似逐渐变得无法区分。阿麦不是别人，是小凌自身欲望与冒险冲动的人格化投射。\n  • 小凌沉入水中：声音闷下去、心跳变慢、寂静。\n  ⑤ 湖边 · 对谈（剧情对话 + 主观交互）\n  • 短发女孩救起小凌。两个处在不同人生阶段、却拥有相同困惑的女人彻夜长谈。\n  • 女孩不追问、不评判，只说"因为我也这样"。玩家在对话选项中替小凌做出回应——那些现实里没说出口的话，在湖边第一次说出来。\n  • 主观交互一·玻璃罐：闭眼进入主观世界，玩家试图把星星点点的“选择”放进玻璃罐，却怎么也放不进去——具象化“不知道自己要什么”。\n  • 主观交互二·生活音墙：做饭点火、打字、洗漱、孩子哭喊、汽笛……各种生活音效从各自分开到逐渐交织、越来越密，玩家用一个手势全部静音——只剩自己的呼吸。\n  • 手部细节交互：小凌抓起女孩的手，查看三个细节点位：无名指的银戒指、掌纹皱纹、一道小疤痕——她是年轻时的母亲。两个女性在跨代际的凝视中真正照见彼此。\n  • 世界再次震动，两只手松开的瞬间，梦结束。\n  第四章 · 典礼上的选择（现实 · 第一人称）\n  • 婚礼当天，小凌在走廊叫住思雨，说出全部的“不知道”。\n  • 最终三选一结局：\n  ◦ A. 走进婚礼：她与思雨立下新的约定（“以后我想做别的事，你不要告诉我这是不成熟”），自己掀开头纱走向红毯——是她主动选择进入关系。\n  ◦ B. 取消婚礼：她脱下高跟鞋，赤脚跑出酒店，跑进阳光里。\n  ◦ C. 暂缓婚礼：“不知道，也可以是一个答案。”婚礼与她的个人主题音乐短暂共存，悬而未决。\n  • 三个结局不做好/坏/真结局判定：三种选择都通向她所向之处。\n  核心设计亮点\n  1. “看与被看”的视角语言：看不见自己（第一人称）→ 闭眼倾听 → 看见自己（第三人称）→ 在倒影中认出欲望就是自己。视角变化即自我认知的变化，玩法与主题完全同构。\n  2. “闭眼”统一交互语义：闭眼是进入内心世界的开关，贯穿森林入口、玻璃罐、生活音墙等所有主观段落。\n  3. 阿麦的视觉渐变：欲望化身随主角自我清晰而模糊、最终与主角重合——他是女孩内心欲望的投射。\n  4. 对话即共感：神秘女孩不提供答案、不做人生导师，只反复说出“我也这样”——两个女人的彼此照见本身就是力量；对话选择推进叙事，玩家替小凌说出心声。\n  5. 母女跨代际凝视：神秘女孩的真实身份是年轻时的母亲，两个女性在湖边完成的是代际之间的互相照见。\n  6. 无标准答案的结局：游戏不替玩家选择，只让玩家逐步看清楚自己心之所向，做出真正属于自己的选择。', demo_link='https://www.youtube.com/watch?v=zx9uIjGRRfY', xiaohongshu_link='我在She Nicest黑客松结婚了！但是婚礼前夜我的“老公... https://xhslink.cn/o/3evApXGqGkc 带走口令，来【小红书】发现精彩~', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:42:34', is_late='0', created_at='2026-08-30 08:42:34', updated_at='2026-09-01 12:32:01', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99346/cover.jpg', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937c03197de_c90132c33efd4e73.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937c0a1d38a_e396ee84b999aeb8.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937c4d448ff_f6408ac2fd1043e2.png"]', video_link='https://www.youtube.com/watch?v=zx9uIjGRRfY', github_repo_url='https://github.com/DiesesKontofuerVerbindung/WhereSheLongs', bom_link_text=NULL, gameplay_description='游戏类型\n叙事驱动的互动剧情游戏（Narrative Adventure）。以第一人称/第三人称视角切换为核心视觉语言，融合环境探索、对话选择、轻量动作小游戏与主观交互。\n预计游戏时长： 主线流程约20分钟。\n故事流程与玩法\n第一章 · 新婚彩排（现实世界 · 第一人称）\n玩家以盖着头纱的第一人称视角站在婚礼彩排现场。\n• Checklist互动：点击场景各处，逐项完成婚礼清单（确认站位/音乐/来宾名单/菜单/誓词/婚戒/时间），每完成一项打一个勾。\n• 关系叙事：未婚夫思雨迟到、把誓词推到"明天现场来"、中途因工作离场。玩家在点击与对话中，亲手把一场"完美婚礼"的流程确认完毕——也亲手确认了自己的格格不入。\n• 车内对话中，玩家可以说出那句“如果明天不结呢？”\n第二章 · 结婚前夜（现实世界 · 第一人称）\n• 物品探索：点击房间中的物品阅读记忆文本——游戏机（“后来大部分时间都是他一个人在玩”）、从未拆封的攀岩鞋、看电影时他睡着的电影票。每件物品都是一段关系的旁证。\n• 世界震动：母亲的催促（“你马上三十岁了”“这个年纪的人不能总是什么都不知道”）让世界三次震动、声音失真、声场收窄——玩家在主观听觉的崩塌中坠入梦境。\n第三章 · 奇妙夜（内心世界 · 视角切换的核心章节）\n① 草原 · 相遇（自由探索）\n• 小凌在发光草原醒来，遇见一个不知姓名的短发女孩。\n• 环境互动：追发光小动物、看草坡顶端游过云层的发光巨鲸、女孩送她一朵靠近就闭合的花。\n• 这一段没有任务、没有清单、没有正确路线——是全游戏唯一"没人催她去哪"的空间。\n② 黑暗森林 · 闭眼进入（交互语义：闭眼 = 倾听内心）\n• 森林入口，女孩劝她别去。玩家选择进入后，主动闭眼：外部声音一层层消失，只剩呼吸、心跳和很远的虫鸣。\n• 睁眼瞬间，视角从第一人称切换为2D横版第三人称——玩家第一次“看见自己”。此刻小凌的形象边缘发虚、色彩只有三四成、像没画完，象征她尚未看清自己。\n③ 森林冒险 · 阿麦（第三人称 · 轻动作）\n• 心脏发光的神秘男孩阿麦在黑暗中带路，萤火虫排成光轨指路。\n• 森林跑酷小游戏（神庙逃亡式）：跳跃/滑铲躲避藤蔓障碍；跑到中段出现多条路线，阿麦会模仿玩家的选择——玩家跳，他也跳。\n• 核心视觉机制：随着冒险推进，小凌的形象越来越清晰完整，阿麦却越来越模糊，轮廓越来越像小凌。\n④ 神秘湖 · 跳石头（回到第一人称）\n• 视角切回第一人称，玩家亲自踩上过湖的石头。\n• 湖面具有反光：玩家寻找落脚点时，同时看见自己的影子和阿麦的影子——两个影子从姿态相似逐渐变得无法区分。阿麦不是别人，是小凌自身欲望与冒险冲动的人格化投射。\n• 小凌沉入水中：声音闷下去、心跳变慢、寂静。\n⑤ 湖边 · 对谈（剧情对话 + 主观交互）\n• 短发女孩救起小凌。两个处在不同人生阶段、却拥有相同困惑的女人彻夜长谈。\n• 女孩不追问、不评判，只说"因为我也这样"。玩家在对话选项中替小凌做出回应——那些现实里没说出口的话，在湖边第一次说出来。\n• 主观交互一·玻璃罐：闭眼进入主观世界，玩家试图把星星点点的“选择”放进玻璃罐，却怎么也放不进去——具象化“不知道自己要什么”。\n• 主观交互二·生活音墙：做饭点火、打字、洗漱、孩子哭喊、汽笛……各种生活音效从各自分开到逐渐交织、越来越密，玩家用一个手势全部静音——只剩自己的呼吸。\n• 手部细节交互：小凌抓起女孩的手，查看三个细节点位：无名指的银戒指、掌纹皱纹、一道小疤痕——她是年轻时的母亲。两个女性在跨代际的凝视中真正照见彼此。\n• 世界再次震动，两只手松开的瞬间，梦结束。\n第四章 · 典礼上的选择（现实 · 第一人称）\n• 婚礼当天，小凌在走廊叫住思雨，说出全部的“不知道”。\n• 最终三选一结局：\n◦ A. 走进婚礼：她与思雨立下新的约定（“以后我想做别的事，你不要告诉我这是不成熟”），自己掀开头纱走向红毯——是她主动选择进入关系。\n◦ B. 取消婚礼：她脱下高跟鞋，赤脚跑出酒店，跑进阳光里。\n◦ C. 暂缓婚礼：“不知道，也可以是一个答案。”婚礼与她的个人主题音乐短暂共存，悬而未决。\n• 三个结局不做好/坏/真结局判定：三种选择都通向她所向之处。\n核心设计亮点\n1. “看与被看”的视角语言：看不见自己（第一人称）→ 闭眼倾听 → 看见自己（第三人称）→ 在倒影中认出欲望就是自己。视角变化即自我认知的变化，玩法与主题完全同构。\n2. “闭眼”统一交互语义：闭眼是进入内心世界的开关，贯穿森林入口、玻璃罐、生活音墙等所有主观段落。\n3. 阿麦的视觉渐变：欲望化身随主角自我清晰而模糊、最终与主角重合——他是女孩内心欲望的投射。\n4. 对话即共感：神秘女孩不提供答案、不做人生导师，只反复说出“我也这样”——两个女人的彼此照见本身就是力量；对话选择推进叙事，玩家替小凌说出心声。\n5. 母女跨代际凝视：神秘女孩的真实身份是年轻时的母亲，两个女性在湖边完成的是代际之间的互相照见。\n6. 无标准答案的结局：游戏不替玩家选择，只让玩家逐步看清楚自己心之所向，做出真正属于自己的选择。', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99346 AND event_id=4;
UPDATE projects SET event_id='4', team_id='18', captain_application_id='5070', topics='["insta360_hervision"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='Airshot', project_name='全景感知AI搜救机器狗「小安」', tagline='全景感知AI搜救狗「小安」——灾难现场「小安」先进入 先发现 先判断', demo_order='178', project_description='项目名称：Airshot Rescue｜360°智能搜救机器狗\n一句话简述：搭载360°全景相机与多模态AI的搜救机器狗，深入危险区域主动发现受困人员，回传定位、人员状态、环境风险和救援建议。\n项目名称：Airshot Rescue｜360°智能搜救机器狗\n\n一、解决的问题\n\n地震、坍塌现场存在三类困难：\n\n- 救援人员无法安全、快速进入高风险区域；\n- 普通摄像头存在视野盲区，受困人员容易被遮挡；\n- 现场视频信息零散，指挥人员难以及时判断“谁最危险、先救谁、如何救”。\n\n二、解决方案\n\n我们将以下设备组合成一套智能搜救系统：\n\n- VBot 机器狗：进入人员难以抵达的废墟区域；\n- Insta360 X4：采集并回传360°现场画面；\n- RDK：处理视频、音频及设备控制任务；\n- 多模态 AI：持续理解现场信息，主动发现受困人员；\n- 救援指挥界面：将分析结果转化为明确的行动建议。\n\n系统可以输出：\n\n- 受困人员的位置与明显外貌特征；\n- 意识回应、活动能力、受压情况等可观察状态；\n- 松动构件、道路遮挡、积水等环境风险；\n- 人员救援优先级；\n- 救援组与机器狗的下一步任务；\n- 可向意识清醒人员提供的应急补给建议。\n\n系统不替代专业医疗检测，只分析视频和音频中能够观察到的生命迹象。\n\n三、黑客松现场完成内容\n\n- 完成机器狗、全景相机与计算设备的硬件组合；\n- 接入实时360°视频及现场音频；\n- 完成多模态 AI 对连续信息流的理解与结构化输出；\n- 建立受困人员识别、环境风险判断和优先级排序规则；\n- 完成救援组任务与机器狗侦察任务的并行决策逻辑；\n- 完成救援指挥中心用户界面；\n- 跑通“进入现场 → 发现人员 → 分析风险 → 回传定位 → 生成建议”的演示闭环。\n\n四、使用方式\n\n1. 将搭载 X4 和 RDK 的机器狗投放至灾害区域；\n2. 机器狗移动侦察，并持续回传360°视频和音频；\n3. AI 主动识别疑似受困人员及现场风险；\n4. 系统建立人员档案，输出位置、状态、风险和救援优先级；\n5. 指挥人员确认建议，并向救援组和机器狗分别下发任务；\n6. 机器狗继续绕行补充视角，或向受困人员运送应急补给。\n\n核心价值\n\n让机器狗先进入危险现场，让救援人员在行动前获得完整、结构化、可执行的现场信息。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 全景感知AI搜救狗「小安」——灾难现场「小安」先进入 先发现 先判断\n- GitHub 仓库: https://github.com/1ivy403/rescue-xiaoan\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a937b0cd10d7_74050d30c517af45.png)', demo_link='https://1ivy403.github.io/rescue-xiaoan/showcase/videos/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:43:12', is_late='0', created_at='2026-08-30 08:43:12', updated_at='2026-09-01 12:32:05', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99347/cover.png', screenshot_urls=NULL, video_link='https://1ivy403.github.io/rescue-xiaoan/showcase/videos/', github_repo_url='https://github.com/1ivy403/rescue-xiaoan', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='iteration', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url='https://github.com/D-Robotics', iteration_plan='新增：①全景视觉主控程序（C++）：打通 X4 发现、USB 取流、双鱼眼拼接、全景图与人物第三视角双输出及事件抓拍；支持 PC→RDK 低清 JPEG 推流、检测事件回传和 X4 音频转发。②RDK 人员感知节点：基于 YOLOv8n-Pose 在 BPU 端侧推理，输出人员框、方位及 person_enter 等结构化事件。③搜救指挥台 Web 前端：提供 360°虚拟机位、目标队列与距离方位、AI 决策确认、呼救检测、环境风险、战术地图和证据关键帧；支持 MOCK/WebSocket 数据源切换、断线重连与降级。\n\n改造：将官方示例改为事件驱动出图。接收 RDK 的 person_enter 与 bbox 后，以人物为视心，按人物高度自适应视场角（34°–110°）重投影；感知中断 1 秒内回退全景抽帧，避免链路卡死。\n\n验证：连续实测 21.5 分钟，完成 30fps 拼接 3.7 万帧、向 RDK 推流 1.28 万帧、回传 809 个事件、产出 236 张成片；RDK 端 BPU 单帧推理 73ms，稳定检出 1–4 人，留存 97 张证据帧。', iteration_submitted_at='2026-08-30 08:43:12', award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99347 AND event_id=4;
UPDATE projects SET event_id='4', team_id='35', captain_application_id='4731', topics='["qingxian_self", "insta360_hervision", "zhiyuan_herrobot"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='腱鞘炎拯救者队', project_name='SHEWRIST腕安', tagline='懂她的忙碌，也懂她的手腕', demo_order='179', project_description='SHEWRIST腕安是一款面向办公女性人群的智能腕部健康管理设备，通过实时监测手腕姿态与使用负荷，结合智能预警、渐进式震动及软件弹窗，及时提醒用户调整姿势与节奏；同时生成每日数据报告、改善建议和放松教程，让腕部健康管理融入工作日常。\nhttps://ecnxvrghku4q.feishu.cn/docx/FDW2dhHi1oinazxmXhTcOJPYn7d?from=from_copylink\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 懂她的忙碌，也懂她的手腕\n- GitHub 仓库: https://github.com/Debra2559/gentle-wrist-care\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a9374be2aee4_0d7f87c2e98f431a.png)\n  - ![BOM 图](/platform/uploads/images/2026/08/6a937c8dc593d_85651f87659828bb.png)', demo_link='https://gentle-wrist-care.lovable.app', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:43:21', is_late='0', created_at='2026-08-30 08:43:21', updated_at='2026-08-30 09:10:48', leader_participant_id=NULL, presentation_link='https://ecnxvrghku4q.feishu.cn/slides/MZoRsTFKSlj8Utd0dXrco2condc?from=from_copylink', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://ecnxvrghku4q.feishu.cn/file/XIDDb1CenoxQUnxyUNgcW5CDnKf?from=from_copylink', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9328900435d_676efa9837be8b61.jpg","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93289861ae6_297471fbf0c72df7.jpg","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93289e83b4b_5e956a60c7240bce.jpg"]', video_link='https://www.bilibili.com/video/BV1Rm4S6qE97/?spm_id_from=333.1387.homepage.video_card.click', github_repo_url='https://github.com/Debra2559/gentle-wrist-care', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile=