UPDATE projects SET event_id='4', team_id='121', captain_application_id='5034', topics='["ciie_smartchain", "beichen_cloudcomm", "eazo_4her", "liberlive_goodday", "proya_feelings", "qingxian_self", "bluebox_sleep", "zhiyuan_herrobot", "zeroth_linku", "insta360_hervision", "ant_mulan_ai", "loomq_transition", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='润信千方', project_name='Expo Service AI（辰程 AI）', tagline='让每一次相遇，准时发生。', demo_order='201', project_description='展会中，观众经常在有限时间内迷路和错过感兴趣内容，展商难以提前判断真实需求，运营方只能在拥堵或异常发生后被动处理。Expo Service AI（辰程 AI）构建观众、展商、场馆运营三端协同服务：观众端通过兴趣与时间问答生成个性化展位清单，并提供展位库、地图、AI 助手和人流信息；展商端管理展位、预约和在途观众；运营端统一查看活动、地图、预约、分析与实时状态。现场完成了可直接访问的移动端 MVP、三端门户、预约与数据分析闭环、SQLite 持久化、账号与通行密钥登录、Docker/Cloudflare 自托管部署，并为场馆地图设置权威数据、现场复核和双人审核边界。使用方式：打开在线演示，观众可立即完成问答并查看推荐；工作人员从门户切换到对应工作台。下一步将接入经确认的场馆数据，在隐私授权后完善动态路线、邀约与会后转化跟进。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 让每一次相遇，准时发生。\n- GitHub 仓库: https://github.com/eistinlandfrank/chencheng-ai-expo', demo_link='https://chencheng-expo.pages.dev', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:53:56', is_late='0', created_at='2026-08-30 08:53:56', updated_at='2026-09-01 12:32:54', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99370/cover.png', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/5Um_NO0-J-7BfsZmC1gEUew', github_repo_url='https://github.com/eistinlandfrank/chencheng-ai-expo', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, ite