UPDATE projects SET event_id='4', team_id='80', captain_application_id='3205', topics='["ant_mulan_ai", "frostsullivan_proof", "liberlive_goodday", "proya_feelings", "miaoda_super"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='5HERz', project_name='试途——WAYVE', tagline='仕途之前，先“试途” ——让你的职业选择有迹可循', demo_order='204', project_description='“试途（Wayve）”是一款面向在校学生、应届毕业生、求职者及转行人群的 AI 职业方向探索平台。项目聚焦一个常见问题：许多人希望进入 AI 行业，但对不同岗位的实际工作内容、所需能力及自身匹配度缺乏直观认识，传统的问卷测评往往只能给出抽象结论，难以帮助用户形成具体行动方向。\n因此，本项目以“先试途，再择途”为核心理念，将职业探索从“看岗位介绍、做兴趣测试”转变为“完成真实工作情境中的微任务”。用户不需要一开始就决定职业目标，而是可以通过体验不同岗位的任务内容，逐步了解自己更擅长什么、更愿意投入什么，以及下一步应补足哪些能力。\n平台首先通过三步信息收集了解用户情况，包括当前状态、专业或工作背景、过往经历、已掌握的技能工具、感兴趣的工作内容、工作偏好及当前职业困惑。系统据此生成岗位推荐，帮助用户优先体验更符合自身背景和兴趣的职业方向；同时，用户也可以跳过推荐，直接从岗位列表中自主选择体验。\n目前项目已完成以下核心功能：\n- AI 岗位探索：提供 AI 产品经理、AI UI 设计、AI 产品运营、AI 数据与评测、AI 应用开发等岗位的探索入口，展示不同方向的工作特点与能力要求。\n- 个性化岗位推荐：基于用户填写的背景、技能、经历和偏好，推荐值得优先验证的岗位方向，并说明推荐理由与相关能力标签。\n- 工作微任务体验：每个岗位设置 6 道贴近实际工作的情境题，用户需要在任务中进行判断、选择和问题拆解，从而体验岗位日常涉及的思考方式。\n- 情景模拟：围绕项目会议、客户沟通、发布现场等典型工作场景，用户可阅读任务背景、分析问题，并选择处理方案或填写自己的回答，进一步体验真实工作中的决策过程。\n- 个性化体验报告：完成任务后，系统生成岗位能力对照报告，以雷达图呈现用户在问题拆解、用户理解、证据判断、优先级决策、沟通表达等维度上的表现，并提供优势分析、待提升能力、判断依据和下一步行动建议。\n- 职业探索轨迹：平台记录用户已体验的岗位、完成状态与阶段性结果，将分散的任务体验沉淀为可回顾的职业成长路径，帮助用户比较不同方向的匹配程度。\n使用时，用户进入首页后可选择“获取职位推荐”，依次完成个人背景、相关经历和职业偏好的填写；也可以直接进入“探索”页面，自主选择感兴趣的岗位。完成岗位微任务和情景模拟后，即可查看个人职业体验报告，并在“轨迹”页面持续记录和复盘自己的探索过程。\n项目最终希望帮助用户降低进入 AI 行业的决策成本：不只告诉用户“适合什么”，更让用户通过实际体验理解“为什么适合、还缺什么、下一步可以怎么做”。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 仕途之前，先“试途” ——让你的职业选择有迹可循\n- GitHub 仓库: https://github.com/xiangRose/Wayve', demo_link='https://symptoms-harley-casual-full.trycloudflare.com/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:55:47', is_late='0', created_at='2026-08-30 08:55:47', updated_at='2026-09-01 12:33:01', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99373/cover.png', screenshot_urls=NULL, video_link='https://pan.quark.cn/s/331cac9155be', github_repo_url='https://github.com/xiangRose/Wayve', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99373 AND event_id=4;
UPDATE projects SET event_id='4', team_id='234', captain_application_id='3046', topics='["ant_mulan_ai", "frostsullivan_proof", "miaoda_super", "eazo_4her", "beichen_cloudcomm", "sensetime_xiaohuang"]', sponsor_consents='{"sensetime_xiaohuang": {"rights": "非独占、全球范围、免费", "topic_code": "sensetime_xiaohuang", "sponsor_key": "sensetime", "topic_title": "AI，不止完成一步", "consented_at": "2026-08-28T20:21:58+08:00", "consented_ip": "111.205.209.114", "sponsor_label": "商汤 (SenseTime)", "sponsor_full_name": "商汤科技 / SenseTime", "consented_user_agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/138.0.0.0 Safari/537.36 QQBrowser/21.7.7001.400"}}', application_id=NULL, session=NULL, cohort=NULL, team_name='人肉bot拯救计划', project_name='迹忆', tagline='让一线经验不再一线即逝', demo_order='205', project_description='一个真实问题：基层与公益一线工作者主要使用手机、时间碎片化、实践能力强，但不擅长或无暇撰写长文档，宝贵的本地化经验常随人员离开而消失。\n方案：「迹忆」不提炼标准答案，而是把具体情境中的判断与尝试，转化为可复用的组织记忆。\n1.捕捉“即将消失的时刻”：先留轻量标记，避免把现场人员变成文档员。\n2.提取隐性判断，而非摘要已有材料：AI 围绕情境、行动与理由、结果、好与不足、提醒与开放问题追问。\n3.从存档走向复用：经验不只被保存，也是下一次具体行动中的决策支持。\n现场完成内容：团队现场完成了需求访谈、产品定义、移动端交互设计及核心 Web MVP。\n使用方式：\n1. 现场留痕：活动中遇到值得记录的判断或问题，点击“记一下”，说一句话即可。\n2. 活动后还原：AI 针对性追问，补齐行动上下文。\n3. 沉淀经验：卡片留存，让个人的经验生长为团队记忆。\n4. 支持下一次判断：在行动前快速理解“别人当时怎么做、为什么、结果与代价是什么”。\n长期愿景：让分散在不同基层组织的一线经验，形成可迁移、可追溯的实践网络。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 让一线经验不再一线即逝\n- GitHub 仓库: https://github.com/zoe-hi/practice-memory', demo_link='https://pan.quark.cn/s/1fe2f92e840a', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:56:00', is_late='0', created_at='2026-08-30 08:56:00', updated_at='2026-09-01 12:33:08', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99374/cover.jpg', screenshot_urls=NULL, video_link='https://pan.quark.cn/s/1fe2f92e840a', github_repo_url='https://github.com/zoe-hi/practice-memory', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99374 AND event_id=4;
UPDATE projects SET event_id='4', team_id='143', captain_application_id='4869', topics='["proya_feelings", "beichen_cloudcomm", "frostsullivan_proof"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='HerSafe', project_name='HerSafe', tagline='针对女性健康产品的智能审查Agent', demo_order='206', project_description='她测是一款面向产品经理和产品设计者的女性健康数字产品风险审查工具。用户可上传代码包、产品截图、文档或网页，系统通过静态解析与多模态模型梳理页面、按钮及交互路径，并结合可追溯规则库识别隐私、健康安全、自主权、公平与无障碍等风险。审查结果以操作流程、风险待办和代码证据呈现，用户可在对话中补充事实、确认保护机制或上传材料，系统实时更新待办状态并生成风险报告，帮助团队快速发现问题并获得可执行的改进建议。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 针对女性健康产品的智能审查Agent\n- GitHub 仓库: https://github.com/mlml24048903-ctrl/SheNicest-Hackathon_Hersafe-QA', demo_link='https://nankai.feishu.cn/file/M1oTbkI45oTNJbxr3AhcXUaSnpb?from=from_copylink', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:56:35', is_late='0', created_at='2026-08-30 08:56:35', updated_at='2026-09-01 12:33:08', leader_participant_id=NULL, presentation_link='https://ycnw8glizd39.feishu.cn/wiki/OecMw3HHrirxkrkIfYDcoFHMntW?from=from_copylink', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99375/cover.png', screenshot_urls=NULL, video_link='https://b23.tv/CLC3egz', github_repo_url='https://github.com/mlml24048903-ctrl/SheNicest-Hackathon_Hersafe-QA', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99375 AND event_id=4;
UPDATE projects SET event_id='4', team_id='235', captain_application_id='4576', topics='["liberlive_goodday", "sappho_love", "eazo_4her"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='错不起，我队', project_name='ON CUE', tagline='on cue提前就位，遇事张嘴不废。slogan：帮助人们在高压焦虑环境下、面向上位者、与人争辩等环境下也可以流畅有逻辑组织语言表达自己的观点，维护自己的权益。', demo_order='207', project_description='在现实沟通中，许多人遇到矛盾、被质问、被催婚等高压场景时，常会出现生理性紧张、大脑空白、词穷甚至情绪上头，在吵架的时候突然泪失禁等等，事后又陷入“当时应该这么说”的懊悔循环。赛事期间使用不同类型的AI工具，真正从0到1创建了On Cue这个软件，该软件主要通过搭建经典对抗场景、录音复盘实景重现、搭建用户专属复盘知识库和虚拟情绪不倒翁四大模块，让用户通过低成本模拟生活中经常遇到的可能无法顺利张嘴表达个人观点的场景，以及建立用户专属的个人表达困难场景，帮助用户及时排解心中负面情绪的同时，也帮助用户提前做好心理准备，以便以后在生活中遇到类似的场景问题时能降低自己的紧张感恐惧感，可以更从容流畅地展示自己表达自己的想法。该软件操作简单，各个模块都有明显的使用说明提醒，用户一般顺利打开即可使用。\n---\nG001 软件 赛道附加材料\n\n- Slogan: on cue提前就位，遇事张嘴不废。slogan：帮助人们在高压焦虑环境下、面向上位者、与人争辩等环境下也可以流畅有逻辑组织语言表达自己的观点，维护自己的权益。\n- GitHub 仓库: https://github.com/trtr04/On_Cue.git', demo_link='https://bushinijiadegou.site/oncue/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:56:51', is_late='0', created_at='2026-08-30 08:56:51', updated_at='2026-09-01 12:33:09', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99376/cover.jpg', screenshot_urls=NULL, video_link='https://www.bilibili.com/video/BV1br4U6XE88/?share_source=copy_web&vd_source=926d5a409b7a2f8cf18705ddff0d96a3', github_repo_url='https://github.com/trtr04/On_Cue.git', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, i