UPDATE projects SET event_id='4', team_id='47', captain_application_id='4893', topics='["zhiyuan_herrobot", "insta360_hervision", "bluebox_sleep"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='人狗情未了', project_name='她的视界', tagline='让科技成为她探索世界的另一双眼睛！', demo_order='208', project_description='她的视界是一项面向视障女性的智能机器人协作项目，通过人形机器人 + 机器狗 + 全局视觉摄像头构建一个能够“看见、学习、协作、赋能”的智能伙伴系统。机器狗负责移动探索与环境感知，人形机器人负责交互、操作与任务执行，摄像头则作为“第三只眼”建立共享视觉与空间理解。项目通过动作同步挑战、引导训练、协作寻找物品、日常出行陪伴四个场景，让机器人从观察彼此、学习如何帮助人，到最终协同完成真实生活任务，逐步形成个性化的辅助能力。我们希望技术不是替视障女性做决定，而是帮助她获得更多独立探索、选择和生活的自由——让她看见更大的世界，也让世界更好地“看见她”。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 让科技成为她探索世界的另一双眼睛！\n- GitHub 仓库: https://github.com/xyznlp/bot\n- BOM / 原理图:\n  - https://github.com/xyznlp/bot/bom.txt', demo_link='https://b23.tv/lBhX1R1', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:57:10', is_late='0', created_at='2026-08-30 08:57:10', updated_at='2026-09-01 12:33:13', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99377/cover.png', screenshot_urls=NULL, video_link='https://b23.tv/lBhX1R1', github_repo_url='https://github.com/xyznlp/bot', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='standard', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99377 AND event_id=4;
UPDATE projects SET event_id='4', team_id='305', captain_application_id='2993', topics='["eazo_4her", "miaoda_super", "proya_feelings"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='知安', project_name='拆拆', tagline='允许自己，轻轻安放心绪', demo_order='209', project_description='拆拆是一款面向高敏感女性的精力管理鸿蒙原生应用。\n首页以抓娃娃作为标志性交互，每一次抓取必定成功。用户抓取获得心绪小工具，无失败挫败感，用轻松、仪式化的方式开启一次短暂的自我关照。\n产品分为两大核心专区：充电专区与省电专题。\n充电专区内置AI陪伴对话、长时放松内容，帮助用户舒缓思绪、补充心理能量，减少无谓内耗。\n省电专题提供白噪音、专注倒计时、曼陀罗绘画等轻量工具，帮助用户屏蔽外界过载刺激，安定心神，实现感官减负。\n整体产品拒绝冗长的情绪填报、不强制用户复盘，一切记录均为可选操作。以轻量化、低负担的形式，完成觉察‑减负‑修复的完整闭环，陪伴高敏感人群安稳安放情绪，从容管理自身精力。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 允许自己，轻轻安放心绪\n- GitHub 仓库: https://github.com/Ada-Mo/chaichai', demo_link='https://b23.tv/HPIxBvI', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:57:11', is_late='0', created_at='2026-08-30 08:57:11', updated_at='2026-09-01 12:33:14', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99378/cover.jpg', screenshot_urls=NULL, video_link='https://b23.tv/HPIxBvI', github_repo_url='https://github.com/Ada-Mo/chaichai', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99378 AND event_id=4;
UPDATE projects SET event_id='4', team_id='113', captain_application_id='4701', topics='["liberlive_goodday", "miaoda_super", "sappho_love", "eazo_4her", "frostsullivan_proof", "ant_mulan_ai"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='老奶卧底局', project_name='于声见微，听见记忆的变化。', tagline='在日常里见微，在不打扰中早一点看见。', demo_order='210', project_description='「见微」的灵感来自一位真实的老年女性——薇薇女士。她独立、要强，也有一点执拗。即使开始出现忘词、重复和记不起名字的情况，她也习惯用玩笑带过；当子女提出认知检查时，她会立刻说：“我没事，别瞎操心。”她不是不在意，而是不愿被怀疑“生病了”，更害怕失去尊严、成为家人的负担。\n\n这也是许多家庭正在经历的困境：日常生活中的忘词、停顿、重复和表达变化，可能是值得持续关注的早期信号，但子女很难判断这只是普通衰老，还是正在发生某种变化；即使产生怀疑，也不知道怎样开口，才不会让父母觉得自己正在被测试、监视或贴上疾病标签。女性尤其身处这一问题的中心——美国阿尔茨海默病协会数据显示，接近三分之二的阿尔茨海默病患者是女性，超过60%的失智症照护者也是女性，超过三分之一的照护者是患者的女儿。这不仅是老年人的认知健康问题，也是一场发生在母亲与女儿之间、经常被沉默处理的家庭照护难题。\n\n因此，我们设计了「见微」——一个面向成年子女的家庭认知健康观察工具。它不直接检测或诊断阿尔茨海默病，也不要求老人完成一场带有压力的认知测试，而是由AI结合父母的人生经历、兴趣和熟悉话题，为子女生成自然的对话引导。在获得长辈同意后，系统记录并分析对话中的词语寻找、表达连贯性、信息回忆、重复与停顿等变化，帮助家庭“发现变化、持续观察、知道下一步”。随着对话不断积累，系统可以逐步形成个人认知基线和长期变化趋势，为家庭决定是否需要进一步寻求专业评估提供参考。\n\n现场我们完成了可运行的App端、Web端和品牌介绍网站，并实现了长辈档案创建、个性化话题生成、对话录制与上传、说话人识别、语音内容分析、观察报告生成及历史趋势查看等核心流程。使用者只需创建父母档案，选择一个长辈熟悉的话题，根据AI提示完成约五分钟的自然交流并上传录音，即可查看本次对话中值得持续关注的变化；通过定期对话，系统将逐渐建立属于这位长辈自己的观察轨迹。\n\n为了让观察结果经得起专业追问，「见微」将建立“研究依据—原始对话—指标变化—解释边界”的可追溯机制。系统关注的停顿、重复、词语寻找、词汇多样性、语义连贯性和句法复杂度等指标，均来自已有语音与认知研究：一项纳入51项研究、17,340名参与者的系统综述显示，词汇多样性、句法复杂度和语义连贯性是跨研究中较稳定的预测特征，语言与声学联合分析的平均准确率高于单一模态；相关综述也发现，阿尔茨海默病患者的对话中更常出现停顿、重复、找词困难以及信息量和连贯性下降。系统综述 对话研究综述 在产品中，每一项观察结论都应能够回溯到具体录音片段、转写文本和时间戳，并说明本次变化对应的指标、与个人历史基线的差异、数据质量及所依据的研究来源，而不是只输出一个无法解释的风险分数。系统只描述“本次出现了什么”和“相较本人过去是否发生持续变化”，不把单一语言特征直接解释为阿尔茨海默病；因为不同神经认知疾病可能呈现不同的语言模式，而找词困难、记忆或表达变化也可能与抑郁、药物、感染及代谢问题等因素有关，真正的病因判断必须由专业评估完成。数字语音生物标志物研究 美国国家老龄研究所说明 同时，鉴于自然日常对话中的“对话记忆”研究仍然有限，「见微」现阶段将自身定位为长期观察和就医沟通的辅助工具，并通过后续家庭试点、专业机构合作和纵向验证，逐步检验这些指标在真实中文家庭场景中的可靠性。\n\n见微要建立的不是一个制造恐慌的“AI疾病检测器”，而是一个温和、克制、可信的家庭认知健康陪伴品牌。它不替代医生、不凭单次对话给老人贴标签，而是帮助子女在不惊扰父母日常生活、不伤害老人自尊的前提下，早一点看见那些容易被一句“年纪大了”忽略的微小变化。\n\n下一步，「见微」将先围绕家庭场景验证产品的长期使用价值，以家庭年度订阅为切入，持续优化对话生成、个人基线建立和趋势报告等功能；在此基础上，与陪伴机器人、智能音箱及其他家庭智能终端合作，通过技术授权、API 接入或联合会员，让认知观察自然融入长辈日常生活。与此同时，我们计划与医院、社区、养老机构和公益组织开展小规模试点，用于认知健康教育、潜在风险人群触达及规范转介，并根据专业反馈持续校准指标和使用流程。随着用户在知情同意下积累长期数据，我们希望建立经过匿名化、标准化处理的纵向语言与认知数据库，记录词语寻找、停顿、重复、表达连贯性等语言特征的长期变化，并与高校、医学实验室及研究机构合作，进一步研究这些特征与认知功能及相关脑区变化之间的关联，为阿尔茨海默病早期研究、数字生物标志物探索乃至脑机接口研究提供可靠的数据基础。前期我们已经参考哥伦比亚大学阿尔兹海默症临床课题组的研究数据，并与研究人员交流了语音指标、提问方式和分析流程；下一阶段将通过真实家庭试点和专业合作，把这些研究依据转化为可验证、可持续迭代的产品能力。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 在日常里见微，在不打扰中早一点看见。\n- GitHub 仓库: https://github.com/Cyrina-avan/MindTrace', demo_link='https://mindtrace.cyden.site/', xiaohongshu_link='https://www.xiaohongshu.com/discovery/item/6a930a7f000000000a00a1c3?app_platform=ios&app_version=9.44.1&share_from_user_hidden=true&xsec_source=app_share&type=normal&xsec_token=CBnSzDTKYFLVDefcLbMYL3GC4lBGxbMo4bYS30CeW5gQU=&author_share=1&xhsshare=WeixinSession&shareRedId=Nz43NEhJODs7N0g2SzwxPTdGOjg7NzxP&apptime=1788041505&share_id=d2b50b7a798042098dd3f6e27498b8d7&code=Oko71ZsBLz', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:57:22', is_late='0', created_at='2026-08-30 08:57:22', updated_at='2026-09-01 12:33:17', leader_participant_id=NULL, presentation_link='https://khsj.cn/hisfqelo3brxx00', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99379/cover.png', screenshot_urls=NULL, video_link='https://youtube.com/shorts/gO540ZXeahA?si=E7mjz64O8ZVpYvU0', github_repo_url='https://github.com/Cyrina-avan/MindTrace', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:10:48', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99379 AND event_id=4;
UPDATE projects SET event_id='4', team_id='189', captain_application_id='5419', topics='["liberlive_goodday", "miaoda_super", "proya_feelings", "zhiyuan_herrobot", "eazo_4her", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='嘿嘿可颂', project_name='上传你的照片，给你一个仪式感满满的铁盒', tagline='上传你的照片，给你一个仪式感满满的铁盒', demo_order='211', project_description='咕个铁盒——每一份爱与回忆都值得被珍藏。我们关注一个日常问题：照片越来越多，真正重要的瞬间却散落在手机相册里，整理和分享时缺少简单而有仪式感的方式。咕个铁盒是一款手机端数字纪念创作工具。用户上传照片，系统将其预处理并生成小卡、照片吧唧、纪念票根、贴纸等个性化物料；进入 DIY 工作台后，可将图片、素材和文字自由拖拽到开盖铁盒的盒盖或盒底，调整大小、旋转、层级和位置，还能点击“帮我摇一摇”，一次获得多种记忆方式，再继续手动修改。现场已完成从图片导入、物料生成、铁盒编辑、排版推荐到保存开盒图的完整手机端演示，并配有“盒柜”展示和打开不同铁盒。用户无需学习复杂设计软件，就能把友情、旅行、喜欢的人或平凡小事，做成可反复打开的数字铁盒。默认照片只在当前浏览器中处理，保存或收藏时才上传必要内容。我们希望技术不只提升效率，也让每个人成为生活的创作者，让普通日子拥有值得期待的收藏时刻。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 上传你的照片，给你一个仪式感满满的铁盒\n- GitHub 仓库: https://github.com/TheaaaaaaL/BOX', demo_link='https://pan.baidu.com/s/1guG3fiUGKwA4uS3s4Cshgw?pwd=kere', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:57:38', is_late='0', created_at='2026-08-30 08:57:38', updated_at='2026-09-01 12:33:18', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99380/cover.png', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1guG3fiUGKwA4uS3s4Cshgw?pwd=kere', github_repo_url='https://github.com/TheaaaaaaL/BOX', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99380 AND event_id=4;
UPDATE projects SET event_id='4', team_id='252', captain_application_id='5178', topics='["liberlive_goodday", "sappho_love", "miaoda_super", "proya_feelings"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='三只小猪建房子', project_name='MYROOMIE｜租客的数字家具小屋', tagline='让家具先住进未来的家，再决定买不买、带不带走。', demo_order='212', project_description='MYROOMIE 是面向租房人群的家具生命周期决策工具。 我们发现，租客真正反复面对的问题不是“如何装修一个房子”，而是家具如何在不断变化的居住空间中被购买、使用、搬运和处置：新家具放不放得下、会不会影响动线；搬家时一件家具应该带走、出售还是放弃；下一套房是否仍然适配。\n\nMYROOMIE 将真实尺寸的户型与家具转化为可交互的数字小屋。用户可以录入或导入自己的家具和想购买的商品，在 3D 房间中进行真实尺度试摆、移动和旋转，并获得碰撞、越界等空间反馈；家具同时保留“我的家具、房东家具、想购买”等生命周期状态。我们进一步构建了 Furniture Decision Agent，在规则能够直接判断时使用确定性规则，在使用价值、搬运成本、二手残值、空间适配、个人偏好等因素发生冲突时，再由 Agent 进行权衡，输出购买或搬家决策建议。\n\n本次现场 Demo 已完成真实户型 2D→3D、家具真实尺寸建模与摆放、家具信息管理、Wishlist 试摆、碰撞与越界检测、用户语言界面，以及可真实调用模型的家具决策 Agent。我们还尝试了手势控制与 Cozy 风格家具资产管线。\n\n使用方式：进入 Demo 后打开“我的小屋”查看 3D 房间；通过“我的家具”添加已有家具或想购买的家具，输入真实尺寸后放入小屋，在房间中拖动、旋转并查看空间适配结果。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 让家具先住进未来的家，再决定买不买、带不带走。\n- GitHub 仓库: https://github.com/acbtbff/home-demo-package', demo_link='https://pan.baidu.com/s/1sjLn6WccphTlOdOesup25A?pwd=aBmY', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:57:47', is_late='0', created_at='2026-08-30 08:57:47', updated_at='2026-09-01 12:33:19', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99381/cover.png', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1sjLn6WccphTlOdOesup25A?pwd=aBmY', github_repo_url='https://github.com/acbtbff/home-demo-package', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99381 AND event_id=4;
UPDATE projects SET event_id='4', team_id='315', captain_application_id='4774', topics=NULL, sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='夜空中最亮的欣', project_name='当神明拯救虐文女主，给她新的人生！', tagline='当神明拯救虐文女主，给她新的人生！', demo_order='213', project_description='爱情难道比生命还重要吗？可大多数女性从小就是看言情小说长大的，追妻虐文更是其中很大的一个板块。在这些追妻虐文中，为了得到最后追妻的爽感，往往会在前期对女主以各种方法施虐，所谓虐的越爽，最后追妻越爽，但这些无疑给女性从小植入了不正确的价值观，爱情难道真的比健康和安全和其他一切更重要吗？更何况还是畸形的爱情。所以我就想从这个流量和传播度很大的角度出发，希望可以让女性更注重自身发展，选择更良性的生活方式，其实真正的神明是我们每个人自己。选择合成经营类玩法是因为海外gossip habour通过合成经营结合复仇爽剧的流量传播方式非常成功，所以我希望我也可以结合这类玩法+反套路追妻爽文叙事可以达到这样的流量效果，从而影响更多人。\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 当神明拯救虐文女主，给她新的人生！\n- GitHub 仓库: 1\n- 游戏玩法说明:\n  开场虐文剧情\n  →女主死亡并向神明许愿\n  →玩家回应请求\n  →女主重回悲剧发生前\n  →经营合成赚钱\n  →用资金解锁作战工具\n  →进入横向分路塔防\n  →胜利则改写剧情\n  →失败则播放对应的原著虐文结局\n  →允许立即重试\n  →共三关\n  →最终女主收购男主公司并解除男主职务', demo_link='https://Users/liapril/Documents/%E5%B0%8F%E8%AF%B4%E8%8A%82%E5%A5%8F%E6%8B%86%E8%A7%A3/%E6%8B%92%E7%BB%9D%E6%88%90%E4%B8%BA%E5%A5%B3%E4%B8%BB/index.html', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:58:12', is_late='0', created_at='2026-08-30 08:58:12', updated_at='2026-09-01 12:33:27', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99382/cover.png', screenshot_urls=NULL, video_link='https://Users/liapril/Documents/%E5%B0%8F%E8%AF%B4%E8%8A%82%E5%A5%8F%E6%8B%86%E8%A7%A3/%E6%8B%92%E7%BB%9D%E6%88%90%E4%B8%BA%E5%A5%B3%E4%B8%BB/index.html', github_repo_url='1', bom_link_text=NULL, gameplay_description='开场虐文剧情\n→女主死亡并向神明许愿\n→玩家回应请求\n→女主重回悲剧发生前\n→经营合成赚钱\n→用资金解锁作战工具\n→进入横向分路塔防\n→胜利则改写剧情\n→失败则播放对应的原著虐文结局\n→允许立即重试\n→共三关\n→最终女主收购男主公司并解除男主职务', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99382 AND event_id=4;
UPDATE projects SET event_id='4', team_id='23', captain_application_id='3210', topics=NULL, sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='周周的队伍', project_name='多智能体生成自媒体长文内容', tagline=NULL, demo_order='214', project_description='通过学习的优质长文结合当下可选的热点生成长文 学习海量优质作品 生成风格卡 用户的采纳修改纳入长期记忆 可自己增加外部知识存入知识库\n---\nG001 ai 赛道附加材料', demo_link='https://github.com/sans923/viral-scribe-kit', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:58:20', is_late='0', created_at='2026-08-30 08:58:20', updated_at='2026-08-30 09:29:03', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url=NULL, screenshot_urls=NULL, video_link=NULL, github_repo_url=NULL, bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99383 AND event_id=4;
UPDATE projects SET event_id='4', team_id='171', captain_application_id='3121', topics=NULL, sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='情绪可穿戴', project_name='有点东西', tagline='每天一句话，让“我有点东西”被自己看见！Women speaking up? It‘s a thing.', demo_order='215', project_description='在技术、创业、职场等男性占比较高的场景中，许多女性明明有能力、有判断、有成果，却因为谦逊、不敢说或不会说，在关键时候吃了哑巴亏——她们习惯于把功劳归给“团队”或“运气”，在汇报时弱化自己的贡献，在争取资源时犹豫不决，在被人打断时选择沉默。\n\n市面上现有的解决方案——工作坊、演讲课、自信训练营——都有用，但门槛太高：需要专门腾出时间、需要鼓起勇气报名、需要面对一群人练习。而大多数人的真实需求，只是一个每天两分钟就能完成的小动作，让“看见自己”这件事先发生。\n\n现场完成的内容：软件（有点东西）+硬件开发（Thing Pin）\n\n使用方式：用户从每天用一两句话记录今天自己做过的、值得被记住的事情开始，语音会形成一张字条，每一条记录自动存入个人成就档案，用户可以选择将今日成就存入成就日记或漂流到社群中。Community界面会有不同居民分享的今日成就，你可以与他们互动点赞来彼此鼓励。当你情绪低落或自我怀疑的某天，你可以打开我们的app发现你竟然做了这么多这么棒的事情，你也可以选择和chatbot聊天你的困惑或心情，他们根据你过去的成就，基于事实来肯定和帮助你看到自己。同时，我们chatbot与美国百年NGO专注表达的 toastmaster俱乐部学习与合作，为女性从“敢说”到”擅长说“的过程提供提升表达能力的刻意训练途径，最终帮助女性大胆发声、有效表达！\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 每天一句话，让“我有点东西”被自己看见！Women speaking up? It‘s a thing.\n- GitHub 仓库: https://github.com/pinkess0415lin-ctrl/you-dian-dongxi\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a937d180a124_6321e9e421d8ff23.png)\n  - ![BOM 图](/platform/uploads/images/2026/08/6a937dd361f48_a86eadecc44271b3.png)', demo_link='https://b23.tv/w7khopf', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:58:27', is_late='0', created_at='2026-08-30 08:58:27', updated_at='2026-09-01 12:33:29', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99384/cover.png', screenshot_urls=NULL, video_link='https://b23.tv/w7khopf', github_repo_url='https://github.com/pinkess0415lin-ctrl/you-dian-dongxi', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99384 AND event_id=4;
UPDATE projects SET event_id='4', team_id='19', captain_application_id='5050', topics='["tripo_hergaze"]', sponsor_consents='{"tripo_hergaze": {"rights": "非独占、全球范围、免费", "topic_code": "tripo_hergaze", "sponsor_key": "tripo", "topic_title": "为她而设计 — Her Gaze, Her Game", "consented_at": "2026-08-26T18:37:42+08:00", "consented_ip": "111.198.130.210", "sponsor_label": "Tripo 3D", "sponsor_full_name": "Tripo 3D (Vietnam)", "consented_user_agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0"}}', application_id=NULL, session=NULL, cohort=NULL, team_name='完蛋！我被邪教徒包围了', project_name='完蛋！我被邪教徒包围了', tagline='戏里戏外同样恐怖 克系人系难解难分', demo_order='216', project_description='我们做的是一款仿Windows95风的文字冒险解谜游戏\n游戏引擎是我们从头做起，纯html+es6，无node_modules依赖\n我们引入了十分完善的开发人员模式，提供一个可视化的方式对我们的游戏引擎进行二次开发\n不论是avg爱好者还是oc人都可以利用这个游戏引擎书写自己的未完待续。\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 戏里戏外同样恐怖 克系人系难解难分\n- GitHub 仓库: https://github.com/gro-w/cultists\n- 游戏玩法说明:\n  一款 Windows 95 风格、纯原生 ES6、无构建步骤的数据驱动网页互动游戏。玩家白天在 HIS 中处理医院工作，非工作时间回到宿舍与 NPC 交流、调查物品、收集关键词并推进剧情，逐步查明真相。在玩家的san值、舍友的好感度和怀疑度的共同作用下触发不同结局。\n  游戏内置Chatgtp作为调查关键词的道具。提供开发人员模式，方便玩家书写自己的故事及二次开发。', demo_link='https://gro-w.github.io/cultists/?dev', xiaohongshu_link='https://xhslink.cn/o/6XOq9BXm22H', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:58:48', is_late='0', created_at='2026-08-30 08:58:48', updated_at='2026-09-01 12:33:31', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99385/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937be899a1d_fd63fa9da77f845c.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937c33cf47f_4485a94828d8ded0.png"]', video_link='https://xhslink.com/o/6wCaeI9aI2s', github_repo_url='https://github.com/gro-w/cultists', bom_link_text=NULL, gameplay_description='一款 Windows 95 风格、纯原生 ES6、无构建步骤的数据驱动网页互动游戏。玩家白天在 HIS 中处理医院工作，非工作时间回到宿舍与 NPC 交流、调查物品、收集关键词并推进剧情，逐步查明真相。在玩家的san值、舍友的好感度和怀疑度的共同作用下触发不同结局。\n游戏内置Chatgtp作为调查关键词的道具。提供开发人员模式，方便玩家书写自己的故事及二次开发。', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99385 AND event_id=4;
UPDATE projects SET event_id='4', team_id='223', captain_application_id='5447', topics='["liberlive_goodday", "insta360_hervision", "ant_mulan_ai"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='Jack的双重奏', project_name='Retake - 你的摄影大师', tagline='You take the photo . We take the shot', demo_order='217', project_description='出去玩两小时，回家修图四小时。\n\n拍的时候一路都很忙，谁有空管构图和光线。等回到家打开相册——一百多张，逆光的\n脸、抢镜的路人、歪掉的地平线。你得一张张对着手机抠，眼睛都快抠瞎了，最后能发\n出去的可能就三张。\n\nRetake 的敌人不是"照片不好看"，是"修图这件劳动"本身。而它的解法不是教你怎么\n修，是让你根本不用学——不用懂光圈，不用懂构图，不用懂修图。\n\n丢一批进来，走开。回来的时候它们已经拍好了。\n\n在这中间我们做了一件别人不做的事：先告诉你它到底坏在哪。不是"照片质量 7 分"\n这种废话，是"树荫下整体偏暗发闷，绿叶反光让三张脸都泛青灰""前置广角把最靠近\n镜头的那张脸拉宽放大"。具体到你一看就懂，一懂就再也忘不掉。很多人是在这一步\n第一次知道，自己拍的照片原来是这么坏的。\n\n然后才是重新拍好。不是滤镜，不是磨皮，是按一个专业摄影师会做的方式重新处理光\n线、色彩、背景和仪容。人还是你，衣服还是那件衣服，那一刻还是那一刻。\n\n我们给自己划了一条线：不改姿势，不改表情。一旦动了这两样，照片里的人就不再是\n你了。所以每份诊断里都留着一栏"看见了，但这一版不动"——我们看得出你姿势僵、\n表情飘，但我们不碰。宁可少改一点，也不要还给你一个陌生人。\n\n修好之后还能让它动起来：一次呼吸，一次眨眼，几缕头发轻轻飘。\n\n愿景是一句话：让"会不会拍照"这件事，不再决定一个人能不能留下好照片。\n---\nG001 软件 赛道附加材料\n\n- Slogan: You take the photo . We take the shot\n- GitHub 仓库: https://github.com/motiful/retake', demo_link='https://retake-web.vercel.app/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:58:50', is_late='0', created_at='2026-08-30 08:58:50', updated_at='2026-09-01 12:33:31', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99386/cover.png', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1dNN8_AKtMVE7-AFmbJ4cMg?pwd=tsmt', github_repo_url='https://github.com/motiful/retake', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99386 AND event_id=4;
UPDATE projects SET event_id='4', team_id='20', captain_application_id='3030', topics=NULL, sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='月亮神经丛', project_name='月痕 MoonTrace', tagline='把难以言说的感受，变成看得见的边界；让每一次看见，都成为保护自己的开始。', demo_order='218', project_description='月痕 Moon Trace 是一款面向身体、心理与关系边界的记录与支持工具。很多越界经历发生时，并没有清晰的“对错”提示，人往往先感到不舒服，却难以判断发生了什么，甚至陷入“是不是自己想多了”的自我怀疑；而当真正需要回看、求助或采取行动时，相关感受与信息又常常已经模糊、散落。\n\n月痕希望把难以言说的感受，变成看得见的边界，让每一次看见，都成为保护自己的开始。 产品以“觉察—记录—理解—行动”为核心路径：通过身体部位与心理感受记录不适，关联时间、地点、图片、录音等信息形成连续痕迹；由 AI 对记录进行模式识别、心理线索梳理与行动建议，帮助理解反复出现的边界问题；同时提供安全出口、求助资源及匿名的「月光角落」，让经验、支持与资源能够被看见。\n\n现场将完成微信小程序核心体验，包括身体边界、心理边界、痕迹时间线、录音留存、AI 分析、安全出口与月光角落等模块。使用时无需先判断一件事是否“足够严重”，只需要从当下真实的不适开始记录，月痕会将零散的感受逐渐整理成可回看、可追溯、可用于后续判断和行动的个人边界档案。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 把难以言说的感受，变成看得见的边界；让每一次看见，都成为保护自己的开始。\n- GitHub 仓库: https://github.com/tinxixii/MoonTrace', demo_link='https://xhslink.cn/m/9S6ucmJNS01', xiaohongshu_link='小红书ID：月痕 MoonTrace', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:59:07', is_late='0', created_at='2026-08-30 08:59:07', updated_at='2026-09-01 12:33:32', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99387/cover.jpg', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9364a7e8eba_2d079101d17bb150.jpg"]', video_link='https://xhslink.cn/m/9S6ucmJNS01', github_repo_url='https://github.com/tinxixii/MoonTrace', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99387 AND event_id=4;
UPDATE projects SET event_id='4', team_id='313', captain_application_id='5548', topics='["miaoda_super", "liberlive_goodday", "proya_feelings", "sensetime_xiaohuang", "qingxian_self", "zhiyuan_herrobot", "bluebox_sleep", "eazo_4her", "frostsullivan_proof", "ant_mulan_ai", "ciie_smartchain", "beichen_cloudcomm", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session='从0到1', cohort=NULL, team_name='牛来', project_name='洪水安防地理智能系统', tagline='山洪面前，让AI替基层抢出宝贵的27分钟', demo_order='2', project_description='一、问题\n山洪与山体滑坡是我国伤亡最频繁的灾害类型之一，但基层防汛长期存在四个结构性难题：\n来得快，判得慢。 一条沟谷从发现险情到洪峰抵达往往只有十几分钟，而县级指挥部要同时盯十几个乡镇、上百个村组，靠人工会商研判，平均需要 30 分钟以上才能定下"转移谁、派谁去、走哪条路"。\n预警发得出，群众看不懂。 传统预警是专业术语堆砌的水文数据，村民看不明白，不知道该不该走、往哪走。\n断网即失联。 极端天气下公网基站断电，村民求救无门，指挥部的指令也下不去，最危险的时刻恰恰是通信最差的时刻。\n灾后统计拖太久。 农田定损靠人跑田、填表、层层汇总，一个县往往要 7 天才能出结果，直接影响救灾与理赔进度。\n二、方案\nFloodGuard 用"测-报-预-救-评"五个环节串成一条 AI 驱动的闭环：\n测：接入雨量站、雷达、卫星多源数据，一并纳入地形坡度、土壤类型、人口分布。\n报：按国标自动生成红/橙/黄/蓝四级预警，同时产出两个版本——给村民的通俗版和给指挥部的专业溯源版。\n预：核心是八步山洪推演引擎——降雨输入 → 产汇流 → 沟道演进 → 淹没分析 → 风险评估 → 分级预警 → 转移任务 → 反馈校正。8 秒跑完传统需要数小时的水文研判，洪峰到达误差 ±15 分钟、淹没范围误差 ±12%。\n救：村民一键 SOS 后，AI 智能派单自动检索应急预案、调用推演模型、匹配最近救援队伍、规划绕开深水点的路线、生成任务包直达救援人员手机；公网中断时自动改走北斗短报文，做到"断网不断联"。\n评：结合淹没水深与无人机正射影像 AI 识别受淹农田，定损周期从 7 天压缩到 2 天。\n关键设计原则：AI 只做"翻译"与"编排"，绝不直接做数值计算。所有水文结果由确定性模型产出，每一条处置建议都必须能回溯到官方应急预案原文——在防汛场景，模型不容许编造。\n技术底座：以 Dify 为编排平台，落地 LLMOps / RAG / Agent / AI Workflow 四类能力，形成可被企业直接采纳的 MVP。\n三、现场完成内容\n1. 可交互离线作品（单文件，零依赖）\nFloodGuard-离线完整版.html（约 290 KB）——两个高质量移动端 Demo 已内联进同一文件，U 盘拷贝或邮件发送后双击即可运行，无需后端、无需联网。\n四角色登录隔离：水利气象指挥部、受灾村民、应急救援队、农业灾情统计员，各司其职、数据互通。\nGIS 指挥调度大屏：淹没范围、北斗短报文链路、安置点、救援力量、物资需求、活跃预警、底部「时光机」推演轴。\n八步模型链自动推演：进入页面即自动推进，每 1.6 秒点亮一步，参数修改自动重算，全程零点击。\nAI 智能中枢：山洪推演引擎、AI 智能派单、应急预案库、准确率评测四个页签，进入后自动动画演示运行全过程。\n村民端 / 救援端：完整手机端 Demo，含预警接收、避险登记、SOS 求救、安置点导航、任务接收与执行上报。\n农业灾情统计端：灾情登记、损失汇总。\n2. Dify 编排工程（dify/）\n4 个工作流 DSL：八步山洪推演 / SOS 智能派单 Agent / 应急预案检索 / 灾后 AI 定损，可直接导入 Dify 复现。\n3 套知识库语料：防汛应急预案汇编、历史山洪灾情案例库、山洪滑坡避险指引。\nLLMOps：22 条评测用例 + 提示词版本管理 + 回归阻断机制（准确率下降超 1 个百分点自动阻止上线）。\n3. 完整前后端源码（11 FloodGuard/）\nReact 18 + TypeScript + Vite 前端，Express + TypeScript + SQLite 后端，Leaflet GIS，WebSocket 实时通信，Docker / Vercel 部署配置。\n四、使用方式\n评委 / 普通用户：直接体验\n双击打开 FloodGuard-离线完整版.html（现代浏览器即可，推荐 Chrome / Edge）。\n用各角色演示账号登录依次查看内容\n---\nG001 软件 赛道附加材料\n\n- Slogan: 山洪面前，让AI替基层抢出宝贵的27分钟\n- GitHub 仓库: https://github.com/PillarsCreation/FloodGuard', demo_link='https://github.com/PillarsCreation/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:59:11', is_late='0', created_at='2026-08-30 08:59:11', updated_at='2026-09-01 12:33:32', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99388/cover.png', screenshot_urls=NULL, video_link='https://www.bilibili.com/video/BV1xy4U6DE3b/', github_repo_url='https://github.com/PillarsCreation/FloodGuard', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99388 AND event_id=4;
UPDATE projects SET event_id='4', team_id='176', captain_application_id='292', topics='["tripo_hergaze", "sappho_love"]', sponsor_consents='{"tripo_hergaze": {"rights": "非独占、全球范围、免费", "topic_code": "tripo_hergaze", "sponsor_key": "tripo", "topic_title": "为她而设计 — Her Gaze, Her Game", "consented_at": "2026-08-28T15:32:07+08:00", "consented_ip": "123.118.98.110", "sponsor_label": "Tripo 3D", "sponsor_full_name": "Tripo 3D (Vietnam)", "consented_user_agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36 Edg/151.0.0.0"}}', application_id=NULL, session=NULL, cohort=NULL, team_name='再借我亿点偷啃', project_name='盖娅的舞会 Where the Roots Dance', tagline='在一个仍然生长的世界里，重新学习如何看见、理解与记录', demo_order='219', project_description='项目背景\n·项目原点\n我们的创作起点，来自对“什么会被看见，什么会被记录”这一问题的观察。\n在科学史中，知识并不总是以今天熟悉的专业机构、论文与正式署名的方式产生。18—19 世纪植物学逐渐普及的过程中，女性曾广泛参与植物采集、观察、分类、标本制作与知识交换。植物学一度是女性相对能够进入的科学领域，但随着自然科学进一步专业化、制度化，一部分由女性参与的植物实践逐渐被重新描述为业余爱好、家庭教育或辅助性劳动。她们参与了知识的形成，却未必以同样的方式进入后来被书写和保存的科学史。\n这使我们开始关注一种并不只存在于历史中的现象：当一种知识无法被现有的分类、评价和记录体系完整描述时，被忽略的究竟是知识本身，还是我们观看它的方式？\n菌类与菌丝网络为这个问题提供了另一重启发。我们通常首先注意到地表上短暂出现、拥有明确形态的子实体，却很难直接看见地下持续延展的菌丝网络。后者通过连接、交换与共生参与整个生态系统，却往往隐藏在可见结果之下。当生命的价值习惯性地通过可见成果、“生产”与“繁殖”进行理解时，那些发生在地下、关系之间以及漫长时间尺度中的照料、连接和互惠，又应该如何被看见？\n这种“可见的结果与不可见的关系”逐渐成为项目最初的创作母题。\n与此同时，《地球尽头的温室》《如果我们无法以光速前进》《一个女人认为自己是行星》等女性科幻作品，也影响了我们对于灾后世界的想象。相比以战争、征服、技术扩张或英雄拯救作为核心的末日叙事，我们更希望从植物、环境、研究、照料与关系出发，想象灾难之后生命如何继续存在，以及人类如何重新理解一个已经不再完全服从自身秩序的世界。\n·从创作观察到游戏问题\n当我们开始把这些观察转化为游戏时，我们意识到，它们与游戏中一些习以为常的规则存在有趣的对应。\n游戏中的“成长”通常意味着获得更高的等级、更强的能力和更多资源；“探索”往往意味着发现、收集和占有；环境中的异常通常意味着需要被修复、清除或恢复到预设状态。\n于是我们提出了一个最初的设计问题：如果玩家的成长不是变得更强，而是不断发现自己原先理解世界的方式并不完整呢？\n由此，我们将项目设计为一款以植物和生态关系作为探索语言的第一人称 3D 叙事解谜游戏。\n玩家不是通过战斗征服遗迹，而是通过观察、采样、识别、实验和植物互动逐渐理解环境。玩家最初依赖官方数据库和调查系统认识世界，但随着探索深入，会不断遇到无法被既有模型完整解释的现象：不同植物之间彼此连接的地下网络、突破人工培养边界的生命、停止运行多年却依然稳定的生态，以及没有出现在正式研究记录中的历史。\n因此，游戏中的成长主要表现为认知上的成长：从发现异常、尝试解释到获得证据、发现原有解释不足再修正自己的判断。\n在核心谜题中，这种认知变化进一步成为实际操作。玩家需要根据自己在环境中获得的证据判断：究竟应该让已经变化的生态重新服从旧有模型，还是承认旧模型已经无法描述眼前仍在生长的世界。遗迹中的植物早已突破人工划定的培养范围，而旧规划与现实环境之间的差异正是玩家进行判断的重要依据。\n·为什么用游戏表达\n我们最终选择游戏，不只是因为希望讲述一段关于植物、女性研究者和灾后生态的故事，而是因为这个问题需要玩家亲自做出判断。\n如果通过文字或影像直接告诉玩家“旧有的分类可能是不完整的”“生命不应该只是资源”，玩家获得的是一个已经完成的结论。\n而在游戏中，我们可以先让玩家学习并信任一套规则。\n玩家使用官方工具识别植物、采集环境样本、更新调查报告，并逐渐习惯通过数据库、编号和标准化参数理解遗迹；随后，环境开始不断出现无法被这套系统完整解释的现象。玩家必须把数据库信息、植物状态、空间变化、私人研究记录和自己的观察结合起来，重新建立对世界的判断。\n因此，我们希望让玩家经历对于“规则”认识的转变——我按照原来的规则行动，却亲自发现它已经无法解释眼前的世界。\n最终，玩家完成调查后，官方系统会根据其采集到的真实数据，将这片区域总结为具有“持续性生态利用价值”，并建议进一步开展资源调查与利用评估。\n这里并没有虚假的数据，但问题是：准确的数据，是否就意味着完整的理解？\n这也成为项目最终希望留给玩家的问题：\n当旧的规则无法解释一个仍在生长的世界时，我们选择修正世界，还是修正规则？\n\n---\n目标用户\n本作的核心目标用户为 18–30 岁、偏好叙事体验、环境探索与轻度解谜的独立游戏玩家。他以女性玩家、剧情向玩家、文艺向单机玩家为主，拒绝爽感快餐玩法，追求氛围、思辨与沉浸式探索体验。\n核心用户画像\n1. 喜欢观察、推理与自主发现的叙事解谜玩家\n这类玩家享受从场景细节、环境变化和碎片信息中建立联系，而不是单纯按照任务箭头寻找下一个交互点。本作以“发现异常—形成判断—主动验证—修正认知”作为主要探索节奏，希望提供一种更接近调查与推理的解谜体验。\n随着新的证据出现，玩家还会不断重新理解此前见过的空间与线索。因此，解开谜题带来的满足感不仅来自“找到答案”，也来自某个瞬间意识到：原来之前看到的一切，还可以这样理解。\n2. 偏爱人文科幻、生态题材与氛围叙事的玩家\n本作尤其适合喜欢轻科幻、灾后生态与人文思辨题材的玩家。这类玩家通常也更愿意接受留白、碎片化叙事和需要主动拼合的信息结构。\n与以战斗、生存竞争和英雄拯救为中心的灾后叙事不同，本作从植物、研究、记忆与生命关系出发理解灾后的世界。玩家面对的核心问题不是“如何击败这里的威胁”，而是“这里为什么仍然能够生长”“过去的人如何理解它”“我们今天又应该如何面对它”。关注自然与人类、掌控与共生、体系与个体的深层主题，愿意为剧情立意、世界观留白与思想内核付费。\n3. 关注女性叙事与非征服式游戏体验的玩家\n游戏以一段被遗忘的女性植物学研究史作为重要叙事线索，但不会通过直接说教呈现主题。玩家通过私人信件、研究记录、空间遗留物以及官方档案之间的差异，逐渐发现那些没有进入正式历史的知识与关系。\n这类玩家偏好无暴力、无血腥、氛围细腻、视角温柔的游戏叙事。认同女性研究者视角，偏爱以观察、陪伴、共生、思考为核心的玩法，区别于传统冒险游戏的掠夺式、征服式体验，注重情绪共鸣与剧情留白质感。\n4. 喜欢低操作压力、完整单机体验的轻度玩家\n本作没有复杂战斗、等级养成或高强度操作要求，核心交互集中于移动探索、环境观察、植物识别、采样、实验与轻度空间解谜。\n因此，即使玩家不是硬核解谜或动作游戏用户，也可以通过视觉线索、环境反馈和逐渐积累的信息理解谜题。我们希望降低操作门槛，，让玩家能够把注意力集中在环境、故事与自己的判断上。\n核心体验需求\n这些用户虽然可能因为植物、科幻、解谜或女性叙事等不同元素进入游戏，但我们希望最终满足的是同一种体验需求：\n进入一个陌生而安静的世界，通过自己的观察发现异常、建立联系、验证猜想，并在不断深入的过程中发现：自己最初理解这个世界的方式并不完整。\n因此，本作不以持续的即时刺激作为主要驱动力，而以好奇心、发现感、认知反转和沉浸感维持探索动力；不要求玩家拥有植物学知识，而是让玩家在游玩过程中逐渐学会“如何阅读植物与环境”。\n本作核心目标用户为18–30岁、偏好叙事体验与轻解谜的独立游戏玩家，以女性玩家、剧情向玩家、文艺向单机玩家为主，拒绝爽感快餐玩法，追求氛围、思辨与沉浸式探索体验。\n\n---\n技术栈\n1. 开发引擎与基础环境\n本项目为96小时Game Jam极限开发的3D叙事生态解谜游戏，整体技术选型围绕轻量化开发、高稳定性、快速迭代、氛围表现力优先的核心原则搭建，适配短周期Demo完整体验闭环开发，兼顾视觉表现、玩法机制与叙事系统落地，具体技术栈配置如下：\n基于 Unity 6.3 LTS 开发，采用 C# 实现核心游戏逻辑，并以 URP 完成第一人称 3D 灾后生态环境的实时渲染。围绕“植物与生态关系作为探索语言”的核心体验，项目将程序系统、3D 场景与环境叙事结合，使玩家能够通过观察、调查和环境反馈理解并推进游戏。\n2. 游戏开发与交互： \nUnity 6.3 LTS / C# / Unity Input System / Cinemachine / UI Toolkit。主要实现第一人称探索、物体交互、植物识别与采样、环境状态变化、生态谜题、事件触发以及官方调查报告等系统。\n3. 3D 美术与场景：\n采用 DCC → Unity 工作流。主场景、核心建筑及关键探索空间由团队自主建模和搭建，并在 Unity 中完成材质、灯光、碰撞、交互与环境效果整合；非核心环境与装饰部分根据开发周期使用部分现成素材。3D 场景同时承担空间引导和谜题信息传递，使植物分布、生态边界、人工设施与环境变化本身成为玩家可以“阅读”的线索。\n4. 视觉表现：\n 基于 URP 构建污染区、植物研究所、温室及菌丝生态等不同环境状态，通过植被、材质、光照与环境效果的变化强化区域之间的视觉差异，并服务于无强制箭头的环境引导。\n5. 工程与协作\n 使用 Git + GitHub + Git LFS 进行版本管理，采用分支与 Pull Request 工作流；通过 Multi-Scene / Additive Scene 拆分不同开发区域，并结合 UnityYAMLMerge 降低多人并行编辑 Scene 与 Prefab 时的冲突。项目同时建立统一的 C#、目录结构、场景协作、性能及版本控制规范，以支持短周期内的多人并行开发。\n6. 项目管控与优化技术\n针对Demo场景进行模型面数精简、特效层级优化、资源按需加载，保证低配置设备可流畅运行，无卡顿、无阻断性BUG。适配96小时极限开发周期，采用模块化分工开发，机制、美术、叙事、音频并行迭代，精准落地MVP核心功能，保障体验闭环完整。\n\n---\n创新点\n本项目的创新来自题材表达与游戏机制两个层面的共同设计。\n在题材上，我们将女性植物学史、生态关系与灾后科幻想象结合，以一座被植物与菌丝重新占据的废弃研究所为舞台，关注那些在正式记录之外仍然持续生长的生命、知识与历史。\n在玩法上，我们进一步尝试将这些主题转化为玩家可以直接体验的规则：成长不一定意味着变强，植物不一定意味着资源，发现不一定意味着占有，而准确记录也不一定意味着真正理解。\n我们希望玩家不是在游戏结束后才通过剧情“理解主题”，而是在探索、判断和解谜的过程中，已经亲自经历这些问题。\n1. 女性植物学史 × 生态科幻的题材与叙事视角\n本作将女性植物学研究史、菌丝生态与灾后科幻放入同一个世界观中。\n我们的灵感来自一个真实的历史观察：女性曾长期参与植物采集、观察、分类和知识传播，但随着科学逐渐专业化、制度化，其中一部分实践被重新定义为业余、家庭或辅助性劳动。她们参与形成的知识并没有完全消失，却未必以同样的方式进入后来被认可和保存的历史。\n菌丝网络与植物生态则为这一问题提供了另一层自然隐喻——地表可见的生命只是整个生态的一部分，在地下还存在着难以直接观察，却持续发生连接、交换与共生的关系网络。\n因此，本作没有选择传统灾后游戏中常见的生存竞争、资源争夺与英雄拯救作为核心，而是从一名植物研究者的视角进入废墟，通过植物、研究、私人通信和环境遗迹重新理解灾难之后仍然延续的生命与知识。\n这里的女性历史也不是作为背景文本附着在玩法之外。随着调查深入，玩家逐渐发现：今天仍在维持生态的知识，与那些没有被完整写入正式历史的研究之间存在联系。\n2. 以「认知成长」替代传统数值成长\n我们不拘泥于传统解谜游戏“找道具、开机关、提示引导”的固化模式，尝试重新理解游戏中的“成长”，构建观察—假设—验证—认知重构的完整科研式探索闭环。玩家以植物研究者的思维开展探索，通过采样、识别、环境比对完成逻辑推理与假设验证，使解谜从机械操作转变为认知迭代与科学探究，实现玩法、人设、世界观的高度统一。\n新的信息因此不仅意味着“获得一条线索”，还可能改变玩家对已经见过的线索的理解。本作希望让玩家获得一种不同于数值升级的成长体验：不是“我现在更强了”，而是“我现在看见了以前看不见的东西”。\n3. 植物不是资源，而是「阅读世界的语言」\n区别于多数游戏将植物作为装饰、资源或道具的浅层设计，本项目将植被、根系、菌丝体系升级为解读遗迹历史与生态真相的核心媒介，让植物自身成为环境信息的一部分。\n植物的生长方位、长势差异、边界突破形态、人为采样痕迹与生态制衡关系，均可反向推导场地环境演变、前人实验轨迹与仙女环生态运作规律。植物同时承担线索载体、解谜核心、世界观证明与叙事载体多重功能，随着游戏推进，玩家实际上是在逐渐学习一套新的“生态语言”，并利用这种语言阅读空间、发现路径和理解历史。\n4. 「生态协商式解谜」：从征服环境到理解环境\n在传统冒险游戏中，环境障碍常遵循“获得能力—破坏障碍—继续前进”的结构。本作尝试建立另一种关系：玩家不是消灭阻碍自己的生命，而是理解它为什么会产生这种行为，并利用生态关系使其主动发生改变。\n例如，面对具有自我修复能力的活体菌丝屏障，单一植物作用无法将其解除。玩家需要理解不同物种释放的生态信号，将具有亲和作用与抑制作用的信号组合，使菌丝网络改变自身状态并主动退让。\n我们将这种设计概括为：生态协商式解谜（Ecological Negotiation Puzzle）：不是征服环境，而是理解环境如何响应。\n这一逻辑也延伸到大型环境谜题中。当植物已经突破过去人工规划的培养边界时，玩家真正需要判断的不是“哪个按钮才是正确答案”，思考当现实已经改变，我们应该让现实重新服从模型，还是让模型重新学习现实？\n于是，游戏的主题不再只是存在于剧情文本中，而直接进入了玩家解决谜题时所遵循的规则。\n5. 双重记录系统：让「谁定义知识」成为玩法\n本作同时设置了官方调查报告与个人植物手记两套记录系统。官方报告记录物种编号、污染数据、设施状态、异常指标与资源价值；个人手记则逐渐记录植物之间的关系、研究者留下的痕迹、无法被数据库解释的现象，以及主角不断发生变化的判断。\n官方系统并不是一个简单的“错误系统”。它可以准确回答“这是什么”“数值是多少”“是否具有利用价值”，却很难回答“为什么它们能够共同存在”“这些知识从哪里来”“什么没有进入正式记录”。\n随着游戏推进，两套系统对于同一个世界逐渐形成不同的描述。最终，当官方系统准备把玩家发现的一切重新整理为可调查、可开发、可利用的信息时，“记录”本身也成为玩家必须重新思考的行为：发现一种生命、知识或历史之后，我们应该如何记录它？而记录它，是否也意味着重新定义甚至占有它？\n创新的整体价值：\n我们不仅希望选择一个较少被游戏表现的题材，也希望为这个题材寻找只属于游戏的表达方式。\n女性植物学史与生态科幻构成了作品的题材创新；从“征服与占有”转向“观察、关系与共生”构成了作品的视角创新；认知成长、植物环境语言与生态协商式解谜构成了玩法创新；官方报告与个人手记则进一步让叙事主题进入游戏规则本身。\n最终，这些创新共同服务于同一个核心问题：\n当旧的规则无法解释一个仍在生长的世界，我们选择修正世界，还是修正规则？\n\n---\n团队分工\n本项目为96小时极限GameJam开发项目，团队分为策划组、美术组、程序组三大模块，各组权责清晰、并行协作、高度配合，保障项目在短周期内完成完整Demo闭环体验，具体分工如下：\n一、策划组\n负责项目整体框架搭建、玩法设计、叙事内容制作与项目进度统筹，把控游戏核心体验与整体调性。\n1. 核心设计：敲定项目整体玩法机制，设计「观察—假设—验证—认知重构」核心探索循环，搭建生态解谜规则、双记录系统、认知反转叙事体系，确定MVP核心功能与可删减内容，严控96小时开发范围。\n2. 关卡与流程设计：规划研究站、温室、实验室、地下菌丝区域整体探索动线，设计全流程谜题逻辑、异常交互节点与探索触发顺序，保障玩家认知递进体验完整闭环。\n3. 叙事与文案制作：撰写全套世界观背景、玩法说明、植物扫描文案、实验日志、研究员手记、官方报告与私人手记内容，统一全文案叙事风格与思辨主题。\n4. 项目统筹与落地：对接美术、程序同步需求，跟进各模块开发进度，试玩测试并优化体验细节，收尾项目路演文案、项目文档整合与成果输出。\n二、美术组\n负责项目所有视觉表现、场景氛围、动态特效与材质渲染，打造贴合温柔废土、生态叙事的专属美术风格。\n1. 3D场景搭建：完成研究站、废弃温室、廊道、地下菌丝核心区域模块化搭建，还原“人工设施被自然植被侵占”的视觉叙事效果，匹配关卡探索动线优化场景布局。\n2. 模型与资产制作：制作植物、菌丝、实验设备、废弃道具等核心场景资产，贴合灾后生态研究站设定，统一模型风格与精度标准，适配Demo轻量化运行需求。\n3. 材质与氛围渲染：调试场景光影、氛围材质，制作积灰、老旧、湿润、通透菌丝等质感表现，搭建整体静谧、隐秘、沉浸式的探索氛围。\n4. 动态特效制作：制作植物生长、生态微光、试剂融合、菌丝收缩、光场交互等核心VFX特效，联动玩法机制，实现生态逻辑可视化表现。\n5. UI视觉设计：制作植物扫描界面、实验图纸、报告面板、手记界面等功能性UI，贴合项目科研生态主题，保证界面简洁直观、适配叙事展示。\n三、程序组\n负责所有玩法功能、交互逻辑、系统框架开发与性能优化，实现策划设计的全部核心机制，保障项目稳定运行。\n1. 基础交互框架开发：搭建玩家移动、场景交互、物品拾取、工具调用、扫描采样、植株交互等基础功能，统一全游戏交互逻辑，适配快速迭代开发。\n2. 核心玩法开发：实现植物状态生长模拟、生态制衡解谜逻辑、环境异常判定、线索触发与进度解锁机制，落地「观察验证式」核心解谜玩法。\n3. 核心系统开发：搭建双记录系统逻辑，实现官方探索报告数据自动收录、私人手记内容存储与留存，完成结局抉择机制、进度存档逻辑开发。\n4. 叙事与UI功能实现：对接文案资源，实现线索弹窗、日志阅览、图纸展示、植物档案、剧情文本动态触发与进度解锁功能。\n5. 性能优化与Bug修复：针对场景模型、特效、资源进行轻量化优化，排查并修复阻断性Bug，保障Demo流畅稳定运行，完成最终打包输出。\n\n---\n开发过程\n本项目在 96 小时 Game Jam 周期内完成。面对 3D 游戏在场景、程序、玩法与叙事整合上的开发压力，团队没有追求一次性完成所有设想，而是先确定 Demo 必须成立的核心体验，再将玩法、程序、美术和叙事拆分并行制作，并通过持续整合与试玩逐步完成最终版本。\n整体开发过程可以分为四个阶段：\n1. 核心体验确认与 Demo 范围收束\n项目初期，团队首先统一游戏的核心定位，并将较大的世界观与主题研究收束为一个可以实际验证的体验目标：玩家能否通过观察植物与环境、提出判断并主动验证，在探索过程中不断修正自己对世界的理解？\n围绕这一目标，我们确定了“探索—发现异常—调查—判断—验证—认知更新”的核心玩法循环，并主动控制 Demo 的开发范围。战斗、复杂数值成长、大规模开放区域等与核心体验关系较弱的系统没有进入当前版本；开发资源优先投入到第一人称探索、植物观察与调查、生态解谜、环境叙事、双重记录以及最终选择等关键内容中。\n同时，策划组完成玩法机制、关卡动线、谜题逻辑、叙事文案与项目文档体系搭建，团队梳理完整体验流程与关键节点，以一个能够从进入遗迹、建立调查规则，到逐渐发现异常、修正认知并完成最终选择的完整可玩 Demo作为共同开发目标。\n2. 玩法、程序、美术与叙事并行制作\n核心流程确定后，项目进入多模块并行开发阶段。这一阶段各模块围绕同一条玩家动线持续交换可用版本，使关卡、美术、程序与文本能够同步调整。\n策划与叙事侧继续细化关卡动线、植物机制、谜题条件、调查内容、环境线索与文本，并根据实际实现情况持续调整信息密度和流程节奏。\n程序侧基于 Unity 搭建第一人称移动与交互框架，并逐步实现植物识别与采样、调查对象、环境状态、谜题触发、剧情事件、报告与手记等核心系统，为后续内容快速接入提供基础。\n3D 美术与场景侧则同步进行灰盒验证、主建筑与核心空间制作、场景搭建、材质灯光和生态环境表现。核心建筑与主要探索空间由团队自主制作，同时在非核心环境内容中合理使用现成资产，将制作时间集中到真正影响探索体验与视觉识别的区域。\n3. 从独立功能到完整游戏体验\n中后期的重点从“功能是否能够运行”转向“这些功能组合起来之后，是否真的形成了我们的核心体验”。\n团队开始将植物生态规律、空间设计、调查工具与谜题状态进一步整合。例如，植物不再只是一个可以扫描并返回信息的对象，它的分布、生长状态和与其他生命的关系也需要成为玩家判断环境的依据；谜题的完成也不只是触发机关，而需要通过植物、菌丝、设施与环境变化给予玩家能够观察到的反馈。\n叙事内容同样在这一阶段进一步进入玩法。研究记录、私人信件、环境痕迹不再单独承担“讲故事”的功能，而是与玩家正在调查的问题相互印证；官方调查报告与个人植物手记则分别记录同一次探索中不同层面的信息，使两套记录之间的差异随着流程推进逐渐显现。\n通过这一阶段的整合，最初分别开发的探索、植物调查、生态解谜、环境叙事与记录系统被串联成同一条玩家体验。\n4. 完整流程试玩与体验打磨\n进入开发后期后，团队将主要精力转向完整流程试玩，而不再继续扩张功能范围。\n测试重点不仅包括流程阻断、触发异常、场景碰撞和功能 Bug，也包括一些更直接影响本作体验的问题：玩家是否能够注意到关键植物？是否能够理解环境发生了什么变化？谜题给出的信息是否足够形成判断？文本是否说得太多或太少？没有强制任务箭头时，玩家是否仍然知道自己应该探索哪里？\n针对试玩结果，团队持续调整植物与场景线索的可读性、交互反馈、谜题提示、文本出现时机、环境引导与整体探索节奏，并同步进行场景、模型、灯光与运行性能方面的优化。\n最终，我们希望 Demo 达到的并不是“展示尽可能多的功能”，而是让玩家能够从头到尾完整经历一次：\n进入未知环境 → 学会调查 → 发现既有解释的局限 → 利用新的证据理解生态 → 修正自己的判断 → 面对最终选择。\n\n---\n后续计划\n当前 Game Jam Demo 主要用于验证三个核心设计是否能够成立：以认知变化驱动探索、以植物与生态关系构成谜题，以及通过不同记录方式让玩家重新思考“什么是有效知识”。\n如果项目继续开发，我们不会单纯通过增加地图和文本扩充内容，而会围绕这套已经建立的核心机制继续深化。\n1.  深化植物与生态解谜机制\n现阶段 Demo 已经建立了通过植物特性、环境状态与物种关系进行探索和解谜的基础框架。后续将进一步丰富植物之间的共生、竞争、信号传递、环境适应与群落变化，让生态关系本身产生更多可观察、可推理、可利用的玩法可能。谜题设计也将逐渐减少“一种植物对应一种固定功能”的方式，增加不同环境条件与物种关系之间的组合。玩家需要先观察现象、提出假设，再通过实验和环境反馈验证自己的判断。\n我们希望最终形成更完整的“生态协商式解谜”：玩家面对的不是等待被清除的障碍，而是一个具有自身运行规律的生命系统；解决问题的关键，在于理解它如何响应。\n2. 完善以知识为核心的「认知成长」系统\n后续版本将进一步强化本作区别于传统数值成长的“认知成长”。\n玩家在早期获得的植物记录、生态规律、研究资料与环境经验，将不仅承担剧情信息功能，还能够参与后续区域的判断与解谜。随着知识不断积累，玩家能够识别过去无法理解的生态模式、建立更复杂的假设，并重新解释曾经调查过的空间与历史。\n我们希望进一步验证一个核心设计方向：知识本身，能否像传统游戏中的技能与装备一样，成为真正具有玩法价值的成长资源？由此让“越来越能够理解这个世界”本身，成为玩家持续探索的重要动力。\n3. 深化双重记录与玩家选择\n现有 Demo 中的官方调查报告与个人植物手记将继续作为后续叙事系统的重要核心。\n未来版本中，两套记录不仅呈现不同的信息，也可以进一步与玩家行为产生联系：哪些发现进入正式报告、如何描述某种异常、哪些关系被保留下来，以及调查结果如何被安全区重新解释，都可能影响后续任务、机构反馈乃至故事走向。\n最终选择也将避免被简化为“提交 / 不提交”“开发 / 保护”的善恶二选一。我们希望建立更复杂的处境：知识需要被记录才能得到保存，但进入制度与资源体系，也可能意味着它再次被分类、定义和利用。\n这样，结局不再是流程末尾突然出现的一道选择题，而是玩家此前所有观察、怀疑与认知变化的自然结果。\n4. 扩展遗迹、生态区域与完整世界\n当前植物研究所代表的是完整世界中的第一个核心调查区域。未来可以围绕安全区边界、菌丝生态以及灾后研究历史，继续扩展具有不同生态特征和历史背景的遗迹。\n每个区域都可以围绕一组新的关系展开：新的生态现象 → 既有知识无法完整解释 → 调查与验证 → 发现新的生命关系 → 被遗漏的历史浮现 → 玩家重新建立理解。不同区域不会只是更换场景与植物，而会引入新的生态规律和观察方式。随着多个调查地点的信息逐渐连接，玩家也将从一座研究所的局部历史，逐渐理解安全区的形成、菌丝网络的发展，以及不同研究者与知识网络之间更大的联系。\n这一结构使当前 Demo 所验证的核心循环能够自然扩展，而不必依赖简单增加关卡数量或重复谜题。\n5. 体验优化与正式版本适配\n在内容扩展之外，后续开发也将持续进行完整的体验与产品化打磨。\n技术层面将进一步优化运行性能、场景加载、第一人称移动与交互手感，并根据目标发布平台进行性能与操作适配，保证复杂植被与 3D 环境下的稳定运行。\n体验层面将通过更多玩家测试完善新手引导与环境信息的可读性。本作仍会保留弱 UI、少任务箭头、鼓励玩家主动观察环境的设计方向，但会进一步优化视觉引导、交互反馈和渐进式教学，在不直接给出答案的情况下，让玩家更自然地理解“应该观察什么”以及“如何验证自己的判断”。\n叙事层面则将继续优化最终选择的前置铺垫、行为反馈与结局留白，使植物研究、女性历史、官方记录与玩家个人理解最终汇聚到同一个选择中，并在游戏结束后保留足够的情绪余味与思考空间。\n最终，我们希望将当前的 Game Jam Demo 逐步打磨为一款在核心玩法、叙事表达、视觉氛围与运行体验上均具备完整性的独立 3D 叙事解谜作品，并为后续正式发布做好准备。\n未来愿景\n当前 Demo 对我们而言并不是一个完整世界的缩小版，而更像是对一套游戏设计语言的第一次验证。\n如果项目继续发展，我们希望每一个新区域带给玩家的，不是一个更强的敌人，而是一种此前无法理解的生命关系；每一次成长，也不是获得更高的数值，而是获得一种新的观察、判断和理解世界的方法。\n最终，我们希望沿着当前原型继续回答游戏最初提出的问题：\n当旧的规则无法解释一个仍在生长的世界，我们是让世界重新服从规则，还是学会用新的方式理解它？\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 在一个仍然生长的世界里，重新学习如何看见、理解与记录\n- GitHub 仓库: https://github.com/AmanThuL/shenicest-2026\n- 游戏玩法说明:\n  01｜核心玩法\n  ·一场从“调查”开始，到“理解”结束的探索\n  本项目是一款以植物与生态关系作为探索语言的 3D 叙事解谜游戏。\n  家扮演一名受安全区派遣的植物研究者，进入一座长期废弃的生态研究遗迹，通过观察环境、识别植物、采集样本、阅读研究痕迹并利用不同生命之间的生态关系，逐步深入遗迹并重构这里曾经发生的历史。\n  玩家不会通过旁白直接获得遗迹的历史，而需要在空间中主动寻找答案：观察植物的生长状态，辨认根系与菌丝的蔓延，检查研究设施与资源采集痕迹，读取不同年代留下的研究记录，并使用采样、识别等工具验证自己的判断。\n  游戏不设置战斗、等级或传统数值成长。玩家的主要成长来自认知变化：随着新的环境证据不断出现，原本已经“看懂”的植物、设施与历史痕迹会获得新的含义。玩家不是通过变得更强来进入下一个区域，而是通过知道得更多、看得更深、修正此前的判断继续前进。\n  当调查趋近尾声，玩家的核心疑问将不再是「这里曾经发生了什么」，而是「知晓全部真相后，我该如何面对」。\n  \n  ·玩家目标\n  玩家最初的明确任务是：进入废弃植物研究所，完成生态与资源调查，并形成调查报告返回安全区。\n  但随着探索深入，玩家会发现调查对象远比官方任务描述复杂：植物正在突破过去人工划定的生长边界；地下菌丝形成了现有数据库无法完整解释的生态网络；研究所中还残留着一段没有进入正式历史的女性植物学研究记录。\n  因此，玩家的目标会逐渐从“完成一次资源调查”转变为“理解这里究竟发生了什么，以及自己应该如何记录所发现的一切”。\n  \n  ·基础操作\n  游戏采用第一人称探索方式，保持较低的操作门槛，让玩家将注意力集中于环境观察和信息判断。\n  玩家主要进行移动与视角观察、调查环境对象、使用识别/采样工具、阅读研究记录、操作研究设施、使用植物或实验产物与环境互动，以及查看官方调查报告和个人植物手记。\n  游戏尽量减少持续任务箭头和强制路径提示。可探索方向主要通过植被密度、植物生长状态、地形结构、光照、声音、人工痕迹与环境变化进行引导，使“观察空间”本身成为操作的一部分。\n  \n  ·关键交互\n  游戏中的关键交互主要围绕“观察—验证—理解”设计。\n  1.植物识别与环境采样：\n   玩家可以使用研究设备识别植物、采集土壤与环境样本，获得物种、污染程度、生长状态等调查数据。相关结果会进入官方调查系统。但随着探索深入，玩家会逐渐发现：识别一个对象，并不意味着理解它与环境之间的关系。\n  2.植物与生态互动：\n   植物不是单纯的收集物或消耗型道具。玩家需要观察根系方向、生长范围、形态变化、共生状态与群落分布，从植物本身读取空间和生态信息，并利用这些关系解决环境谜题。\n  3.生态实验：\n   面对部分活体生态障碍，玩家需要结合不同植物产生的信号与作用进行实验。例如通过不同生态信号的耦合改变菌丝网络状态，使其主动退让。玩家不是简单“破坏障碍”，而是在理解环境规律后促使其产生响应。\n  4.设施操作与环境反馈：\n   部分大型谜题要求玩家结合旧规划图、维护记录和当前植物状态判断设施应该如何运行。操作后，植物、菌丝、设备、声音和空间状态会共同反馈结果，而不是简单弹出“正确 / 错误”。\n  5.调查报告与个人手记：\n   玩家的调查同时进入两套记录系统。官方报告记录分类、环境数据、设施状态与资源价值；个人植物手记则记录关系、疑问、研究历史和主角不断变化的理解。随着探索推进，两套系统对同一个世界逐渐形成不同描述。\n  \n  ·通关条件\n  玩家需要完成研究所主要区域的探索，取得足够的生态与历史证据，解决阻碍调查路线的关键生态谜题，并完成对核心区域的调查。\n  当玩家逐渐理解植物、菌丝、安全区边界与过去研究之间的关系后，将形成最终调查结果。此时，游戏把最初的任务重新交还给玩家：是否将自己的调查发现提交给派遣自己前来的安全区系统？这一选择构成当前 Demo 的最终节点。\n  通关的重点并非击败最终敌人或达到某个数值，而是完成一次完整的认知变化：玩家最初作为一名相信调查系统的研究者进入遗迹，最终需要根据自己亲眼看到、亲自验证和重新理解的一切，决定应该如何处理这份知识。\n  \n  02｜核心玩法循环\n  游戏的核心玩法由两个连续的循环构成。\n  第一重循环：认识世界\n  探索空间\n   ↓\n  发现异常\n   ↓\n  观察植物、环境与人工痕迹\n   ↓\n  形成判断 / 提出疑问\n   ↓\n  使用植物或研究工具验证\n   ↓\n  获得新的信息 / 改变环境状态\n   ↓\n  进入新的区域\n   ↓\n  重新理解此前发现的线索\n  \n  玩家进入新的区域后，会首先通过植物生长状态、空间结构、人工设施或异常生态现象发现“不协调之处”。例如，一片本不应稳定生长的植被、一组跨越多个物种的地下根系网络，或者已经突破原有人工培养边界的植物群落。地下观察窗中，多种植物根系甚至呈现出持续连接、且超出现有数据库识别范围的网络结构。\n  玩家随后利用识别器、采样设备、历史记录以及自身的植物学观察形成初步判断。工具能够回答“这是什么”“污染程度是多少”“是否符合数据库”，但往往无法解释“为什么它会在这里”“为什么不同生命会产生这种关系”。这种已知信息与现场现象之间的缺口构成持续探索的动力。\n  获得线索后，玩家需要进一步利用植物特性、生态信号或环境关系进行验证。谜题的解决并不只是打开一道门，同时也会改变玩家对遗迹的理解。此前看似普通的采样痕迹可能被重新理解为资源收割；被系统判定为“异常”的植物，也可能实际上正在形成一种新的稳定生态。\n  因此，每一个局部谜题都遵循一个更深层的循环：\n  获得答案 → 发现答案并不完整 → 提出新的问题。\n  \n  ---\n  第二重循环：面对世界\n  当玩家逐渐完成调查，所有重要事实已经被记录进官方探索报告。\n  此时游戏不再询问：“你找到答案了吗？”\n  而是询问：“你已知晓全部真相，接下来要如何抉择？”\n  玩家最终面对是否提交调查报告的选择。\n  这个选择并不决定世界的存亡，也不是简单的“正确 / 错误”道德选择。\n  玩家无法拯救这个世界，也无法凭借一次选择决定生态系统和人类社会的未来。\n  玩家只是一个调查者。\n  她能够决定的，是自己是否将已经获得的知识交回原本派遣自己的系统。\n  因此，游戏真正关注的是：一个人在理解世界之后，是否还会以进入这个世界时的方式行动。\n  \n  ---\n  03｜亮点玩法一：植物不是道具，而是“探索语言”\n  本游戏最核心的玩法创新，是将植物从传统游戏中的装饰、资源或收集品，转变为玩家解读空间的媒介。\n  玩家需要观察：\n  -  植物在哪里生长； \n  -  它向哪里生长； \n  -  根系如何延伸； \n  -  哪些植物异常旺盛； \n  -  哪些植物已经突破人工划定的边界； \n  -  哪些植物曾经被采样、切割或移植； \n  -  植物与水体、土壤、菌丝以及建筑之间存在怎样的关系。 \n  这些信息共同构成一种新的“地图”，让玩家从「找通关物品」转变为「探索生态规律、找寻空间历史」\n  最终形成：\n  阅读植物 → 推断环境变化 → 验证猜想 → 推进探索\n  植物因此同时承担：\n  世界观、空间线索、解谜核心与叙事载体。\n  \n  ---\n  04｜亮点玩法二：以观察验证解谜，告别提示式答案\n  游戏中的谜题建立在观察与验证之上。\n  玩家进入一个新的区域后，首先面对的不是明确的任务箭头，而是一个需要解释的异常：\n  -  一条无法继续前进的路径； \n  -  一片异常生长的植物； \n  -  一处失效的设施； \n  -  一段颜色特异的根系； \n  -  一组无法解释的环境数据。 \n  玩家需要先观察环境，再提出自己的判断。\n  随后，可以利用：植物知识 + 采样工具 + 识别工具 + 环境信息对判断进行验证。\n  例如：\n  玩家在废弃廊道墙缝发现成片焰苔，异常集中生长在菌丝大门与根节点周边。\n  通过识别、采样工具检测，验证焰苔拥有抑制、驱离菌丝的特殊生态特性。\n  结合场地环境与植物知识判断：焰苔只在菌丝活跃区域旺盛生长，二者存在特殊生态制衡关系。\n  玩家得出结论：菌丝屏障并非固定障碍，可通过焰苔的特殊生物信号进行干涉、解除封堵，以此打通封闭通路。\n  这里不存在单纯的“点击正确物品”。\n  玩家真正完成的是：发现现象 → 提出假设 → 找到证据 → 得出结论。\n  这也是主角作为植物研究者的核心行动方式。\n  \n  ---\n  05｜亮点玩法三：空间本身就是一份历史档案\n  游戏不通过连续的剧情演出来告诉玩家“这里曾经发生过什么”，遗迹本身就是历史档案。\n  玩家可以从：研究记录、前人手记和书信、实验图纸与报告、植物样本、资源标记、废弃实验设备、温室结构中拼合不同阶段的历史。\n  玩家看到的是不同时间留下的痕迹同时存在于同一个空间里，玩家的认知会层层反转，逐渐深入。\n  玩家可能第一次认为：“这里曾经进行过正常的植物采样研究。”后来发现：“这里曾经存在相关实验研究。”再后来试图假设：“零散的采样痕迹，是前人有目的、成体系的生态资源收集实验。”\n  于是此前看似普通的空间突然获得了新的意义。\n  空间不是承载故事的容器，空间本身就是故事。\n  \n  ---\n  06｜亮点玩法四：“记录”本身设计为叙事机制\n  本作同时设置了官方调查报告与个人植物手记两套记录系统。官方报告记录物种编号、污染数据、设施状态、异常指标与资源价值；个人手记则逐渐记录植物之间的关系、研究者留下的痕迹、无法被数据库解释的现象，以及主角不断发生变化的判断。\n  官方系统并不是一个简单的“错误系统”。它可以准确回答“这是什么”“数值是多少”“是否具有利用价值”，却很难回答“为什么它们能够共同存在”“这些知识从哪里来”“什么没有进入正式记录”。\n  随着游戏推进，两套系统对于同一个世界逐渐形成不同的描述。最终，当官方系统准备把玩家发现的一切重新整理为可调查、可开发、可利用的信息时，“记录”本身也成为玩家必须重新思考的行为：发现一种生命、知识或历史之后，我们应该如何记录它？而记录它，是否也意味着重新定义甚至占有它？\n  \n  ---\n  07｜亮点玩法五：谜题有标准答案，结局无固定选择\n  游戏前期解谜拥有客观正确答案，贴合科研严谨性：玩家需要依据完整线索、数据、环境逻辑做出判断，判断正确即可推进流程，错误则无法解锁新内容。\n  例如：在温室核心区域，玩家需要根据此前获得的植物分布、环境数据、维护记录与空间信息，判断当前生态系统应该采用哪一种循环方案。\n  如果判断错误，系统无法正常运行。\n  如果判断正确，生态循环重新建立，玩家得以进入新的区域。\n  但解谜的终点不是游戏的终点。前期谜题解决的是「什么是真相」，而最终结局选择解决的是「知晓真相后，我该如何行动」。\n  真正的核心抉择，永远在找到答案之后。\n  \n  ---\n  08｜亮点玩法六：玩家不是救世主\n  本游戏摒弃「玩家拯救世界」的寻常套路，把玩家的选择与“人类命运”解绑。\n  最终选择并不会改变世界格局：安全区、人类社会以及生态系统，都不会因玩家的单次选择而覆灭或重生。\n  玩家只是一个偶然进入这里的研究者，见证了无人知晓的过往，女性研究者的付出、植物的过往、末日生存必然的功利性，以及自身调查行为与历史的相似性。一处处同构，一处处投射，一处处隐喻，构建起过往与当下，虚构与现实的联系。\n  最终选择无关拯救，我们回到个人的语境，我们如何理解这个世界的真相，然后选择如何面对这个世界。\n  \n  ---\n  09｜玩家成长：以“认知成长”替代数值成长\n  玩家没有等级、战斗力或装备树。真正的成长体现在对世界模型的不断修正。同一个空间会因为后来获得的新证据而产生新的意义。游戏中的核心谜题甚至要求玩家判断：究竟是现实出现了错误，还是过去用于解释现实的模型已经失效。中央温室的循环系统便以此为基础——玩家需要根据环境调查、旧规划图与维护记录判断，当前生态已经突破原有“核心培育”与“标准环形”模型，并选择是否承认正在扩展的新边界\n  因此，玩家真正获得的不是一把更强的工具，而是一种新的阅读游戏与真实世界的方式。\n  玩家的终极成长：从「看见表面现象」到「读懂底层逻辑」，从「被动完成任务」到「反思自身行为」，掌握全新的认知世界、解读世界的方式。\n  \n  ---\n  10｜一句话总结核心玩法\n  探索遗迹，阅读植物，验证真相；在完全知晓真相后，决定自己的最终取舍\n  我们让玩家通过植物找到答案，却把真正的选择留到了答案之后。', demo_link='https://ccnfc0trzyyp.feishu.cn/drive/folder/KDZof5OqCl6DOpdY3uIccZBAnEf?from=from_copylink', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:59:35', is_late='0', created_at='2026-08-30 08:59:35', updated_at='2026-09-01 12:33:37', leader_participant_id=NULL, presentation_link='https://lcnjvknzkiup.feishu.cn/wiki/Ej6LwIX92iBkHQkWEJ7cwGAvnpb', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99389/cover.png', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937c5f19a0d_e506e6c14f0c2906.png","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a937c7f73e1f_a49b6868e077187e.png"]', video_link='https://ccnfc0trzyyp.feishu.cn/drive/folder/KDZof5OqCl6DOpdY3uIccZBAnEf?from=from_copylink', github_repo_url='https://github.com/AmanThuL/shenicest-2026', bom_link_text=NULL, gameplay_description='01｜核心玩法\n·一场从“调查”开始，到“理解”结束的探索\n本项目是一款以植物与生态关系作为探索语言的 3D 叙事解谜游戏。\n家扮演一名受安全区派遣的植物研究者，进入一座长期废弃的生态研究遗迹，通过观察环境、识别植物、采集样本、阅读研究痕迹并利用不同生命之间的生态关系，逐步深入遗迹并重构这里曾经发生的历史。\n玩家不会通过旁白直接获得遗迹的历史，而需要在空间中主动寻找答案：观察植物的生长状态，辨认根系与菌丝的蔓延，检查研究设施与资源采集痕迹，读取不同年代留下的研究记录，并使用采样、识别等工具验证自己的判断。\n游戏不设置战斗、等级或传统数值成长。玩家的主要成长来自认知变化：随着新的环境证据不断出现，原本已经“看懂”的植物、设施与历史痕迹会获得新的含义。玩家不是通过变得更强来进入下一个区域，而是通过知道得更多、看得更深、修正此前的判断继续前进。\n当调查趋近尾声，玩家的核心疑问将不再是「这里曾经发生了什么」，而是「知晓全部真相后，我该如何面对」。\n\n·玩家目标\n玩家最初的明确任务是：进入废弃植物研究所，完成生态与资源调查，并形成调查报告返回安全区。\n但随着探索深入，玩家会发现调查对象远比官方任务描述复杂：植物正在突破过去人工划定的生长边界；地下菌丝形成了现有数据库无法完整解释的生态网络；研究所中还残留着一段没有进入正式历史的女性植物学研究记录。\n因此，玩家的目标会逐渐从“完成一次资源调查”转变为“理解这里究竟发生了什么，以及自己应该如何记录所发现的一切”。\n\n·基础操作\n游戏采用第一人称探索方式，保持较低的操作门槛，让玩家将注意力集中于环境观察和信息判断。\n玩家主要进行移动与视角观察、调查环境对象、使用识别/采样工具、阅读研究记录、操作研究设施、使用植物或实验产物与环境互动，以及查看官方调查报告和个人植物手记。\n游戏尽量减少持续任务箭头和强制路径提示。可探索方向主要通过植被密度、植物生长状态、地形结构、光照、声音、人工痕迹与环境变化进行引导，使“观察空间”本身成为操作的一部分。\n\n·关键交互\n游戏中的关键交互主要围绕“观察—验证—理解”设计。\n1.植物识别与环境采样：\n 玩家可以使用研究设备识别植物、采集土壤与环境样本，获得物种、污染程度、生长状态等调查数据。相关结果会进入官方调查系统。但随着探索深入，玩家会逐渐发现：识别一个对象，并不意味着理解它与环境之间的关系。\n2.植物与生态互动：\n 植物不是单纯的收集物或消耗型道具。玩家需要观察根系方向、生长范围、形态变化、共生状态与群落分布，从植物本身读取空间和生态信息，并利用这些关系解决环境谜题。\n3.生态实验：\n 面对部分活体生态障碍，玩家需要结合不同植物产生的信号与作用进行实验。例如通过不同生态信号的耦合改变菌丝网络状态，使其主动退让。玩家不是简单“破坏障碍”，而是在理解环境规律后促使其产生响应。\n4.设施操作与环境反馈：\n 部分大型谜题要求玩家结合旧规划图、维护记录和当前植物状态判断设施应该如何运行。操作后，植物、菌丝、设备、声音和空间状态会共同反馈结果，而不是简单弹出“正确 / 错误”。\n5.调查报告与个人手记：\n 玩家的调查同时进入两套记录系统。官方报告记录分类、环境数据、设施状态与资源价值；个人植物手记则记录关系、疑问、研究历史和主角不断变化的理解。随着探索推进，两套系统对同一个世界逐渐形成不同描述。\n\n·通关条件\n玩家需要完成研究所主要区域的探索，取得足够的生态与历史证据，解决阻碍调查路线的关键生态谜题，并完成对核心区域的调查。\n当玩家逐渐理解植物、菌丝、安全区边界与过去研究之间的关系后，将形成最终调查结果。此时，游戏把最初的任务重新交还给玩家：是否将自己的调查发现提交给派遣自己前来的安全区系统？这一选择构成当前 Demo 的最终节点。\n通关的重点并非击败最终敌人或达到某个数值，而是完成一次完整的认知变化：玩家最初作为一名相信调查系统的研究者进入遗迹，最终需要根据自己亲眼看到、亲自验证和重新理解的一切，决定应该如何处理这份知识。\n\n02｜核心玩法循环\n游戏的核心玩法由两个连续的循环构成。\n第一重循环：认识世界\n探索空间\n ↓\n发现异常\n ↓\n观察植物、环境与人工痕迹\n ↓\n形成判断 / 提出疑问\n ↓\n使用植物或研究工具验证\n ↓\n获得新的信息 / 改变环境状态\n ↓\n进入新的区域\n ↓\n重新理解此前发现的线索\n\n玩家进入新的区域后，会首先通过植物生长状态、空间结构、人工设施或异常生态现象发现“不协调之处”。例如，一片本不应稳定生长的植被、一组跨越多个物种的地下根系网络，或者已经突破原有人工培养边界的植物群落。地下观察窗中，多种植物根系甚至呈现出持续连接、且超出现有数据库识别范围的网络结构。\n玩家随后利用识别器、采样设备、历史记录以及自身的植物学观察形成初步判断。工具能够回答“这是什么”“污染程度是多少”“是否符合数据库”，但往往无法解释“为什么它会在这里”“为什么不同生命会产生这种关系”。这种已知信息与现场现象之间的缺口构成持续探索的动力。\n获得线索后，玩家需要进一步利用植物特性、生态信号或环境关系进行验证。谜题的解决并不只是打开一道门，同时也会改变玩家对遗迹的理解。此前看似普通的采样痕迹可能被重新理解为资源收割；被系统判定为“异常”的植物，也可能实际上正在形成一种新的稳定生态。\n因此，每一个局部谜题都遵循一个更深层的循环：\n获得答案 → 发现答案并不完整 → 提出新的问题。\n\n---\n第二重循环：面对世界\n当玩家逐渐完成调查，所有重要事实已经被记录进官方探索报告。\n此时游戏不再询问：“你找到答案了吗？”\n而是询问：“你已知晓全部真相，接下来要如何抉择？”\n玩家最终面对是否提交调查报告的选择。\n这个选择并不决定世界的存亡，也不是简单的“正确 / 错误”道德选择。\n玩家无法拯救这个世界，也无法凭借一次选择决定生态系统和人类社会的未来。\n玩家只是一个调查者。\n她能够决定的，是自己是否将已经获得的知识交回原本派遣自己的系统。\n因此，游戏真正关注的是：一个人在理解世界之后，是否还会以进入这个世界时的方式行动。\n\n---\n03｜亮点玩法一：植物不是道具，而是“探索语言”\n本游戏最核心的玩法创新，是将植物从传统游戏中的装饰、资源或收集品，转变为玩家解读空间的媒介。\n玩家需要观察：\n-  植物在哪里生长； \n-  它向哪里生长； \n-  根系如何延伸； \n-  哪些植物异常旺盛； \n-  哪些植物已经突破人工划定的边界； \n-  哪些植物曾经被采样、切割或移植； \n-  植物与水体、土壤、菌丝以及建筑之间存在怎样的关系。 \n这些信息共同构成一种新的“地图”，让玩家从「找通关物品」转变为「探索生态规律、找寻空间历史」\n最终形成：\n阅读植物 → 推断环境变化 → 验证猜想 → 推进探索\n植物因此同时承担：\n世界观、空间线索、解谜核心与叙事载体。\n\n---\n04｜亮点玩法二：以观察验证解谜，告别提示式答案\n游戏中的谜题建立在观察与验证之上。\n玩家进入一个新的区域后，首先面对的不是明确的任务箭头，而是一个需要解释的异常：\n-  一条无法继续前进的路径； \n-  一片异常生长的植物； \n-  一处失效的设施； \n-  一段颜色特异的根系； \n-  一组无法解释的环境数据。 \n玩家需要先观察环境，再提出自己的判断。\n随后，可以利用：植物知识 + 采样工具 + 识别工具 + 环境信息对判断进行验证。\n例如：\n玩家在废弃廊道墙缝发现成片焰苔，异常集中生长在菌丝大门与根节点周边。\n通过识别、采样工具检测，验证焰苔拥有抑制、驱离菌丝的特殊生态特性。\n结合场地环境与植物知识判断：焰苔只在菌丝活跃区域旺盛生长，二者存在特殊生态制衡关系。\n玩家得出结论：菌丝屏障并非固定障碍，可通过焰苔的特殊生物信号进行干涉、解除封堵，以此打通封闭通路。\n这里不存在单纯的“点击正确物品”。\n玩家真正完成的是：发现现象 → 提出假设 → 找到证据 → 得出结论。\n这也是主角作为植物研究者的核心行动方式。\n\n---\n05｜亮点玩法三：空间本身就是一份历史档案\n游戏不通过连续的剧情演出来告诉玩家“这里曾经发生过什么”，遗迹本身就是历史档案。\n玩家可以从：研究记录、前人手记和书信、实验图纸与报告、植物样本、资源标记、废弃实验设备、温室结构中拼合不同阶段的历史。\n玩家看到的是不同时间留下的痕迹同时存在于同一个空间里，玩家的认知会层层反转，逐渐深入。\n玩家可能第一次认为：“这里曾经进行过正常的植物采样研究。”后来发现：“这里曾经存在相关实验研究。”再后来试图假设：“零散的采样痕迹，是前人有目的、成体系的生态资源收集实验。”\n于是此前看似普通的空间突然获得了新的意义。\n空间不是承载故事的容器，空间本身就是故事。\n\n---\n06｜亮点玩法四：“记录”本身设计为叙事机制\n本作同时设置了官方调查报告与个人植物手记两套记录系统。官方报告记录物种编号、污染数据、设施状态、异常指标与资源价值；个人手记则逐渐记录植物之间的关系、研究者留下的痕迹、无法被数据库解释的现象，以及主角不断发生变化的判断。\n官方系统并不是一个简单的“错误系统”。它可以准确回答“这是什么”“数值是多少”“是否具有利用价值”，却很难回答“为什么它们能够共同存在”“这些知识从哪里来”“什么没有进入正式记录”。\n随着游戏推进，两套系统对于同一个世界逐渐形成不同的描述。最终，当官方系统准备把玩家发现的一切重新整理为可调查、可开发、可利用的信息时，“记录”本身也成为玩家必须重新思考的行为：发现一种生命、知识或历史之后，我们应该如何记录它？而记录它，是否也意味着重新定义甚至占有它？\n\n---\n07｜亮点玩法五：谜题有标准答案，结局无固定选择\n游戏前期解谜拥有客观正确答案，贴合科研严谨性：玩家需要依据完整线索、数据、环境逻辑做出判断，判断正确即可推进流程，错误则无法解锁新内容。\n例如：在温室核心区域，玩家需要根据此前获得的植物分布、环境数据、维护记录与空间信息，判断当前生态系统应该采用哪一种循环方案。\n如果判断错误，系统无法正常运行。\n如果判断正确，生态循环重新建立，玩家得以进入新的区域。\n但解谜的终点不是游戏的终点。前期谜题解决的是「什么是真相」，而最终结局选择解决的是「知晓真相后，我该如何行动」。\n真正的核心抉择，永远在找到答案之后。\n\n---\n08｜亮点玩法六：玩家不是救世主\n本游戏摒弃「玩家拯救世界」的寻常套路，把玩家的选择与“人类命运”解绑。\n最终选择并不会改变世界格局：安全区、人类社会以及生态系统，都不会因玩家的单次选择而覆灭或重生。\n玩家只是一个偶然进入这里的研究者，见证了无人知晓的过往，女性研究者的付出、植物的过往、末日生存必然的功利性，以及自身调查行为与历史的相似性。一处处同构，一处处投射，一处处隐喻，构建起过往与当下，虚构与现实的联系。\n最终选择无关拯救，我们回到个人的语境，我们如何理解这个世界的真相，然后选择如何面对这个世界。\n\n---\n09｜玩家成长：以“认知成长”替代数值成长\n玩家没有等级、战斗力或装备树。真正的成长体现在对世界模型的不断修正。同一个空间会因为后来获得的新证据而产生新的意义。游戏中的核心谜题甚至要求玩家判断：究竟是现实出现了错误，还是过去用于解释现实的模型已经失效。中央温室的循环系统便以此为基础——玩家需要根据环境调查、旧规划图与维护记录判断，当前生态已经突破原有“核心培育”与“标准环形”模型，并选择是否承认正在扩展的新边界\n因此，玩家真正获得的不是一把更强的工具，而是一种新的阅读游戏与真实世界的方式。\n玩家的终极成长：从「看见表面现象」到「读懂底层逻辑」，从「被动完成任务」到「反思自身行为」，掌握全新的认知世界、解读世界的方式。\n\n---\n10｜一句话总结核心玩法\n探索遗迹，阅读植物，验证真相；在完全知晓真相后，决定自己的最终取舍\n我们让玩家通过植物找到答案，却把真正的选择留到了答案之后。', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99389 AND event_id=4;
UPDATE projects SET event_id='4', team_id='294', captain_application_id='5211', topics='["tripo_hergaze"]', sponsor_consents='{"tripo_hergaze": {"rights": "非独占、全球范围、免费", "topic_code": "tripo_hergaze", "sponsor_key": "tripo", "topic_title": "为她而设计 — Her Gaze, Her Game", "consented_at": "2026-08-29T00:28:32+08:00", "consented_ip": "36.112.177.91", "sponsor_label": "Tripo 3D", "sponsor_full_name": "Tripo 3D (Vietnam)", "consented_user_agent": "Mozilla/5.0 (Linux; Android 12; HarmonyOS; CLS-AL30; HMSCore 6.16.2.342; GMSCore 20.12.14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/132.0.6834.79 HuaweiBrowser/17.0.7.302 Mobile Safari/537.36"}}', application_id=NULL, session=NULL, cohort=NULL, team_name='我们称之为队', project_name='我们称之为怪物 The Called', tagline='怪物并不存在，直到我们这样称呼它。', demo_order='220', project_description='项目说明｜报名表版本\n《我们称之为怪物 The Called》是一款以「认知棱镜」为核心的视觉化策略卡牌游戏。日食、月影、疾病与自然异象原本只是客观现象；当人类无法理解它们，便开始赋予它们名字、性格、意图、禁忌与身份——最终，一个怪物诞生了。\n玩家将在意识构成的地图中遭遇不同的「被命名之物」，通过观测、校准、反证与空间部署，在 3×3 棋盘上与其争夺对现实的解释权。每张牌既是一份认知工具，也是一种解释未知的方式。\n项目目前已完成可游玩的网页 Demo，包含关卡地图、三场怪物遭遇、基础卡牌对战、怪物 AI，以及完整的视觉、动画和声音反馈。\n作品以强烈而独特的美术风格、巨型怪物演出与沉浸式声音设计为核心表现，希望让玩家感受到：我们对抗的也许从来不是怪物，而是自己赋予未知的形状。\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 怪物并不存在，直到我们这样称呼它。\n- GitHub 仓库: https://github.com/Strix-OR-Lab/The-Called\n- 游戏玩法说明:\n  《我们称之为怪物 The Called》是一款视觉驱动的空间策略 Deck-building 游戏。\n  你将在意识深处穿行，面对三只诞生于不同文化、天象与集体记忆中的巨型存在。它们并非拥有唯一真相：科学、神话、信仰与传说，都可能成为人类理解它们的方式，也将形成不同的卡牌体系与战斗策略。\n  对局在一块有限的空间棋盘上展开。玩家与怪物轮流打出卡牌，通过占据、覆盖与卡牌之间的联动争夺场面。你需要观察怪物正在形成的叙事，调整自己的解释体系，并在棋盘被填满以前取得优势。\n  \n  操作\n  使用鼠标选择手牌并点击棋盘完成出牌。部分视角与卡牌信息可以通过键盘快捷键切换，怪物会在玩家行动结束后自动进行回合。\n  目标\n  探索意识地图，依次面对三只怪物，并在每场遭遇中建立属于自己的解释。\n  你并非在证明怪物是否真实存在，而是在科学、神话与古老叙事之间作出选择：决定如何观察它、如何称呼它，以及最终让哪一种解释成为人们所相信的现实。\n  \n  通关条件\n  当棋盘被完全占据时，对局结束，并计算双方在场卡牌的总力量。\n  玩家力量高于怪物即可赢得当前遭遇；击败旅途中的全部怪物，便可完成本次游戏流程。若怪物力量更高，则挑战失败；双方力量相同则以平局结束。\n  \n  关键交互\n  游戏的核心在于观察、命名与重构。\n  不同卡牌代表不同的认知方式，它们会因位置、关系与出牌时机产生不同效果。玩家需要在扩张自己的叙事与推翻怪物的叙事之间作出取舍：占据新的空间、覆盖对方的解释，或让已有卡牌彼此呼应。\n  你所打出的不只是一张牌，而是一个关于怪物的判断。\n  而当足够多的判断被放上棋盘——现象便拥有了面孔，传说便拥有了身体，怪物由此诞生。', demo_link='https://the-called.com/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:59:36', is_late='0', created_at='2026-08-30 08:59:36', updated_at='2026-09-01 12:33:42', leader_participant_id=NULL, presentation_link='https://github.com/Strix-OR-Lab/The-Called', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99390/cover.jpg', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93803831d7a_7672d3bfb6b0d028.jpg","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a93803e48b4b_aca2e303a7c4b3a8.jpg","\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a9380494fdd2_7b64b1d2bfd38808.jpg"]', video_link='https://pan.baidu.com/s/14b1aNYDvonCq2Y0wRLs-1A?pwd=x77y', github_repo_url='https://github.com/Strix-OR-Lab/The-Called', bom_link_text=NULL, gameplay_description='《我们称之为怪物 The Called》是一款视觉驱动的空间策略 Deck-building 游戏。\n你将在意识深处穿行，面对三只诞生于不同文化、天象与集体记忆中的巨型存在。它们并非拥有唯一真相：科学、神话、信仰与传说，都可能成为人类理解它们的方式，也将形成不同的卡牌体系与战斗策略。\n对局在一块有限的空间棋盘上展开。玩家与怪物轮流打出卡牌，通过占据、覆盖与卡牌之间的联动争夺场面。你需要观察怪物正在形成的叙事，调整自己的解释体系，并在棋盘被填满以前取得优势。\n\n操作\n使用鼠标选择手牌并点击棋盘完成出牌。部分视角与卡牌信息可以通过键盘快捷键切换，怪物会在玩家行动结束后自动进行回合。\n目标\n探索意识地图，依次面对三只怪物，并在每场遭遇中建立属于自己的解释。\n你并非在证明怪物是否真实存在，而是在科学、神话与古老叙事之间作出选择：决定如何观察它、如何称呼它，以及最终让哪一种解释成为人们所相信的现实。\n\n通关条件\n当棋盘被完全占据时，对局结束，并计算双方在场卡牌的总力量。\n玩家力量高于怪物即可赢得当前遭遇；击败旅途中的全部怪物，便可完成本次游戏流程。若怪物力量更高，则挑战失败；双方力量相同则以平局结束。\n\n关键交互\n游戏的核心在于观察、命名与重构。\n不同卡牌代表不同的认知方式，它们会因位置、关系与出牌时机产生不同效果。玩家需要在扩张自己的叙事与推翻怪物的叙事之间作出取舍：占据新的空间、覆盖对方的解释，或让已有卡牌彼此呼应。\n你所打出的不只是一张牌，而是一个关于怪物的判断。\n而当足够多的判断被放上棋盘——现象便拥有了面孔，传说便拥有了身体，怪物由此诞生。', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99390 AND event_id=4;
UPDATE projects SET event_id='4', team_id='247', captain_application_id='4521', topics='["liberlive_goodday", "bluebox_sleep", "beichen_cloudcomm", "ciie_smartchain"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='ccc', project_name='自驱动猫咪项圈', tagline='让猫咪白天有事可做，一套主动式智能项圈，连接猫咪的健康与全家的睡眠。', demo_order='221', project_description='让猫猫可以自己的去运动，然后消耗他的精力，让他可以保持健康，并且猫猫的精力白天适当消耗之后，晚上不折腾，主人睡得也好，是通过检测猫咪的静态还是动态的一个状态，来向附近的玩具发出指令，让这些玩具动起来，吸引猫咪去追逐玩闹的天性，这些玩具可以发出各种各样的动物声音（鸡叫、狗叫、老鼠叫、发情的母猫叫、找妈妈的幼猫叫、还有很多很多....），来勾起猫咪的好奇心。本质上来讲，就是模拟丛林环境，激活狩猎天性\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 让猫咪白天有事可做，一套主动式智能项圈，连接猫咪的健康与全家的睡眠。\n- GitHub 仓库: http://www.github.com\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a938046c3957_7fc66274d5d5338f.png)', demo_link='http://www.github.com', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 08:59:40', is_late='0', created_at='2026-08-30 08:59:40', updated_at='2026-09-01 12:33:44', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99391/cover.png', screenshot_urls=NULL, video_link='http://www.github.com', github_repo_url='http://www.github.com', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99391 AND event_id=4;
UPDATE projects SET event_id='4', team_id='301', captain_application_id='5163', topics=NULL, sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='她能飞', project_name='先改哪一处｜托福写作AI coach', tagline='人一次只能救一个火', demo_order='222', project_description='每个人都懂这种感觉：问题一下涌过来——作文红叉、工作待办、生活失控——你不可能全都顾，只能先改最要命的那一个。学生拿到作文批改也是这样：时态、逻辑、连接词、例子全被指出来，却更不知道从哪开始。真正卡住他们的不是反馈太少，而是顺序错了：地基还松着，就开始装修，越改越乱。\n作文导航不做“再多挑几个错”，而是像医生开处方：读这篇作文和历史记录，按分数影响、常犯程度、是不是地基、离考试还有多久，选出当下唯一该改的一处，并配一个 10 分钟小练习。练完再测一次，系统判断是继续、过关，还是换一道题看会不会。\n作文导航不做“再多挑几个错”，而是像教练开处方：读这篇作文和历史记录，按分数影响、常犯程度、是不是地基、离考试还有多久，选出今天唯一该改的一处，并配一个 10 分钟小练习。练完再测一次，系统判断是继续、过关，还是换一道题看会不会。\n这套排序方法不是凭空训练出来的：来自我 10 年一线教学，累计带过近千名学生、批改上万篇作文。过去靠我人工告诉学生“先改哪一处”；现在把能复用的经验蒸馏进系统，让 AI 先做初筛，老师最后拍板。本次 Demo 验证的是蒸馏后的系统能否开始复现这套判断：2 名自学的学生 4 周写作从 2.5→4、4.5→5；下一步扩大样本，验证不同老师和不同基础学生下的稳定性。\n---\nG001 软件 赛道附加材料\n\n- Slogan: 人一次只能救一个火\n- GitHub 仓库: https://github.com/1064800242-creator/stephantech.github.io', demo_link='https://pan.baidu.com/s/1xIqDMHlGnqoEaUHeOXhxGA?pwd=1234', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 09:08:54', is_late='0', created_at='2026-08-30 09:08:54', updated_at='2026-09-01 12:33:46', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99392/cover.png', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1xIqDMHlGnqoEaUHeOXhxGA?pwd=1234', github_repo_url='https://github.com/1064800242-creator/stephantech.github.io', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99392 AND event_id=4;
UPDATE projects SET event_id='4', team_id='68', captain_application_id='3236', topics='["liberlive_goodday"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='偷睡漏睡，不如早睡', project_name='一盏会呼吸的床头灯', tagline='一盏会呼吸的床头灯，陪你把今天慢慢收尾', demo_order='223', project_description='睡前刷手机停不下来，不是自律问题--是所有工具都在逼你"立刻停下"。晚风灯换了一种方式:它是一盏ESP32智能床头灯，内置8种灯光状态，与手机端的AI陪伴助手"晚屿"联动。睡前，AI和你聊两句，生成一个最多3步的今晚计划;确认后，晚风灯用光替你记住它--亮暖光表示就绪，低亮呼吸表示守护，轻抬亮是温柔提醒，缓缓熄灭是道晚安。提醒到了不锁屏，而是给你四个选择:再陪10分钟、换个方式放松、准备收尾、今晚别再提醒。灯上还有实体按钮，不碰手机也能延长。软硬件一体，把"该睡了"变成"可以睡了"。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 一盏会呼吸的床头灯，陪你把今天慢慢收尾\n- GitHub 仓库: https://github.com/plx3218/wanyu-night-lamp\n- BOM / 原理图:\n  - https://github.com/plx3218/wanyu-night-lamp/blob/main/docs/BOM.md', demo_link='https://www.bilibili.com/video/BV1Vy8r6JE9z/?spm_id_from=333.1007.tianma.1-1-1.click', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 09:13:03', is_late='0', created_at='2026-08-30 09:13:03', updated_at='2026-09-01 12:33:48', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99393/cover.png', screenshot_urls=NULL, video_link='https://www.bilibili.com/video/BV1Vy8r6JE9z/?spm_id_from=333.1007.tianma.1-1-1.click', github_repo_url='https://github.com/plx3218/wanyu-night-lamp', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99393 AND event_id=4;
UPDATE projects SET event_id='4', team_id='240', captain_application_id='4761', topics='["zhiyuan_herrobot", "miaoda_super", "liberlive_goodday", "qingxian_self", "zeroth_linku", "insta360_hervision", "beichen_cloudcomm", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='伊宝电子手办超级旗舰IP战队', project_name='伊宝-电子手办', tagline='基于esp32开发板的电子智能手办，控制电脑、情感陪护、身体个性化定制一站式智能手办IP', demo_order='224', project_description='伊宝（YiBao）项目文档\n一句话定位：伊宝不是一个只配在桌上看的精致手办，而是一个"能陪你、也能帮你"的电子手办 IP——接上电池就能独立工作，连上家里 Wi‑Fi 就能用自然语言控制你的 Mac/Windows，也能和云端或局域网大模型聊天。我们让手办走向智能，从"摆件"变成"桌面伙伴 + 生产力终端"。\n\n项目代号：YiBao　｜　文档版本：项目文档 V1　｜　基础依据：产品开发文档 V4（2026-08-27）\n\n一、项目背景\n1.1 我们要解决什么\n潮玩、手办市场越来越大，但大多数手办仍然是"死物"——买回家摆着，好看，却不能互动。与此同时，语音助手和陪伴型 AI 大量出现，但它们要么只能闲聊、播内容，要么被绑定在手机/音箱里，离"我的电脑"很远。\n\n我们注意到两个明显的断层：\n\n手办只会"看"，不会"动"：用户为形象和情感付费，却得不到任何实际能力。\n语音助手只会"说"，很难"做"：想用语音打开一个应用、调一下音量、切一下窗口，传统助手要么听不懂，要么把控制请求当成了聊天，链路慢且不稳定。\n1.2 我们的答案：电子手办 IP\n伊宝把"手办的情感价值"和"语音控制电脑的实用价值"合二为一：\n\n感情陪护：伊宝有形象、有语气、有陪伴感，是桌面上真正"在"的伙伴，而不只是另一个音箱。\n智能控制：伊宝能听懂自然语言，去操作你的电脑——开应用、管窗口、调音量、切设备。\n走向智能：它背后是可切换的云端/本地大模型，能对话、能执行、能离线，越用越聪明。\n1.3 与传统方案的区别\n维度\t传统手办\t普通语音助手\t伊宝 YiBao\n情感陪伴\t静态摆件\t无形象/弱陪伴\t有形象、有语气、可互动\n控制电脑\t不支持\t能力弱、依赖封闭生态\t跨 Mac/Windows 自然语言控制\n离线可用\t—\t多依赖云端\t支持局域网本地模型\n安全边界\t—\t模型易直接触达系统\t本地安全策略，模型不直接操电脑\n形态\t纯装饰\t音箱/手机\t桌面电子手办，电池无线\n二、目标用户\n2.1 个人用户（办公 / 学习 / 日常创作）\n使用 Mac 或 Windows，希望用语音快速打开应用、管理窗口、输入文字、调节系统设置。\n双手忙碌时（做饭、整理、抱娃）也能"动口不动手"地操作电脑。\n在自己家 Wi‑Fi 中使用，设备只控制自己的电脑。\n2.2 开发者与内容创作者\n编程时用语音打开 IDE、切换窗口、执行受控工作流。\n录课、直播、会议中不方便频繁碰键盘鼠标。\n有多台 Mac/Windows，需要语音快速切换控制目标。\n2.3 隐私与离线用户\n希望语音和模型服务运行在自己的电脑、NAS 或局域网服务器内。\n公网不可用时，仍需要基本语音对话和电脑控制。\n2.4 潮玩 / 陪伴向用户（IP 核心人群）\n喜欢手办、潮玩，愿意为"有灵魂的桌面伙伴"付费。\n独居、异地、需要轻量情感陪伴的人群。\n看重"我的手办是独一无二的、能和我互动的"这一差异化体验。\n三、技术栈\n3.1 硬件终端（电子手办本体）\n主控：ESP32-S3-BOX3（带屏幕、麦克风、扬声器、电池焊盘）\n系统：ESP-IDF / FreeRTOS\n音频：ESP-SR（AFE/AEC/NS/VAD/WakeNet）、libopus（Opus 编解码）\n连接：Wi‑Fi（主链路）、USB（TinyUSB，备用链路与供电）\n能力：麦克风拾音、按键说话/语音唤醒、LCD 状态显示、电池/电量管理\n说明：ESP32-S3 本身不能运行通用大模型；离线智能运行在用户的电脑 / NAS / 局域网服务器上。\n\n3.2 本地客户端（装在用户电脑上）\n网关：FastAPI / Pydantic，负责 ASR/LLM/TTS 调度、会话管理与安全策略\n控制 Agent：调用 Mac（NSWorkspace / CoreAudio / Accessibility）与 Windows（UIAutomation / Core Audio COM / User32）系统接口执行已授权动作\n存储：SQLite（单机配置）/ PostgreSQL（正式数据）\n消息：Mosquitto MQTT Broker（控制消息 QoS 1）+ UDP（实时 Opus 音频）\n3.3 模型服务（云 / 本地 / 混合）\nASR：云端流式 ASR；本地 FunASR / faster-whisper\nLLM：OpenAI-compatible 云服务（DeepSeek、智谱等）；本地 Ollama / vLLM\nTTS：云端 TTS；本地 Piper\n切换：云端不可用时自动切本地 Provider，恢复后按策略决定是否切回\n3.4 管理网站与前端\n首版：FastAPI 提供 API + 静态页面（原生 HTML/CSS/JS）\n后期：Vue 3 + TypeScript 完整 UI（复用同一套 API）\n实时状态：WebSocket 推送在线 / 执行状态\n安全：API Key 不回显、Host/Origin 校验、CSRF 防护、本地登录令牌\n3.5 安全与通信底座（自研核心）\n消息签名、过期、幂等、重放防护\n动作白名单、参数校验、风险等级、二次确认\n设备—网关、Agent—网关独立配对，用户/设备/电脑授权关系由网关持有\n四、创新点\n4.1 电子手办 IP × 电脑控制（核心差异）\n把"手办的情感价值"和"语音控制电脑的实用价值"首次合体：用户买的是一个有陪伴感的桌面伙伴，顺带获得一个能真正操作电脑的生产力终端。不是"音箱加屏幕"，而是"会帮你的手办"。\n\n4.2 感情陪护 + 实用控制双轮驱动\n伊宝既做"解释一下 MQTT"这类对话陪伴，也做"打开微信""把办公室电脑音量调到 30%"这类实际控制。控制优先分流机制自动判断意图：操作类请求走电脑控制快路径，闲聊类走 AI 对话，避免把控制误当聊天、也避免把闲聊误发成电脑动作。\n\n4.3 本地安全执行，模型不直接碰电脑\n大模型只负责"理解和提出结构化动作提案"；真正的权限检查、动作白名单、参数校验、系统调用全部在用户自己的电脑里完成。即使云端模型被攻破，也无法越权操作用户电脑。高危动作（截图、静音、剪贴板等）还需限时二次确认。\n\n4.4 云端 / 本地 / 离线三重模型模式\n有网用云模型（更强），无公网切局域网本地模型（Ollama/FunASR/Piper 等），断网仍能对话和控制。隐私敏感用户可完全禁止公网 Provider。\n\n4.5 用户隔离与隐私保护\n每台设备、每台电脑、每个用户密钥独立；伪造 host_id 无法跨用户控制；默认不长期保存原始语音；日志不记录 API Key 与敏感内容。\n\n4.6 电池无线 + Wi‑Fi/USB 双链路\n接锂电池即可脱离电脑独立工作，仅通过 Wi‑Fi 控制电脑；Wi‑Fi 故障时可切 USB 备用链路，且切换过程不产生重复电脑动作。\n\n五、团队分工（建议模板，按实际成员填写）\n以下为基于技术栈给出的参考分工模板，请替换为真实姓名 / 角色。黑客松团队常见 3–5 人，可一人兼多责。\n\n角色\t核心职责\t对应技术板块\n嵌入式 / 固件\tBOX3 固件、本板 BSP、音频前端（VAD/降噪）、Wi‑Fi 配网与安全配对、电池/低功耗\tESP-IDF、ESP-SR、libopus、TinyUSB\n客户端 / 后端\t本地网关、FastAPI 服务、Mac/Windows 控制 Agent、安全策略与确认服务\tFastAPI、SQLite、Mosquitto、系统自动化接口\nAI / 模型\tASR/LLM/TTS 集成、Provider 抽象、云/本地切换、意图分流\tDeepSeek/智谱、Ollama/vLLM、FunASR、Piper\n前端 / 产品 / IP\t管理网站、交互与形象设计、电子手办 IP 人设与陪伴体验\tHTML/JS、Vue3（后期）、IP 视觉与文案\n测试 / 质量（可兼任）\t安全验收、性能 Trace、核心场景演练（A–H）\t签名/幂等/确认、P95 时延、续航实测\n协作要点：硬件与安全底座（P0）先行冻结；控制闭环（P1 Mac）优先跑通再扩展 Windows 与多电脑；所有控制动作共用同一套 Policy/确认/校验管线，网站触发的测试动作与语音动作走完全相同的安全链路。\n\n六、开发过程\n按"先安全底座、再单平台闭环、后多平台与离线"的渐进路线推进，分六个阶段：\n\nP0 · 硬件和安全底座\n实机确认主控、Flash、PSRAM、麦克风、引脚；建立本板 BSP（屏幕/按键/音频/Wi‑Fi/电池/USB）。\n完善消息 Schema、签名、过期、幂等、统一错误码。\n冻结 SoftAP 配网、安全配对、设备—主机授权模型。\n完成条件：硬件独立测试通过、板级配置冻结、安全领域测试通过。\nP1 · 电池 Wi‑Fi + Mac 闭环 + 简易网站\nBOX3 电池供电、Wi‑Fi 配网、按键说话；本地客户端 + 简单管理网站 + 设备配对。\n云端模型对话；Mac 打开应用 / 音量 / 窗口控制；TTS/LCD 反馈与 Trace。\n完成条件：BOX3 不接 USB，经 Wi‑Fi 控制 Mac 并完成 AI 对话。\nP2 · Windows 与多电脑\nWindows Agent 与权限引导；多电脑注册、当前电脑切换、显式目标控制。\nMac/Windows 统一中立动作协议（Windows 11 为正式基线）。\n完成条件：一台 BOX3 安全切换并控制一台 Mac 与一台 Windows。\nP3 · 本地模型与离线闭环\n本地 ASR/LLM/TTS Provider；云/本地健康检查与切换；CPU/内存/GPU 指标与过载降级。\n完成跨系统/硬件档位的模型兼容矩阵、许可证与最低资源要求。\n完成条件：断开公网后仍可对话并控制电脑。\nP4 · 低功耗与双链路\n电池曲线、背光、休眠、续航优化；USB 传输原型与 Mac/Windows 兼容测试。\nWi‑Fi/USB 主备仲裁、缓存与去重。\n完成条件：达到实测续航目标，链路切换不产生重复电脑动作。\nP5 · 产品化后台和发布\nVue 3 + TypeScript 完整 UI；安装包、开机启动、升级、日志导出与诊断。\nPostgreSQL、审计、告警、备份、SBOM 与第三方许可证；固件签名 OTA、A/B 回滚、安全启动。\n完成条件：安装、升级、72 小时稳定性与安全验收通过。\n七、后续计划\n7.1 工程侧（近期）\n低功耗与 USB 双链路实测：把"待机/拾音/播放/重连功耗、实际续航"从目标变成实测数据；USB 主备切换完成跨平台验证后再对外承诺。\n完整前端与发布：Vue 3 + TypeScript UI、一键安装包、固件 OTA 与安全启动。\n模型兼容矩阵与许可合规：逐平台验证 ASR/LLM/TTS，明确许可证（如 Piper GPL-3.0 决策）、校验和与最低资源。\n7.2 产品 / IP 侧（中期，差异化重点）\n深化感情陪护：为伊宝建立稳定人设、记忆与多轮上下文，从"能对话"走向"懂你"的陪伴。\n电子手办 IP 化：形象设计、表情/语气、可换装与周边，构建可识别、可运营的 IP。\n社区与生态：用户自定义动作、语音包、手办性格，形成 UGC 与共创氛围。\n7.3 商业 / 生态侧（长期）\n面向办公、直播、无障碍（行动不便人群语音控电脑）等场景的垂直方案。\n隐私优先的本地智能定位，作为"不想把数据上云"人群的首选桌面终端。\n从单一手办扩展到"手办家族"，多设备协同、多角色分工的桌面智能生态。\n附：核心验收场景\nA 用户隔离：用户 A/B 各自配网，伪造 host_id 不能跨用户控制。\nB 电池无线：BOX3 只接电池，同 Wi‑Fi 完成打开应用/调音量/窗口控制。\nC 多电脑：一台 BOX3 配对 Mac+Windows，"切到 Windows"只发 Windows。\nD 公网断开：自动切本地模型，仍完成一次对话 + 一次控制。\nE 安全拒绝：模型生成任意命令/越界参数，网关与 Agent 均拒绝，无副作用。\nF 重复与断线：同一 msg_id 重发 100 次只执行一次；断线不盲目重试。\nG 链路切换：Wi‑Fi 故障切 USB 恢复会话，电脑动作不重复。\nH 低功耗：空闲降背光与功耗，低电量触发保护策略。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 基于esp32开发板的电子智能手办，控制电脑、情感陪护、身体个性化定制一站式智能手办IP\n- GitHub 仓库: https://github.com/1660536805-spec/yibao\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a937881b4e2a_38f6391d69dd06f3.png)\n  - ![BOM 图](/platform/uploads/images/2026/08/6a937886c2544_21252759ab552a7b.png)\n  - ![BOM 图](/platform/uploads/images/2026/08/6a9378a59248a_2117882844dfcb47.png)\n  - ![BOM 图](/platform/uploads/images/2026/08/6a9383b252254_07b96090279ba358.jpg)', demo_link='https://1660536805-spec.github.io/yibao-website/', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 09:15:44', is_late='0', created_at='2026-08-30 09:15:44', updated_at='2026-09-01 12:04:37', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99394/cover.png', screenshot_urls=NULL, video_link='https://3a773b9bb4534541ba29156c69b81a00.app.workbuddy.link', github_repo_url='https://github.com/1660536805-spec/yibao', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='standard', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99394 AND event_id=4;
UPDATE projects SET event_id='4', team_id='203', captain_application_id='5155', topics='["miaoda_super", "liberlive_goodday", "proya_feelings", "qingxian_self", "bluebox_sleep", "eazo_4her", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='Soft Core', project_name='息', tagline='身体，不止一种写法。', demo_order='225', project_description='一句话总结，我想解决的是：身体感觉长期被预设模式替代，用户只能选择，而不能创作的问题。\n\n“息”是一套让女性自己创作、体验并改写身体感觉的软硬件系统。现有身体交互产品通常只让用户选择位置、强度和预设节奏；息让用户画下一段动作，将路径、方向、速度、停顿和压力记录为可编辑的 Touch Score。\n\n同一份 Touch Score 可以成为视觉、声音等艺术作品被分享，也可以发送到 ESP32 实体输出端进行空间回放，让其他人以另一种形式观看和体验。当前已完成 Make—Feel—Name—Rewrite 网页闭环，以及 ESP32、8 灯4区和压力输入的低保真实体呈现链路。\n\n未来，图像、音乐、环境与日常瞬间都可以成为感官创作的素材。系统只提出可修改的转译草稿，意义始终由体验者命名、删除或改写。息想做的不是替身体提供答案，而是让每个身体拥有自己的写法。\n---\nG001 硬件 赛道附加材料\n\n- Slogan: 身体，不止一种写法。\n- GitHub 仓库: https://github.com/YoshuaYang/xi-touch-score\n- BOM / 原理图:\n  - ![BOM 图](/platform/uploads/images/2026/08/6a93805cc7cfa_1fa932d84fc39e2d.jpg)', demo_link='https://soft-core-touch.yoshuayashuyang.chatgpt.site', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 09:25:57', is_late='0', created_at='2026-08-30 09:25:57', updated_at='2026-09-01 12:04:34', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99395/cover.png', screenshot_urls=NULL, video_link='https://soft-core-touch.yoshuayashuyang.chatgpt.site', github_repo_url='https://github.com/YoshuaYang/xi-touch-score', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:29:03', review_notes='', track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99395 AND event_id=4;
UPDATE projects SET event_id='4', team_id='211', captain_application_id='4909', topics='["ant_mulan_ai"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='等灯', project_name='等灯dengdeng', tagline='等灯 dengdeng～ 欢迎来玩！ 在这里，每个人心中都有一盏小灯。它可以照见自己，也可以照亮他人。有人为自己提灯，勇敢探索；也有人为彼此持灯，带来陪伴、温暖与方向。 “The lamps are different, but the light is the same.”——Rumi 一盏灯在家乡，一盏灯在远方，光同样照耀着你。  掷出骰子，向前出发；看见不对劲的事，勇敢说出来；看见需要帮助的人，也为他留一盏灯。', demo_order='226', project_description='等灯 dengdeng～ 欢迎来玩！\n在这里，每个人心中都有一盏小灯。它可以照见自己，也可以照亮他人。有人为自己提灯，勇敢探索；也有人为彼此持灯，带来陪伴、温暖与方向。\n“The lamps are different, but the light is the same.”——Rumi\n一盏灯在家乡，一盏灯在远方，光同样照耀着你。\n\n掷出骰子，向前出发；看见不对劲的事，勇敢说出来；看见需要帮助的人，也为他留一盏灯。\n---\nG001 游戏 赛道附加材料\n\n- Slogan: 等灯 dengdeng～ 欢迎来玩！ 在这里，每个人心中都有一盏小灯。它可以照见自己，也可以照亮他人。有人为自己提灯，勇敢探索；也有人为彼此持灯，带来陪伴、温暖与方向。 “The lamps are different, but the light is the same.”——Rumi 一盏灯在家乡，一盏灯在远方，光同样照耀着你。  掷出骰子，向前出发；看见不对劲的事，勇敢说出来；看见需要帮助的人，也为他留一盏灯。\n- GitHub 仓库: https://github.com/CyberDoctor2023/dengdeng\n- 游戏玩法说明:\n  地图\n  《等灯 dengdeng》的地图由六个生活场景组成：\n  - 家 Home：起点，每位玩家出发的地方。  \n  - 教室 Classroom：灯管照亮学习与同伴相处。  \n  - 操场 Playground：路灯照亮游戏与安全边界。  \n  - 田野 Field：月亮照亮安静的心事与陪伴。  \n  - 办公室 Office：台灯照亮求助、倾听与解决。  \n  - 小卖铺 Village Shop：灯泡照亮分享、物品与尊重；这里是折返终点，玩家到达后开启回程。\n  六个场景之间以路径连接，每段路径设有 6 个棋格，其中3个格子是功能格，分别对应于1个问号？黄色格：抽取问题卡牌；1个三角形蓝色格：抽取互动卡牌；1个圆形红色格：抽取 dengdeng 卡；以及另外2个流浪猫/狗格，善待小动物，到达即可直接+1流明（游戏分值单位为流明）\n  \n  收集更多流明，不只是为了前进，也是在一次次选择中，让自己的灯更亮。\n  \n  \n  \n  \n  人物卡\n  这是同学们在游戏开始前需要抽到的角色卡牌。每个角色对应一个地点有不同的功能。\n  【静静】-纪律委员：如果玩家刚好到达教室地点，所有人安静，静静可以再掷一次骰子\n  【跳跳姐姐】-体育老师：如果玩家刚好到达操场地点，可以多抽取一张互动卡获得流明\n  【稻草人】-田间守望者：如果玩家刚好到达田野地点，可以直接帮助接下来第一位抽到黑色dengdeng卡的玩家抵消手里的黑卡并获得相应的流明数值\n  【好好老师】-班主任：如果玩家刚好到达办公室地点，可以多抽取一张问题卡获得流明\n  【糖果叔叔】-小卖铺老板：如果玩家刚好到达小卖铺地点，回程可以任意步数+1或者+2\n  【留灯人】-家人：从Home出发即可在夜灯区选择任意点位继续游戏，单程有效，回程无效（夜灯区为家、教室和操场三条路径形成的区域）\n  \n  功能卡\n  整个游戏包含3种功能卡牌：问题卡牌、互动卡牌、dengdeng卡牌\n  - 问题卡牌（20张）包含关于校园预防欺凌和霸凌的单选题以及多选题。对应的分数不相同，如果玩家回答正确。他们就能获得对应分数的流明。\n  - 互动卡牌（20张）包含20个不同的互动游戏，赢得游戏或者完成任务的人可以获得一颗心。（在办公室滞留的玩家不得参与游戏）\n  - dengdeng卡牌\n  黑色dengdeng卡牌（20张）：是扣除流明的卡片，内容为不友善、欺凌或危险行为，对应 -1 至 -5 分。粉色dengdeng卡牌（20张）：是获得流明的卡片，内容为友善、陪伴和求助行为，对应 +1 至 +5 分。\n  当有玩家抽到黑色 dengdeng 卡时，其他玩家可以打出任意1张粉色 dengdeng 卡帮助抵消，可以多位玩家一起帮助，但每人只能出一张。打出粉卡的玩家同时获得粉卡对应的流明分数。如果没有人打出粉卡，抽到黑卡的玩家扣除对应流明，并进入办公室停止一轮游戏，下一轮从办公室重新出发继续游戏。\n  所有dengdeng卡使用完后归回原处，粉色 dengdeng 卡只有在黑卡出现时才能使用，游戏结束时，未使用的粉卡不计分。\n  \n  流明卡\n  流明卡等于游戏的分数，它们对应三种不同的分数，被玩家用作分数筹码。每个玩家最初有10个流明。游戏结束时谁的分数最高谁就获胜。（包含50张1流明、30张5流明、20张10流明）', demo_link='https://cyberdoctor.me/dengdeng', xiaohongshu_link='', xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 09:29:02', is_late='0', created_at='2026-08-30 09:29:02', updated_at='2026-09-01 12:04:33', leader_participant_id=NULL, presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99396/cover.jpg', screenshot_urls='["\\\\/platform\\\\/uploads\\\\/images\\\\/2026\\\\/08\\\\/6a938728aabae_6c731e7b996b7107.jpg"]', video_link='https://cyberdoctor.me/dengdeng', github_repo_url='https://github.com/CyberDoctor2023/dengdeng', bom_link_text=NULL, gameplay_description='地图\n《等灯 dengdeng》的地图由六个生活场景组成：\n- 家 Home：起点，每位玩家出发的地方。  \n- 教室 Classroom：灯管照亮学习与同伴相处。  \n- 操场 Playground：路灯照亮游戏与安全边界。  \n- 田野 Field：月亮照亮安静的心事与陪伴。  \n- 办公室 Office：台灯照亮求助、倾听与解决。  \n- 小卖铺 Village Shop：灯泡照亮分享、物品与尊重；这里是折返终点，玩家到达后开启回程。\n六个场景之间以路径连接，每段路径设有 6 个棋格，其中3个格子是功能格，分别对应于1个问号？黄色格：抽取问题卡牌；1个三角形蓝色格：抽取互动卡牌；1个圆形红色格：抽取 dengdeng 卡；以及另外2个流浪猫/狗格，善待小动物，到达即可直接+1流明（游戏分值单位为流明）\n\n收集更多流明，不只是为了前进，也是在一次次选择中，让自己的灯更亮。\n\n\n\n\n人物卡\n这是同学们在游戏开始前需要抽到的角色卡牌。每个角色对应一个地点有不同的功能。\n【静静】-纪律委员：如果玩家刚好到达教室地点，所有人安静，静静可以再掷一次骰子\n【跳跳姐姐】-体育老师：如果玩家刚好到达操场地点，可以多抽取一张互动卡获得流明\n【稻草人】-田间守望者：如果玩家刚好到达田野地点，可以直接帮助接下来第一位抽到黑色dengdeng卡的玩家抵消手里的黑卡并获得相应的流明数值\n【好好老师】-班主任：如果玩家刚好到达办公室地点，可以多抽取一张问题卡获得流明\n【糖果叔叔】-小卖铺老板：如果玩家刚好到达小卖铺地点，回程可以任意步数+1或者+2\n【留灯人】-家人：从Home出发即可在夜灯区选择任意点位继续游戏，单程有效，回程无效（夜灯区为家、教室和操场三条路径形成的区域）\n\n功能卡\n整个游戏包含3种功能卡牌：问题卡牌、互动卡牌、dengdeng卡牌\n- 问题卡牌（20张）包含关于校园预防欺凌和霸凌的单选题以及多选题。对应的分数不相同，如果玩家回答正确。他们就能获得对应分数的流明。\n- 互动卡牌（20张）包含20个不同的互动游戏，赢得游戏或者完成任务的人可以获得一颗心。（在办公室滞留的玩家不得参与游戏）\n- dengdeng卡牌\n黑色dengdeng卡牌（20张）：是扣除流明的卡片，内容为不友善、欺凌或危险行为，对应 -1 至 -5 分。粉色dengdeng卡牌（20张）：是获得流明的卡片，内容为友善、陪伴和求助行为，对应 +1 至 +5 分。\n当有玩家抽到黑色 dengdeng 卡时，其他玩家可以打出任意1张粉色 dengdeng 卡帮助抵消，可以多位玩家一起帮助，但每人只能出一张。打出粉卡的玩家同时获得粉卡对应的流明分数。如果没有人打出粉卡，抽到黑卡的玩家扣除对应流明，并进入办公室停止一轮游戏，下一轮从办公室重新出发继续游戏。\n所有dengdeng卡使用完后归回原处，粉色 dengdeng 卡只有在黑卡出现时才能使用，游戏结束时，未使用的粉卡不计分。\n\n流明卡\n流明卡等于游戏的分数，它们对应三种不同的分数，被玩家用作分数筹码。每个玩家最初有10个流明。游戏结束时谁的分数最高谁就获胜。（包含50张1流明、30张5流明、20张10流明）', aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='159', reviewed_at='2026-08-30 09:36:15', review_notes='', track_code='游戏', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99396 AND event_id=4;
UPDATE projects SET event_id='4', team_id='214', captain_application_id='3208', topics='["miaoda_super", "liberlive_goodday", "sensetime_xiaohuang", "qingxian_self", "eazo_4her", "ant_mulan_ai"]', sponsor_consents='{"sensetime_xiaohuang": {"rights": "非独占、全球范围、免费", "topic_code": "sensetime_xiaohuang", "sponsor_key": "sensetime", "topic_title": "AI，不止完成一步", "consented_at": "2026-08-28T18:50:22+08:00", "consented_ip": "114.246.236.138", "sponsor_label": "商汤 (SenseTime)", "sponsor_full_name": "商汤科技 / SenseTime", "consented_user_agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/152.0.0.0 Safari/537.36"}}', application_id=NULL, session=NULL, cohort=NULL, team_name='你俩 AI 聊吧', project_name='等号', tagline='少一点消耗，多一个等号。', demo_order=NULL, project_description='1｜问题\n企业已经大量使用 AI 客服降低自身客服劳动，但复杂售后没有被第一层智能客服解决时，找入口、重复描述、等待、追人工、理解新回复、补材料和判断下一步等劳动仍由消费者承担。\n\n2｜方案\n「等号」是一款 Android 端消费者侧客服托管 AI Agent。用户说清问题并完成 Case 级授权后，Agent 持续读取平台新回复、维护事实与证据、判断当前进展并动态调整策略；只有需要真实证据、身份操作或接受/拒绝赔偿、退款等关键决定时才把用户叫回来，完成后继续推进。最终要么在原平台解决问题，要么在合理平台路径穷尽后整理出可用于后续维权行动的证据包。\n\n3｜现场完成内容 / 完成度\n本次黑客松完成了 Android 本地产品壳与核心 Case 状态逻辑、跨 App 手势执行、截图、输入等移动执行底座，以及 Case 级授权、Need User → Resume、结果与还权等核心流程，并完成最终交互原型。核心机制已经跑通美团平台真实案例验证：在 1 个真实美团售后 Case 中，用户只在补充真实材料和作关键决定时介入，Agent 随后继续推进并取得实际平台业务结果。当前真实平台证据为 n=1，不宣称多 Case、多平台或生产级稳定性已经完成。\n\n4｜下一步发展规划\n下一步将完成消费者 App 一体化工程，扩展更多真实 Case 与消费平台；完善后台等待与恢复机制；将开发期 Windows DEV Proxy 迁移为可部署的 Backend / Model Gateway；继续强化 Case Memory、策略切换、RoleSafety、执行前后 Verify、隐私与权限管理，并通过真实用户验证授权意愿、长期使用和付费意愿。\n\n', demo_link='https://github.com/crave93/shenicest-consumer-advocate', xiaohongshu_link=NULL, xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 10:12:45', is_late='1', created_at='2026-08-30 10:12:45', updated_at='2026-09-01 12:14:21', leader_participant_id='3208', presentation_link='https://docs.google.com/document/d/17lAeWIGvTveaIXSr2gc8ScE6zjIJELGpHpnDXoOD9cA/edit', presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='/platform/logo-shenicest-square.webp', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1c1WXf9kFExWar9BT6ky8DQ?pwd=799q', github_repo_url='https://github.com/crave93/shenicest-consumer-advocate', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='160', reviewed_at='2026-08-30 11:24:22', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99397 AND event_id=4;
UPDATE projects SET event_id='4', team_id='295', captain_application_id='5345', topics='["ant_mulan_ai", "zhiyuan_herrobot"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='喜欢去瑞幸coding', project_name='We Remember', tagline='We Remember', demo_order=NULL, project_description='《都记得》是一款面向家庭协作与照护场景的 AI Agent。它解决的不是"家人容易忘事"，而是许多家庭中总由同一个人负责发现问题、记时间、做安排、提醒和兜底，具体任务虽已分出，隐形责任却没有真正转移。\n\n用户只需用自然语言告诉 Agent"什么时候、做什么、谁参与、谁负责、何时提醒"，系统即可生成确认卡，写入家庭时间表，并将事件、待办归入责任域。责任交接需双方确认；接手后，负责人和后续提醒同步迁移，原负责人退出默认催办链。私密表达默认仅本人可见，分享前会再次征求同意。\n\n现场已完成 Agent 对话、事件抽取、确认卡、家庭时间表、成员通知管理和同步反馈，并完成责任域与交接流程设计。使用时创建家庭空间、邀请成员，直接输入或说出安排，确认后同步；长期事项可发起责任交接，由接手人确认后生效。\n\n', demo_link='https://family.davidwang.space', xiaohongshu_link=NULL, xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 10:18:35', is_late='1', created_at='2026-08-30 10:18:35', updated_at='2026-09-01 12:14:21', leader_participant_id='5345', presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99398/cover.png', screenshot_urls=NULL, video_link='https://www.bilibili.com/video/BV14y4U6DEE7/', github_repo_url='https://github.com/songconmaisaix31-design/New-gethe-point', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='160', reviewed_at='2026-08-30 11:24:03', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99398 AND event_id=4;
UPDATE projects SET event_id='4', team_id='219', captain_application_id='5519', topics='["sappho_love", "liberlive_goodday"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='四个岛民', project_name='共屿 co-island', tagline='让每一段关系，都有一座属于它的岛。', demo_order=NULL, project_description='共屿 co-island 是一款以"关系共同创造"为核心的亲密关系互动应用。我们希望解决的是如何让两个人之间那些难以表达、容易被遗忘，却真正构成一段关系的情绪、暗号与共同经历，被保存下来，并逐渐形成属于彼此的独特关系文化。\n\n在共屿中，每一段关系都会对应一座由两个人共同拥有的数字岛屿。用户可以邀请另一位重要的人进入同一座岛，共同聊天、记录记忆、创造私人暗号，并通过低压力的方式表达自己的状态。与传统社交软件不同，共屿不会把所有沟通都放进聊天框里，而是将抽象的关系变化转化为岛屿中真实可见的反馈：开心时岛屿放晴，难过时天空下雨；一段值得纪念的经历可以变成篝火、树木或长椅留在岛上；两个人之间特殊的称呼、表情和内部梗，则可以通过双方共同确认，逐渐形成一本只属于彼此的"私人词典"。\n\n随着相处时间增长，这座岛也会留下越来越多共同创造的痕迹。用户看到的不再是一串聊天记录，而是一段关系共同生活过的"数字空间"——某一天的天气、某一次互动、某个纪念物，都对应着真实发生过的情绪与记忆。\n\n项目同时尝试将数字关系延伸到现实世界。通过外接蓝牙实体按键，用户无需打开复杂界面，只需按下代表不同心情的按钮，就可以让双方共享岛屿的天气实时发生变化。例如，当一方心情低落时按下按键，另一方手机中的岛屿便会下起雨。这种"现实动作—数字环境—对方感知"的交互方式，让表达情绪不再必须依赖一段完整的文字，也降低了亲密关系中"我不知道该怎么说"的沟通压力。\n\n因此，共屿是一个以岛屿为媒介的关系共创空间。我们希望让那些只存在于两个人之间的语言、情绪和记忆拥有可以共同维护的载体，让一段关系不只是被记录，而是能够被看见、被感知，并随着两个人的相处持续生长。\n\n让每一段关系，都有一座属于它的岛。\n\n', demo_link=NULL, xiaohongshu_link=NULL, xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 11:00:54', is_late='1', created_at='2026-08-30 11:00:54', updated_at='2026-09-01 12:14:21', leader_participant_id='5519', presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='https://assets.shenicest.com/projects/event-management/99402/cover.png', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1kLdrisZevs-j6Izt5gC5Kw', github_repo_url='https://github.com/luyilin0816-beep/guanxi-island', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='160', reviewed_at='2026-08-30 11:21:00', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99402 AND event_id=4;
UPDATE projects SET event_id='4', team_id='282', captain_application_id='4862', topics='["miaoda_super", "liberlive_goodday", "proya_feelings", "qingxian_self", "bluebox_sleep", "eazo_4her", "insta360_hervision", "sappho_love"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='我小猫咪赛博重生', project_name='武皇明鉴——以武皇之智，破今日之局。', tagline='一款帮你在被 PUA、被操控、被拿捏时，一眼看穿套路、当场拿到反击话术的 AI 军师。以武则天的权谋智慧为人格，把千年识人驭人之术，变成普通人今天就能用的破局工具。', demo_order=NULL, project_description='【痛点】\n被 PUA、被情感勒索、被职场打压时，最让人无力的不是当下，而是"说不出哪不对劲，也想不出怎么回应"。市面上的产品，大多只能听你倾诉、给你安慰——却没人告诉你：这是什么套路，你该怎么破。\n\n【产品】\n武皇明鉴，是一位以武则天权谋智慧为人格的 AI 军师。\n她对局势冷静锐利，点破对方的算计绝不留情；对你却温暖托底，替你撑腰。你只需把困境说给她听——文字、语音、甚至多张聊天截图都行——剩下的交给她：\n识局：一眼看穿对方在用哪些套路，客观复盘。\n破局：从机会、能力、风险三个维度，给你可执行的破局方案与行动路径。\n论剑：对着扮演施压者的对手实战演练反击，练完为你逐招复盘、点评评分。\n修心：把每一次交锋炼成长久的底气，长成那个再不被人拿捏的自己。\n\n【为什么是武皇，而不是又一个 AI 助手】\n她的每一句判断，背后是大量自研的谋略、心理、沟通方法论，以及从多维度经典中提炼的智慧内核——古人的识人驭人之术，被重构成今天普通人就能用的破局能力。这不是让 AI 扮武则天说话，而是真的给了她一套军师的大脑。\n\n【价值主张 / 收尾】\n从"看懂"，到"练会"，到"变强"。\n谋于未兆，慎于未成——以武皇之智，破今日之局。\n\n', demo_link='https://3000-io2682gvdjjmieyesex8i.e2b.app', xiaohongshu_link=NULL, xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 11:15:00', is_late='1', created_at='2026-08-30 11:15:00', updated_at='2026-09-01 12:14:21', leader_participant_id='4862', presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='/platform/logo-shenicest-square.webp', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1KbSkcURFqcVhbyblS6p-5g?pwd=7vd2', github_repo_url='https://github.com/happymeow626/-', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='from_scratch', status='approved', reviewed_by='160', reviewed_at='2026-08-30 11:23:51', review_notes='', track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99403 AND event_id=4;
UPDATE projects SET event_id='4', team_id='257', captain_application_id='5117', topics='["miaoda_super", "eazo_4her", "ant_mulan_ai"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='凝莱', project_name='Wearchemy', tagline='把已有衣橱，温柔地炼成属于你的风格配方。', demo_order=NULL, project_description='面对日渐丰盈的衣橱，我们却依然常常困在"衣服很多，今天却不知道穿什么"的选择里。传统穿搭工具大多聚焦于新品推荐与消费转化，却鲜少真正理解用户已经拥有的衣物，也难以回应天气、场合、情绪、睡眠与身体节律交织而成的细微需求。\n\nWearchemy 由此诞生。我们希望让穿搭不再只是一次仓促的选择，而成为一段持续认识自我、表达自我的旅程：让沉睡在衣橱里的旧单品重新焕发生机，让每一次搭配都沉淀为可复用的风格经验，也让个人风格不再追随瞬息万变的潮流，而是在真实生活中自然生长。它既是一间懂你的数字衣橱，也是一座连接衣物、情绪与身体感受的个人风格实验室。', demo_link='http://111.62.156.213:10350', xiaohongshu_link=NULL, xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 11:51:15', is_late='1', created_at='2026-08-30 11:51:15', updated_at='2026-08-30 12:25:05', leader_participant_id='5117', presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='/platform/logo-shenicest-square.webp', screenshot_urls=NULL, video_link='https://b23.tv/iqyCdOj', github_repo_url='https://github.com/NIU-123370/Wearchemy', bom_link_text=NULL, gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='1', motherboard_csv_slot=NULL, scoring_profile='standard', status='approved', reviewed_by=NULL, reviewed_at=NULL, review_notes=NULL, track_code='软件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99404 AND event_id=4;
UPDATE projects SET event_id='4', team_id='42', captain_application_id='4518', topics='["proya_feelings"]', sponsor_consents=NULL, application_id=NULL, session=NULL, cohort=NULL, team_name='面部美学', project_name='SEEME', tagline='「让专业审美变成人人都能复刻的镜前能力」', demo_order=NULL, project_description='AI辅助智能妆造，利用硬件帮助人完成\n\nBOM:\n1. 震动马达模块 - 直流振动电机模块，3 针接口 x1 - 提供振动触觉反馈\n2. Arduino Nano I/O 扩展板 - 适配 Nano V3.0、ATmega328P x1 - 扩展接口，便于连接传感器和振动模块\n3. 彩色杜邦线 - 母对母，40P，2.54 mm 间距 x1 排（40 根）- 模块之间接线\n4. Arduino Nano V3.0 开发板 - ATmega328P、CH340、Type-C、焊排针 x1 - 主控制器\n5. 医用自粘弹性绷带 - 黑色，5 卷装 x1 包 - 固定腕带、模块或连接线\n6. USB 转 Type-C 数据线 - 白色编织线，约 1.5 m x1 - 开发板供电、程序下载或数据传输\n7. 8 通道肌电神经腕带 - 唯理，单腕带，蓝牙透传版 x1 - 采集肌电/手势信号并通过蓝牙传输\n\n项目文档: https://ycnfqpcp6v90.feishu.cn/wiki/QLRiwl2n4irxW6k81rocnlchn1f', demo_link=NULL, xiaohongshu_link=NULL, xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at='2026-08-30 12:27:29', is_late='1', created_at='2026-08-30 12:27:29', updated_at='2026-08-30 12:27:29', leader_participant_id='4518', presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url='/platform/logo-shenicest-square.webp', screenshot_urls=NULL, video_link='https://pan.baidu.com/s/1pjN_viAVi8HXcmPRyhgn0g?pwd=2n6t', github_repo_url='https://github.com/ziyu1617/-shenicest-fission', bom_link_text='| 序号 | 物料名称 | 规格/型号 | 数量 | 单价 | 用途/备注 |\n| 1 | 震动马达模块 | 直流振动电机模块，3 针接口 | 1 个 | (待补充) | 提供振动触觉反馈 |\n| 2 | Arduino Nano I/O 扩展板 | 适配 Nano V3.0、ATmega328P | 1 个 | (待补充) | 扩展接口，便于连接传感器和振动模块 |\n| 3 | 彩色杜邦线 | 母对母，40P，2.54 mm 间距 | 1 排（40 根） | (待补充) | 模块之间接线；长度需确认 |\n| 4 | Arduino Nano V3.0 开发板 | ATmega328P、CH340、Type-C、焊排针 | 1 个 | (待补充) | 主控制器，负责信号处理和设备控制 |\n| 5 | 医用自粘弹性绷带 | 黑色，5 卷装 | 1 包 | (待补充) | 固定腕带、模块或连接线；宽度需确认 |\n| 6 | USB 转 Type-C 数据线 | 白色编织线，约 1.5 m | 1 条 | (待补充) | 开发板供电、程序下载或数据传输 |\n| 7 | 8 通道肌电神经腕带 | 唯理，单腕带，蓝牙透传版 | 1 个 | (待补充) | 采集肌电/手势信号并通过蓝牙传输 |', gameplay_description=NULL, aigc_video_link=NULL, aigc_creative_thinking=NULL, demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='standard', status='approved', reviewed_by=NULL, reviewed_at=NULL, review_notes=NULL, track_code='硬件', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99405 AND event_id=4;
UPDATE projects SET event_id='4', team_id=NULL, captain_application_id='5259', topics=NULL, sponsor_consents=NULL, application_id=NULL, session='', cohort=NULL, team_name='Is you', project_name='Isyou', tagline='看见自己，也看见更多可能', demo_order=NULL, project_description='项目说明 一句话概括：Isyou 是一款面向多元神经群体的职业探索与成长 Coach，通过具体经历理解用户，把能力画像连接到真实岗位，并将职业差距转化为每天可以完成的小行动。 1. 问题 传统招聘和职业测评通常依赖“沟通能力强不强”“是否抗压”等抽象自评。这类表达容易忽略环境、任务结构和工作方式的差异，也会给不擅长自我包装的用户带来较高负担。 现有产品主要存在四个问题： 抽象标签多，用户很难准确描述自己。 岗位推荐只看职位名称，较少分析具体任务、规则和工作环境。 推荐结果缺少依据，用户不知道“为什么适合”。 培训内容通常是固定课程，没有根据个人差距和实际进度动态调整。 2. 方案 Isyou 将职业探索设计成一条可追溯的完整路径： 结构化能力探索 通过生活场景、具体经历和卡片选项收集信息，允许跳过、不确定和自由补充，不要求用户先给自己贴标签。 能力图谱 将回答整理为能力倾向、环境偏好、约束条件和待确认项。每条判断都尽量保留来源，未知信息不会被写成能力缺陷。 岗位匹配与真实岗位检索 从任务结构、环境要求和规则稳定性等维度匹配岗位，同时支持联网检索公开招聘页面、核验职位信息并导出选定 JD。 通用成长 Coach Coach 自动接收当前岗位、能力画像和岗位差距，依次生成 Gap Map、阶段计划和每日任务。用户提交结果后，系统将其保存为待复核证据，并在下一学习日先 Review，再调整后续任务。 3. 完成度 目前已经形成可以完整演示的端到端 Demo： 能力探索问卷与本地进度保存。 可追溯的能力图谱。 5 个稳定的演示岗位匹配结果。 真实岗位候选搜索、公开页面核验与 JD 下载。 岗位详情到通用 Coach 的上下文传递。 Gap Map、阶段计划、每日任务和多日 Review。 暂停、恢复、卡点反馈和任务降级。 前端与 Coach API 同源运行。 演示岗位与真实岗位明确区分。 20 项自动化测试全部通过。 GitHub 公开仓库和本地运行说明已完成。 当前仍属于 Hackathon Demo：Coach 会话主要保存在服务进程内存中，联网岗位搜索依赖外部 API、网络状态及招聘页面的可访问性。 4. 下一步 数据持久化 接入数据库和账号体系，长期保存画像、Coach 会话、任务记录与能力证据。 提高 Coach 个性化能力 在现有状态机和安全边界内接入可控的模型能力，使任务内容更贴合岗位、用户起点和历史反馈。 完善真实岗位链路 增加更多招聘来源、搜索缓存、异步任务、失败重试和岗位失效检测。 开展真实用户测试 邀请多元神经群体、职业顾问和招聘方参与测试，重点验证提问压力、推荐准确性和任务可执行性。 加强隐私与可访问性 完善数据授权、删除机制、日志脱敏、键盘操作、屏幕阅读器支持和低刺激视觉模式。 生产化部署 增加 HTTPS、监控告警、限流、数据库备份和模型成本控制，使项目从可演示 Demo 走向可持续使用的产品。', demo_link='https://github.com/Marukooo11/Isyou', xiaohongshu_link=NULL, xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at=NULL, is_late='0', created_at='2026-08-30 12:39:37', updated_at='2026-08-30 12:55:32', leader_participant_id='5259', presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url=NULL, screenshot_urls=NULL, video_link='https://github.com/Marukooo11/Isyou', github_repo_url='https://github.com/Marukooo11/Isyou', bom_link_text='', gameplay_description='', aigc_video_link='', aigc_creative_thinking='', demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='standard', status='approved', reviewed_by='159', reviewed_at='2026-08-30 12:55:32', review_notes='', track_code='software', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99406 AND event_id=4;
UPDATE projects SET event_id='4', team_id=NULL, captain_application_id='5460', topics=NULL, sponsor_consents=NULL, application_id=NULL, session='', cohort=NULL, team_name='SHE²', project_name='Normal World', tagline='“如果有一天，顺利只是正常的一天。”', demo_order=NULL, project_description='这个作品最开始来自一种很简单的感受：很多时候，女性在生活里遇到的不舒服，并不是特别戏剧化的大事，而是一些已经习惯到很容易被忽略的小事。比如求职时被默认问婚育、被认为某些工作“更适合男生”，又或者只是想多吃一点饭，也会被一句“女孩子吃不了这么多”替你做决定。 所以我们没有想把它做成一部很激烈的“对抗”作品，而是想拍一个普通女孩很普通的一天。 故事里的女主经历了一连串现实中并不罕见的事情，后来因为一只猫，意外进入了一个看起来格外“顺利”的一天。她发现，原来所谓的“爽剧”，可能只是没有被额外设限、没有被提前定义、可以按照自己的能力和需求生活而已。猫最后告诉她：“你只是过了正常的一天。”这句话也是我们最想留下来的东西。 在表达上，我们用了现实与平行世界的对照，但没有把人物简单分成好人和坏人。很多偏见本身就是以一种很自然、甚至“为你好”的方式存在，所以我们更想让观众自己感受到其中的差异。 AIGC在这个项目里不是单纯用来“做漂亮画面”的。我们用它完成角色统一、场景构建、镜头设计、动作与表演测试，也不断调整人物表情、空间逻辑、光线和镜头节奏，希望最终呈现出来的不是“AI生成感”，而是一部真正能让人进入情绪的短片。 团队里，我主要负责整体创意、剧本、叙事结构、视觉方向和AIGC生成把控；另一位成员负责剪辑以及后期节奏。整个过程其实就是不断推翻、重做、测试，再一点点把脑子里的那个世界变得可信。 我们希望它最后留下的不是一句“女性应该怎样”，而是一个更简单的问题： 为什么有些人习以为常的生活，对另一些人来说，却像一场爽剧？', demo_link='https://www.bilibili.com/video/BV1up4Q6YEv2', xiaohongshu_link=NULL, xiaohongshu_likes='0', hardware_requirements=NULL, submitted_at=NULL, is_late='0', created_at='2026-08-30 12:39:37', updated_at='2026-08-30 12:55:32', leader_participant_id='5460', presentation_link=NULL, presentation_storage_path=NULL, sheet_email=NULL, sheet_row=NULL, cover_image_url=NULL, screenshot_urls=NULL, video_link='https://b23.tv/Zx0PfPZ', github_repo_url='', bom_link_text='', gameplay_description='', aigc_video_link='https://pan.baidu.com/s/1c8x9ChiymyOwS97V7k4-IQ', aigc_creative_thinking='我们关注的是女性在日常生活中经常遇到、却容易被忽略的隐性偏见，例如求职中的性别预设、婚育询问、对女性需求的刻板判断等。相比直接说教，我们选择用一个“平行世界”的故事去呈现：女主经历了一天看似格外顺利的生活，直到猫告诉她——“你只是过了正常的一天。”通过现实与平行世界的对照，让观众自己感受到这些差异。 在方案上，我们将AIGC用于角色设计、场景搭建、分镜预演、图像生成、视频生成以及部分声音和后期辅助，并通过多轮迭代解决人物一致性、动作逻辑、空间关系、光线和表演自然度等问题，尽量降低“AI感”，让最终成片更接近真实电影叙事。 现场完成内容包括：完整短片的剧本、角色设定、主要场景和镜头设计，以及核心片段的AIGC生成与剪辑整合。最终作品以完整短片形式呈现，可直接播放观看。 使用方式上，观众无需了解AIGC技术背景，直接观看影片即可。我们希望它首先是一部能被看懂、能让人产生情绪和思考的短片，其次才是一件AIGC作品。', demo_completed='0', motherboard_csv_slot=NULL, scoring_profile='standard', status='approved', reviewed_by='159', reviewed_at='2026-08-30 12:55:32', review_notes='', track_code='aigc', finalist_rank=NULL, finalist_track=NULL, finalist_locked_at=NULL, iteration_source_url=NULL, iteration_plan=NULL, iteration_submitted_at=NULL, award_eligibility=NULL, is_alumni='0', alumni_status=NULL WHERE id=99407 AND event_id=4;
COMMIT;
